  tickers: string[],
  endDate: string,
): Promise<Map<string, RelativeStrengthRatioCoverageRow>> {
  const uniqueTickers = Array.from(new Set(
    tickers
      .map((ticker) => ticker.trim().toUpperCase())
      .filter(Boolean),
  ));
  const rowsByTicker = new Map<string, RelativeStrengthRatioCoverageRow>();
