    const placeholders = chunk.map(() => "?").join(",");
    const rows = await db.prepare(
      `SELECT ticker, MAX(trading_date) as lastDate, COUNT(*) as rowCount
       FROM rs_ratio_cache
       WHERE benchmark_ticker = ?
