export async function loadDailyBarCoverage(
  env: Env,
  tickers: string[],
  endDate: string,
): Promise<Map<string, DailyBarCoverageRow>> {
  const uniqueTickers = Array.from(new Set(
    tickers
      .map((ticker) => ticker.trim().toUpperCase())
      .filter(Boolean),
  ));
  const out = new Map<string, DailyBarCoverageRow>();
  if (uniqueTickers.length === 0) return out;
  if (env.EOD_READ_ENABLED === "true") {
    for (const [ticker, row] of await loadEodCatalogRows(env, uniqueTickers, endDate, { unavailableRows: "omit" })) {
      if (row.lastDate != null) out.set(ticker, { ticker, lastDate: row.lastDate, barCount: row.barCount });
    }
    return out;
  }
  const db = getMarketDataDb(env);
  const feed = marketDataFeed(env);
  for (let index = 0; index < uniqueTickers.length; index += RS_STORED_BAR_QUERY_CHUNK_SIZE) {
    const chunk = uniqueTickers.slice(index, index + RS_STORED_BAR_QUERY_CHUNK_SIZE);
    const placeholders = chunk.map(() => "?").join(",");
    const rows = await db.prepare(
      `SELECT ticker, MAX(date) as lastDate, COUNT(*) as barCount
       FROM alpaca_daily_bars
       WHERE feed = ?
         AND ticker IN (${placeholders})
         AND date <= ?
       GROUP BY ticker`,
    )
      .bind(feed, ...chunk, endDate)
      .all<DailyBarCoverageRow>();
    for (const row of rows.results ?? []) {
      out.set(row.ticker.toUpperCase(), {
        ticker: row.ticker.toUpperCase(),
        lastDate: row.lastDate,
        barCount: Number.isFinite(Number(row.barCount)) ? Number(row.barCount) : 0,
      });
    }
  }
  return out;
}

