): Promise<void> {
  await heartbeatManualRelativeStrengthRun(env, runId, {
    lastAttemptCursorOffset: candidate.cursorOffset,
    lastAttemptTicker: candidate.ticker,
    lastAttemptStage: stage,
    lastAttemptElapsedMs: Date.now() - startedAt,
