}

async function acquireManualRelativeStrengthRunLease(
  env: Env & { SCANNER_CACHE_DB: D1Database },
  run: ManualRelativeStrengthRunRecord,
): Promise<ManualRelativeStrengthRunRecord | null> {
  if (isManualRelativeStrengthRunLeaseActive(run)) return null;
  const leaseOwner = crypto.randomUUID();
  const leaseExpiresAt = new Date(Date.now() + MANUAL_RS_SCAN_LEASE_DURATION_MS).toISOString();
  await env.SCANNER_CACHE_DB.prepare(
    `UPDATE rs_scan_runs
     SET status = 'running',
         started_at = COALESCE(started_at, CURRENT_TIMESTAMP),
         updated_at = CURRENT_TIMESTAMP,
         heartbeat_at = CURRENT_TIMESTAMP,
         lease_owner = ?,
         lease_expires_at = ?
     WHERE id = ?
       AND status IN ('queued', 'running')
       AND (
         lease_owner IS NULL
         OR lease_expires_at IS NULL
         OR datetime(lease_expires_at) <= datetime('now')
       )`,
  )
    .bind(leaseOwner, leaseExpiresAt, run.id)
    .run();
  const leased = await loadManualRelativeStrengthRun(env, run.id);
  return leased?.leaseOwner === leaseOwner ? leased : null;
}

async function loadLatestCompletedPostCloseDailyBarRefreshAt(
  env: Env,
  tradingDate: string,
): Promise<number | null> {
  const row = await getOpsDb(env).prepare(
    `SELECT completed_at as completedAt
     FROM post_close_daily_bar_refresh_jobs
     WHERE scope = ?
       AND trading_date = ?
       AND status = 'completed'
       AND completed_at IS NOT NULL
     ORDER BY datetime(completed_at) DESC
     LIMIT 1`,
  )
    .bind(POST_CLOSE_DAILY_BARS_SCOPE, tradingDate)
    .first<{ completedAt: string | null }>();
  return toTimestampMs(row?.completedAt);
}

async function loadManualRelativeStrengthFeatureCacheRows(
  env: Env & { SCANNER_CACHE_DB: D1Database },
  configKey: string,
  tickers: string[],
): Promise<Map<string, ManualRelativeStrengthFeatureRow>> {
  const uniqueTickers = Array.from(new Set(tickers.map((ticker) => ticker.trim().toUpperCase()).filter(Boolean)));
  const rowsByTicker = new Map<string, ManualRelativeStrengthFeatureRow>();
  for (let index = 0; index < uniqueTickers.length; index += RS_STORED_BAR_QUERY_CHUNK_SIZE) {
    const chunk = uniqueTickers.slice(index, index + RS_STORED_BAR_QUERY_CHUNK_SIZE);
    const placeholders = chunk.map(() => "?").join(",");
    const rows = await env.SCANNER_CACHE_DB.prepare(
      `SELECT
         config_key as configKey,
         ticker,
         expected_trading_date as expectedTradingDate,
         trading_date as tradingDate,
         benchmark_ticker as benchmarkTicker,
         rs_ma_type as rsMaType,
         rs_ma_length as rsMaLength,
         new_high_lookback as newHighLookback,
         price_close as priceClose,
         change_1d as change1d,
         rs_ratio_close as rsRatioClose,
         rs_ratio_ma as rsRatioMa,
         rs_above_ma as rsAboveMa,
         rs_new_high as rsNewHigh,
         rs_new_high_before_price as rsNewHighBeforePrice,
         bull_cross as bullCross,
         approx_rs_rating as approxRsRating,
         status,
         reason,
         computed_at as computedAt
       FROM rs_features_latest
       WHERE config_key = ?
         AND ticker IN (${placeholders})`,
    )
      .bind(configKey, ...chunk)
      .all<ManualRelativeStrengthFeatureRow>();
    for (const row of rows.results ?? []) {
      rowsByTicker.set(row.ticker.toUpperCase(), {
        ...row,
        ticker: row.ticker.toUpperCase(),
        benchmarkTicker: row.benchmarkTicker.toUpperCase(),
        rsMaType: normalizeRsMaType(row.rsMaType),
        rsMaLength: Math.max(1, Math.trunc(Number(row.rsMaLength || 21))),
        newHighLookback: Math.max(1, Math.trunc(Number(row.newHighLookback || 252))),
      });
    }
  }
  return rowsByTicker;
}

function isReusableManualRelativeStrengthFeature(
  row: ManualRelativeStrengthFeatureRow | undefined,
  identity: RelativeStrengthConfigIdentity,
  invalidatedAfterMs: number | null,
): row is ManualRelativeStrengthFeatureRow {
  if (!row) return false;
  const expectedTradingDate = row.expectedTradingDate ?? row.tradingDate;
  if (expectedTradingDate !== identity.expectedTradingDate) return false;
  const computedAtMs = toTimestampMs(row.computedAt);
  if (invalidatedAfterMs != null && computedAtMs != null && computedAtMs < invalidatedAfterMs) return false;
  if (row.status === "computed") return row.tradingDate === identity.expectedTradingDate;
  return row.status === "missing_bars" || row.status === "insufficient_history" || row.status === "stale_benchmark";
}

function cachedManualRelativeStrengthResult(
  candidate: ManualRelativeStrengthCandidateRow,
  feature: ManualRelativeStrengthFeatureRow,
): {
  candidate: ManualRelativeStrengthCandidateRow;
  status: ManualRelativeStrengthTickerStatus;
  reason: string | null;
  latestTradingDate: string | null;
  price: number | null;
  change1d: number | null;
  avgVolume: number | null;
  relativeVolume: number | null;
  priceAvgVolume: number | null;
  feature: RelativeStrengthLatestCacheRecord | null;
  source: "cache";
} {
  const price = feature.priceClose ?? candidate.price ?? null;
  const avgVolume = candidate.avgVolume ?? null;
  return {
    candidate,
    status: feature.status as ManualRelativeStrengthTickerStatus,
    reason: feature.reason ?? null,
    latestTradingDate: feature.tradingDate ?? candidate.latestTradingDate ?? null,
    price,
    change1d: feature.change1d ?? candidate.change1d ?? null,
    avgVolume,
    relativeVolume: candidate.relativeVolume ?? null,
    priceAvgVolume: price != null && avgVolume != null ? price * avgVolume : candidate.priceAvgVolume ?? null,
    feature,
    source: "cache",
  };
}

function countManualRelativeStrengthBatchStatus(
  results: Array<{ status: ManualRelativeStrengthTickerStatus; source: "cache" | "computed" }>,
): Pick<ManualRelativeStrengthRunRecord, "cacheHitTickers" | "computedTickers" | "missingBarsTickers" | "insufficientHistoryTickers" | "errorTickers" | "staleBenchmarkTickers"> {
  return {
    cacheHitTickers: results.filter((result) => result.source === "cache").length,
    computedTickers: results.filter((result) => result.source === "computed" && result.status === "computed").length,
    missingBarsTickers: results.filter((result) => result.status === "missing_bars").length,
    insufficientHistoryTickers: results.filter((result) => result.status === "insufficient_history").length,
    errorTickers: results.filter((result) => result.status === "error").length,
    staleBenchmarkTickers: results.filter((result) => result.status === "stale_benchmark").length,
  };
}

function manualRelativeStrengthResultFromBars(
  candidate: ManualRelativeStrengthCandidateRow,
  tickerBars: RelativeStrengthDailyBar[],
  benchmarkBars: RelativeStrengthDailyBar[],
  identity: RelativeStrengthConfigIdentity,
  config: RelativeStrengthConfig,
  refreshAttempted: boolean,
): ManualRelativeStrengthBatchResult {
  try {
    const latestTickerDate = latestBarDate(tickerBars);
    const latest = tickerBars[tickerBars.length - 1] ?? null;
    const previous = tickerBars.length > 1 ? tickerBars[tickerBars.length - 2] : null;
    const avgVolume = averageVolume(tickerBars, 30);
    const latestVolume = latest == null ? null : Number((latest as { volume?: number }).volume ?? 0);
    const relativeVolume = avgVolume != null && latestVolume != null && avgVolume > 0 ? latestVolume / avgVolume : null;
    const priceAvgVolume = latest?.c != null && avgVolume != null ? latest.c * avgVolume : null;
    const change1d = latest && previous ? percentChange(latest.c, previous.c) : null;
    if (tickerBars.length === 0) {
      return {
        candidate,
        status: "missing_bars",
        reason: refreshAttempted
          ? "No stored daily bars are available for this ticker after bounded refresh."
          : "No stored daily bars are available for this ticker.",
        latestTradingDate: null,
        price: null,
        change1d: null,
        avgVolume,
        relativeVolume,
        priceAvgVolume,
        feature: null,
        source: "computed",
      };
    }
    if (latestTickerDate !== identity.expectedTradingDate) {
      return {
        candidate,
        status: "missing_bars",
        reason: refreshAttempted
          ? `Latest stored bar is ${latestTickerDate ?? "none"}; expected ${identity.expectedTradingDate} after bounded refresh.`
          : `Latest stored bar is ${latestTickerDate ?? "none"}; expected ${identity.expectedTradingDate}.`,
        latestTradingDate: latestTickerDate,
        price: latest?.c ?? null,
        change1d,
        avgVolume,
        relativeVolume,
        priceAvgVolume,
        feature: null,
        source: "computed",
      };
    }
    if (tickerBars.length < Math.max(identity.rsMaLength, Math.min(identity.newHighLookback, identity.requiredBarCount))) {
      return {
        candidate,
        status: "insufficient_history",
        reason: `Only ${tickerBars.length} stored bars are available; ${identity.requiredBarCount} are preferred for this RS config.`,
        latestTradingDate: latestTickerDate,
        price: latest?.c ?? null,
        change1d,
        avgVolume,
        relativeVolume,
        priceAvgVolume,
        feature: null,
        source: "computed",
      };
    }
    const computedRows = buildRelativeStrengthCacheRows(tickerBars, benchmarkBars, config);
    const computed = computedRows[computedRows.length - 1] ?? null;
    if (!computed || computed.tradingDate !== identity.expectedTradingDate) {
      return {
        candidate,
        status: "missing_bars",
        reason: refreshAttempted
          ? "Ticker and benchmark bars could not be aligned through the expected session after bounded refresh."
          : "Ticker and benchmark bars could not be aligned through the expected session.",
        latestTradingDate: computed?.tradingDate ?? latestTickerDate,
        price: latest?.c ?? null,
        change1d,
        avgVolume,
        relativeVolume,
        priceAvgVolume,
        feature: null,
        source: "computed",
      };
    }
    return {
      candidate,
      status: "computed",
      reason: null,
      latestTradingDate: computed.tradingDate,
      price: computed.priceClose,
      change1d: computed.change1d,
      avgVolume,
      relativeVolume,
      priceAvgVolume,
      feature: {
        ticker: computed.ticker,
        benchmarkTicker: computed.benchmarkTicker,
        rsMaType: identity.rsMaType,
        rsMaLength: identity.rsMaLength,
        newHighLookback: identity.newHighLookback,
        tradingDate: computed.tradingDate,
        priceClose: computed.priceClose,
        change1d: computed.change1d,
        rsRatioClose: computed.rsClose,
        rsRatioMa: computed.rsMa,
        rsAboveMa: computed.rsAboveMa,
        rsNewHigh: computed.rsNewHigh,
        rsNewHighBeforePrice: computed.rsNewHighBeforePrice,
        bullCross: computed.bullCross,
        approxRsRating: computed.approxRsRating,
      },
      source: "computed",
    };
  } catch (error) {
    return {
      candidate,
      status: "error",
      reason: error instanceof Error ? error.message : "Failed to compute relative strength for this ticker.",
      latestTradingDate: null,
      price: null,
      change1d: null,
      avgVolume: null,
      relativeVolume: null,
      priceAvgVolume: null,
      feature: null,
      source: "computed",
    };
  }
}

function manualRelativeStrengthResultFromFeature(
  candidate: ManualRelativeStrengthCandidateRow,
  feature: RelativeStrengthLatestCacheRecord,
  metricBars: RelativeStrengthDailyBar[],
): ManualRelativeStrengthBatchResult {
  const latest = metricBars[metricBars.length - 1] ?? null;
  const previous = metricBars.length > 1 ? metricBars[metricBars.length - 2] : null;
  const avgVolume = averageVolume(metricBars, 30) ?? candidate.avgVolume ?? null;
  const latestVolume = latest == null ? null : Number((latest as { volume?: number }).volume ?? 0);
  const relativeVolume = avgVolume != null && latestVolume != null && avgVolume > 0
    ? latestVolume / avgVolume
    : candidate.relativeVolume ?? null;
  const price = feature.priceClose ?? latest?.c ?? candidate.price ?? null;
  return {
    candidate,
    status: "computed",
    reason: null,
    latestTradingDate: feature.tradingDate,
    price,
    change1d: feature.change1d ?? (latest && previous ? percentChange(latest.c, previous.c) : candidate.change1d ?? null),
    avgVolume,
    relativeVolume,
    priceAvgVolume: price != null && avgVolume != null ? price * avgVolume : candidate.priceAvgVolume ?? null,
    feature,
    source: "computed",
  };
}

async function buildManualRelativeStrengthIncrementalResult(
  env: Env & { SCANNER_CACHE_DB: D1Database },
  candidate: ManualRelativeStrengthCandidateRow,
  benchmarkBars: RelativeStrengthDailyBar[],
  identity: RelativeStrengthConfigIdentity,
): Promise<ManualRelativeStrengthBatchResult | null> {
  const rollout = rsStateV2Rollout(env);
  if (rollout.legacyWriteEnabled || !rollout.readEnabled) {
    await ensureRelativeStrengthRatioCacheCurrent(env, [candidate.ticker], benchmarkBars, identity);
  }
  await materializeRelativeStrengthTickers(env, identity, [candidate.ticker], benchmarkBars);
  const feature = (await loadRelativeStrengthEffectiveLatestCacheRows(
    env,
    identity.configKey,
    [candidate.ticker],
    identity.expectedTradingDate,
  )).get(candidate.ticker);
  if (!feature || feature.tradingDate !== identity.expectedTradingDate) return null;
  const metricBars = await loadStoredDailyBarsByCount(env, [candidate.ticker], identity.expectedTradingDate, 30);
  return manualRelativeStrengthResultFromFeature(candidate, feature, metricBars);
}

async function buildManualRelativeStrengthComputedResults(
  env: Env & { SCANNER_CACHE_DB: D1Database },
  candidates: ManualRelativeStrengthCandidateRow[],
  benchmarkBars: RelativeStrengthDailyBar[],
  identity: RelativeStrengthConfigIdentity,
  config: RelativeStrengthConfig,
  refreshAttempted: boolean,
): Promise<ManualRelativeStrengthBatchResult[]> {
  if (candidates.length === 0) return [];
  const barsByTicker = groupBarsByTicker(
    await loadStoredDailyBarsByCount(
      env,
      candidates.map((candidate) => candidate.ticker),
      identity.expectedTradingDate,
      identity.requiredBarCount,
    ),
  );
  return candidates.map((candidate) =>
    manualRelativeStrengthResultFromBars(
      candidate,
      barsByTicker.get(candidate.ticker) ?? [],
      benchmarkBars,
      identity,
      config,
      refreshAttempted,
    ),
  );
}

async function refreshManualRelativeStrengthCandidatesOnce(
  env: Env & { SCANNER_CACHE_DB: D1Database },
  candidates: ManualRelativeStrengthCandidateRow[],
  identity: RelativeStrengthConfigIdentity,
): Promise<void> {
  if (candidates.length === 0) return;
  try {
    await refreshDailyBarsIncremental(env, {
      tickers: candidates.map((candidate) => candidate.ticker),
      startDate: isoDateDaysBefore(identity.expectedTradingDate, calendarLookbackDaysForBars(identity.requiredBarCount)),
      endDate: identity.expectedTradingDate,
      provider: getProvider(env, { fallbackEnabled: false }),
      providerBatchSize: MANUAL_RS_SCAN_REFRESH_CHUNK_SIZE,
      continueOnError: true,
      target: "market",
    });
  } catch (error) {
    console.warn("manual relative strength bounded daily-bar refresh failed", {
      tickers: candidates.map((candidate) => candidate.ticker),
      expectedTradingDate: identity.expectedTradingDate,
      error,
    });
  }
}

async function buildManualRelativeStrengthUncachedTickerResult(
  env: Env & { SCANNER_CACHE_DB: D1Database },
  candidate: ManualRelativeStrengthCandidateRow,
  benchmarkBars: RelativeStrengthDailyBar[],
  identity: RelativeStrengthConfigIdentity,
  config: RelativeStrengthConfig,
  reportStage: (stage: ManualRelativeStrengthAttemptStage) => Promise<void>,
): Promise<ManualRelativeStrengthBatchResult> {
  await reportStage("coverage");
  const coverage = (await loadDailyBarCoverage(env, [candidate.ticker], identity.expectedTradingDate)).get(candidate.ticker);
  const hasCurrentBars = coverage?.lastDate === identity.expectedTradingDate;
  if (hasCurrentBars) {
    await reportStage("compute");
    try {
      const incrementalResult = await buildManualRelativeStrengthIncrementalResult(env, candidate, benchmarkBars, identity);
      if (incrementalResult) return incrementalResult;
    } catch (error) {
      console.warn("manual relative strength incremental cache fill failed; falling back to full-bar compute", {
        ticker: candidate.ticker,
        expectedTradingDate: identity.expectedTradingDate,
        error,
      });
    }
    await reportStage("bar_load");
    const [computed] = await buildManualRelativeStrengthComputedResults(
      env,
      [candidate],
      benchmarkBars,
      identity,
      config,
      false,
    );
    return computed ?? manualRelativeStrengthResultFromBars(candidate, [], benchmarkBars, identity, config, false);
  }

  await reportStage("compute");
  await refreshManualRelativeStrengthCandidatesOnce(env, [candidate], identity);
  await reportStage("bar_load");
  const [computed] = await buildManualRelativeStrengthComputedResults(
    env,
    [candidate],
    benchmarkBars,
    identity,
    config,
    true,
  );
  return computed ?? manualRelativeStrengthResultFromBars(candidate, [], benchmarkBars, identity, config, true);
}

async function buildManualRelativeStrengthSnapshotResult(
  env: Env & { SCANNER_CACHE_DB: D1Database },
  preset: ScanPreset,
  run: ManualRelativeStrengthRunRecord,
): Promise<{
  providerLabel: string;
  matchedRowCount: number;
  status: "ok" | "warning" | "error" | "empty";
  error: string | null;
  rows: ScanSnapshotRow[];
}> {
  const rows = await env.SCANNER_CACHE_DB.prepare(
    `SELECT
       t.cursor_offset as cursorOffset,
       t.ticker,
       t.name,
       t.sector,
       t.industry,
       t.exchange,
       t.asset_class as assetClass,
       t.market_cap as marketCap,
       t.relative_volume as relativeVolume,
       t.avg_volume as avgVolume,
       t.price_avg_volume as priceAvgVolume,
       t.price,
       t.change_1d as change1d,
       t.status,
       t.reason,
       t.latest_trading_date as latestTradingDate,
       t.source,
       ? as benchmarkTicker,
       ? as rsMaType,
       ? as rsMaLength,
       ? as newHighLookback,
       ? as expectedTradingDate,
       COALESCE(t.latest_trading_date, f.trading_date) as tradingDate,
       COALESCE(t.price, f.price_close) as priceClose,
       COALESCE(t.change_1d, f.change_1d) as featureChange1d,
       COALESCE(t.rs_ratio_close, f.rs_ratio_close) as rsRatioClose,
       COALESCE(t.rs_ratio_ma, f.rs_ratio_ma) as rsRatioMa,
       COALESCE(t.rs_above_ma, f.rs_above_ma) as rsAboveMa,
       COALESCE(t.rs_new_high, f.rs_new_high) as rsNewHigh,
       COALESCE(t.rs_new_high_before_price, f.rs_new_high_before_price) as rsNewHighBeforePrice,
       COALESCE(t.bull_cross, f.bull_cross) as bullCross,
       COALESCE(t.approx_rs_rating, f.approx_rs_rating) as approxRsRating,
       COALESCE(t.computed_at, f.computed_at) as computedAt
     FROM rs_scan_run_tickers t
     LEFT JOIN rs_features_latest f
       ON f.config_key = ?
      AND f.ticker = t.ticker
      AND f.expected_trading_date = ?
      AND f.status = 'computed'
     WHERE t.run_id = ?
       AND t.status = 'computed'
     ORDER BY t.cursor_offset ASC`,
  )
    .bind(
      run.benchmarkTicker,
      run.rsMaType,
      run.rsMaLength,
      run.newHighLookback,
      run.expectedTradingDate,
      run.configKey,
      run.expectedTradingDate,
      run.id,
    )
    .all<ManualRelativeStrengthCandidateRow & ManualRelativeStrengthFeatureRow & { featureChange1d: number | null }>();

  const scaleFactor = preset.verticalOffset * 100;
  const supportedRules = effectiveManualSnapshotRules(preset).filter(manualRuleFieldSupported);
  const skippedRuleWarning = manualRulesWarning(preset);
  const identity = buildRelativeStrengthConfigIdentity(preset, run.expectedTradingDate);
  const mergedRows = (rows.results ?? [])
    .map((row) => {
      const cacheRow: RelativeStrengthLatestCacheRecord = {
        ticker: row.ticker.toUpperCase(),
        benchmarkTicker: (row.benchmarkTicker ?? run.benchmarkTicker).toUpperCase(),
        rsMaType: normalizeRsMaType(row.rsMaType),
        rsMaLength: Math.max(1, Math.trunc(row.rsMaLength || 21)),
        newHighLookback: Math.max(1, Math.trunc(row.newHighLookback || 252)),
        tradingDate: row.tradingDate,
        priceClose: row.priceClose,
        change1d: row.featureChange1d ?? row.change1d,
        rsRatioClose: row.rsRatioClose,
        rsRatioMa: row.rsRatioMa,
        rsAboveMa: row.rsAboveMa,
        rsNewHigh: row.rsNewHigh,
        rsNewHighBeforePrice: row.rsNewHighBeforePrice,
        bullCross: row.bullCross,
        approxRsRating: row.approxRsRating,
      };
      if (!cachedRowMatchesOutputMode(cacheRow, preset.outputMode)) return null;
      const rsClose = cacheRow.rsRatioClose == null ? null : cacheRow.rsRatioClose * scaleFactor;
      const rsMa = cacheRow.rsRatioMa == null ? null : cacheRow.rsRatioMa * scaleFactor;
      const latestVolume = row.avgVolume != null && row.relativeVolume != null ? row.avgVolume * row.relativeVolume : null;
      const snapshotRow: ScanSnapshotRow = {
        ticker: row.ticker.toUpperCase(),
        name: row.name ?? row.ticker.toUpperCase(),
        sector: row.sector ?? null,
        industry: row.industry ?? null,
        change1d: cacheRow.change1d,
        marketCap: row.marketCap ?? null,
        relativeVolume: row.relativeVolume ?? null,
        price: cacheRow.priceClose,
        avgVolume: row.avgVolume ?? null,
        priceAvgVolume: row.priceAvgVolume ?? null,
        rsClose,
        rsMa,
        rsAboveMa: asBooleanFlag(cacheRow.rsAboveMa),
        rsNewHigh: asBooleanFlag(cacheRow.rsNewHigh),
        rsNewHighBeforePrice: asBooleanFlag(cacheRow.rsNewHighBeforePrice),
        bullCross: asBooleanFlag(cacheRow.bullCross),
        approxRsRating: cacheRow.approxRsRating,
        rawJson: JSON.stringify({
          benchmarkTicker: identity.benchmarkTicker,
          tradingDate: cacheRow.tradingDate,
          rsClose,
          rsMa,
          rsAboveMa: asBooleanFlag(cacheRow.rsAboveMa),
          rsNewHigh: asBooleanFlag(cacheRow.rsNewHigh),
          rsNewHighBeforePrice: asBooleanFlag(cacheRow.rsNewHighBeforePrice),
          bullCross: asBooleanFlag(cacheRow.bullCross),
          approxRsRating: cacheRow.approxRsRating,
          relative_volume_10d_calc: row.relativeVolume ?? null,
          latest_volume: latestVolume,
          exchange: row.exchange ?? null,
          type: manualCandidateType(row.assetClass),
        }),
      };
      const filterRow = manualRowToTradingViewRow(snapshotRow, row, latestVolume);
      return rowMatchesRules(filterRow, supportedRules) ? snapshotRow : null;
    })
    .filter((row): row is ScanSnapshotRow => Boolean(row));

  const sortedRows = sortSnapshotRows(mergedRows, preset.sortField, preset.sortDirection).slice(0, preset.rowLimit);

  return {
    providerLabel: RS_PROVIDER_LABEL,
    matchedRowCount: mergedRows.length,
    status: sortedRows.length > 0 ? (skippedRuleWarning ? "warning" : "ok") : "empty",
    error: skippedRuleWarning,
    rows: sortedRows,
  };
}

export async function publishRelativeStrengthPresetFromCompletedRun(
  env: Env & { SCANNER_CACHE_DB: D1Database },
  preset: ScanPreset,
  run: ManualRelativeStrengthRunRecord,
): Promise<ScanSnapshot | null> {
  if (run.status !== "completed") throw new Error("Only a completed relative strength generation can be published.");
  const identity = buildRelativeStrengthConfigIdentity(preset, run.expectedTradingDate);
  if (identity.configKey !== run.configKey) throw new Error("Relative strength generation config does not match the preset.");
  const result = await buildManualRelativeStrengthSnapshotResult(env, preset, run);
  const publicationId = await stageRelativeStrengthPublication(env, preset, run, result);
  const promoted = await env.SCANNER_CACHE_DB.batch([
    relativeStrengthPublicationPointerStatement(env.SCANNER_CACHE_DB, preset.id, publicationId),
  ]);
  inspectScannerCacheWriteResults(env, promoted, "rs-publication-promotion", { throwOnHalt: false });
  return loadLatestScansSnapshot(env, preset.id);
}

const RS_PUBLICATION_WRITE_CHUNK_SIZE = 50;

async function stageRelativeStrengthPublication(
  env: Env & { SCANNER_CACHE_DB: D1Database },
  preset: ScanPreset,
  run: ManualRelativeStrengthRunRecord,
  result: { matchedRowCount: number; status: "ok" | "warning" | "error" | "empty"; error: string | null; rows: ScanSnapshotRow[] },
): Promise<string> {
  const publicationId = crypto.randomUUID();
  const headerWrite = await env.SCANNER_CACHE_DB.prepare(
    `INSERT INTO rs_publications
      (id, preset_id, config_key, expected_trading_date, run_id, status, row_count, matched_row_count, warning, published_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)`,
  ).bind(publicationId, preset.id, run.configKey, run.expectedTradingDate, run.id, result.status,
    result.rows.length, result.matchedRowCount, result.error).run();
  inspectScannerCacheWriteResults(env, [headerWrite], "rs-publication-header");

  for (let offset = 0; offset < result.rows.length; offset += RS_PUBLICATION_WRITE_CHUNK_SIZE) {
    const chunk = result.rows.slice(offset, offset + RS_PUBLICATION_WRITE_CHUNK_SIZE);
    const memberWrites = await env.SCANNER_CACHE_DB.batch(chunk.map((row, index) =>
      env.SCANNER_CACHE_DB.prepare(
        "INSERT INTO rs_publication_tickers (publication_id, ticker, rank) VALUES (?, ?, ?)",
      ).bind(publicationId, row.ticker, offset + index)));
    inspectScannerCacheWriteResults(env, memberWrites, "rs-publication-members");
  }

  return publicationId;
}

export async function hasMatchingRelativeStrengthPublication(
  env: Env,
  presetId: string,
  configKey: string,
  expectedTradingDate: string,
): Promise<boolean> {
  if (!env.SCANNER_CACHE_DB) return false;
  const row = await env.SCANNER_CACHE_DB.prepare(
    `SELECT 1 as found FROM rs_preset_publications pointer
     JOIN rs_publications publication ON publication.id = pointer.publication_id
     JOIN rs_scan_runs run ON run.id = publication.run_id
     WHERE pointer.preset_id = ? AND publication.config_key = ? AND publication.expected_trading_date = ?
       AND publication.status != 'error' AND run.status = 'completed' LIMIT 1`,
  ).bind(presetId, configKey, expectedTradingDate).first<{ found: number }>();
  return Boolean(row?.found);
}

function relativeStrengthPublicationPointerStatement(
  db: D1Database,
  presetId: string,
  publicationId: string,
  completedRunId?: string,
): D1PreparedStatement {
  if (completedRunId) return db.prepare(
    `INSERT INTO rs_preset_publications (preset_id, publication_id, updated_at)
     SELECT ?, ?, CURRENT_TIMESTAMP WHERE EXISTS (SELECT 1 FROM rs_scan_runs WHERE id = ? AND status = 'completed')
     ON CONFLICT(preset_id) DO UPDATE SET publication_id = excluded.publication_id, updated_at = CURRENT_TIMESTAMP`,
  ).bind(presetId, publicationId, completedRunId);
  return db.prepare(
    `INSERT INTO rs_preset_publications (preset_id, publication_id, updated_at)
     VALUES (?, ?, CURRENT_TIMESTAMP)
     ON CONFLICT(preset_id) DO UPDATE SET publication_id = excluded.publication_id, updated_at = CURRENT_TIMESTAMP`,
  ).bind(presetId, publicationId);
}

async function listActiveRelativeStrengthPresetsForManualRunConfig(
  env: Env,
  run: ManualRelativeStrengthRunRecord,
  requestedPreset: ScanPreset,
): Promise<ScanPreset[]> {
  if (run.requestedBy !== "scheduled") return [requestedPreset];
  const presets = (await listScanPresets(env))
    .filter((preset) => preset.isActive && preset.scanType === "relative-strength")
    .filter((preset) => buildRelativeStrengthConfigIdentity(preset, run.expectedTradingDate).configKey === run.configKey);
  const byId = new Map<string, ScanPreset>();
  byId.set(requestedPreset.id, requestedPreset);
  for (const preset of presets) byId.set(preset.id, preset);
  return Array.from(byId.values());
}

async function completeManualRelativeStrengthRun(
  env: Env & { SCANNER_CACHE_DB: D1Database },
  preset: ScanPreset,
  run: ManualRelativeStrengthRunRecord,
  matchedTickers: number,
): Promise<ScanSnapshot | null> {
  if (run.requestedBy === "scheduled" && (
    run.cursorOffset !== run.totalTickers
    || run.processedTickers !== run.totalTickers
    || run.missingBarsTickers !== 0
    || run.staleBenchmarkTickers !== 0
    || run.errorTickers !== 0
  )) {
    throw new Error("Scheduled RS generation is incomplete or contains current-bar, benchmark, or ticker errors.");
  }
  const settings = await loadWorkerScheduleSettings(env);
  const targetPresets = settings.rsSharedConfigSnapshotFanoutEnabled
    ? await listActiveRelativeStrengthPresetsForManualRunConfig(env, run, preset)
    : [preset];
  let selectedSnapshotId: string | null = null;
  let selectedWarning: string | null = null;
  const staged: Array<{ preset: ScanPreset; publicationId: string }> = [];
  for (const targetPreset of targetPresets) {
    const result = await buildManualRelativeStrengthSnapshotResult(env, targetPreset, run);
    const snapshotId = await stageRelativeStrengthPublication(env, targetPreset, run, result);
    staged.push({ preset: targetPreset, publicationId: snapshotId });
    if (targetPreset.id === preset.id) {
      selectedSnapshotId = snapshotId;
      selectedWarning = result.error;
    }
  }
  const completion = env.SCANNER_CACHE_DB.prepare(
    `UPDATE rs_scan_runs SET status = 'completed', processed_tickers = ?, matched_tickers = ?, cursor_offset = ?,
       warning = ?, latest_snapshot_id = ?, duration_ms = ?, completed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP,
       heartbeat_at = CURRENT_TIMESTAMP, lease_owner = NULL, lease_expires_at = NULL
     WHERE id = ? AND status IN ('queued', 'running')
       AND lease_owner = ?
       AND datetime(lease_expires_at) > datetime('now')`,
  ).bind(run.totalTickers, matchedTickers, run.totalTickers, selectedWarning, selectedSnapshotId,
    elapsedMs(run.startedAt ?? run.createdAt), run.id, run.leaseOwner);
  const promoted = await env.SCANNER_CACHE_DB.batch([
    completion,
    ...staged.map(({ preset: targetPreset, publicationId }) =>
      relativeStrengthPublicationPointerStatement(env.SCANNER_CACHE_DB, targetPreset.id, publicationId, run.id)),
  ]);
  const completionChanges = Number((promoted[0]?.meta as { changes?: number } | undefined)?.changes);
  if (Number.isFinite(completionChanges) && completionChanges === 0) {
    console.warn("RS publication promotion skipped after lease loss", { runId: run.id, leaseOwner: run.leaseOwner });
    return null;
  }
  inspectScannerCacheWriteResults(env, promoted, "rs-publication-atomic-promotion", { throwOnHalt: false });
  try {
    await removeScannerCacheScanRunFromQueue(env, run.id);
  } catch (error) {
    console.warn("completed RS run queue cleanup failed", { runId: run.id, error });
  }
  try {
    return await loadLatestScansSnapshot(env, preset.id);
  } catch (error) {
    console.warn("completed RS publication hydration failed", { runId: run.id, presetId: preset.id, error });
    return null;
  }
}

function normalizeVcpRunRecord(row: VcpRunRecord): VcpRunRecord {
  return {
    ...row,
    totalTickers: Math.max(0, Math.trunc(Number(row.totalTickers ?? 0))),
    processedTickers: Math.max(0, Math.trunc(Number(row.processedTickers ?? 0))),
    matchedTickers: Math.max(0, Math.trunc(Number(row.matchedTickers ?? 0))),
    cursorOffset: Math.max(0, Math.trunc(Number(row.cursorOffset ?? 0))),
    cacheHitTickers: Math.max(0, Math.trunc(Number(row.cacheHitTickers ?? 0))),
    computedTickers: Math.max(0, Math.trunc(Number(row.computedTickers ?? 0))),
    missingBarsTickers: Math.max(0, Math.trunc(Number(row.missingBarsTickers ?? 0))),
    insufficientHistoryTickers: Math.max(0, Math.trunc(Number(row.insufficientHistoryTickers ?? 0))),
    errorTickers: Math.max(0, Math.trunc(Number(row.errorTickers ?? 0))),
    durationMs: row.durationMs == null ? null : Math.max(0, Math.trunc(Number(row.durationMs))),
  };
}

function mapVcpRunRecordToJob(record: VcpRunRecord): ScanRefreshJob {
  const computedElapsedMs = elapsedMs(record.startedAt ?? record.createdAt);
  const terminal = isTerminalScanStatus(record.status);
  return {
    id: record.id,
    presetId: record.presetId,
    presetName: record.presetName,
    jobType: "vcp",
    status: record.status,
    startedAt: record.startedAt ?? record.createdAt,
    updatedAt: record.heartbeatAt ?? record.updatedAt,
    completedAt: record.completedAt,
    error: record.error,
    totalCandidates: record.totalTickers,
    processedCandidates: record.processedTickers,
    matchedCandidates: record.matchedTickers,
    cursorOffset: record.cursorOffset,
    latestSnapshotId: record.latestSnapshotId,
    requestedBy: record.requestedBy,
    configKey: record.configKey,
    sharedRunId: null,
    expectedTradingDate: record.expectedTradingDate,
    fullCandidateCount: record.totalTickers,
    materializationCandidateCount: record.totalTickers,
    alreadyCurrentCandidateCount: 0,
    lastAdvancedAt: record.heartbeatAt ?? record.updatedAt,
    deferredTickerCount: 0,
    warning: record.warning,
    phase: terminal ? record.status : "vcp",
    lastProgressAt: record.heartbeatAt ?? record.updatedAt,
    lastAttemptCursorOffset: null,
    lastAttemptTicker: null,
    lastAttemptStage: null,
    lastAttemptElapsedMs: null,
    elapsedMs: terminal ? record.durationMs ?? computedElapsedMs : computedElapsedMs,
    durationMs: record.durationMs ?? (terminal ? computedElapsedMs : null),
    cacheHitCount: record.cacheHitTickers,
    computedCount: record.computedTickers,
    missingBarsCount: record.missingBarsTickers,
    insufficientHistoryCount: record.insufficientHistoryTickers,
    errorCount: record.errorTickers,
    staleBenchmarkCount: 0,
    appliesToPreset: true,
  };
}

