  };
}

async function cancelLegacyRelativeStrengthRefreshJob(
  env: Env,
  record: ScanRefreshJobRecord,
): Promise<{ job: ScanRefreshJob; snapshot: ScanSnapshot | null } | null> {
  const preset = await loadScanPreset(env, record.presetId);
  if (!preset) return null;
  if (!isTerminalScanStatus(record.status)) {
    await updateScanRefreshJobRecord(env, record.id, {
      status: "cancelled",
      error: null,
      warning: "Cancelled by user.",
      phase: "cancelled",
      completedAt: new Date().toISOString(),
      lastAdvancedAt: new Date().toISOString(),
    });
    await removeRelativeStrengthRefreshJobFromQueue(env, record.id);
    if (record.sharedRunId) {
      const activeJobs = await listScanRefreshJobRecordsForSharedRun(env, record.sharedRunId, { activeOnly: true });
      if (activeJobs.length === 0) {
        const sharedRun = await loadRelativeStrengthMaterializationRun(env, record.sharedRunId);
        if (sharedRun && isActiveScanStatus(sharedRun.status)) {
          await updateRelativeStrengthMaterializationRun(env, sharedRun.id, {
            status: "cancelled",
            error: null,
            warning: "Cancelled by user.",
            phase: "cancelled",
            completedAt: new Date().toISOString(),
            leaseOwner: null,
            leaseExpiresAt: null,
            heartbeatAt: new Date().toISOString(),
          });
          await removeRelativeStrengthMaterializationRunFromQueue(env, sharedRun.id);
        }
      }
    }
  }
  const updated = await loadScanRefreshJobRecord(env, record.id);
  return {
    job: mapJobRecordToJob(updated ?? record, preset),
    snapshot: await loadLatestUsableScansSnapshot(env, preset.id),
  };
}

export async function cancelScanRefreshJob(
  env: Env,
  jobId: string,
): Promise<{ job: ScanRefreshJob; snapshot: ScanSnapshot | null } | null> {
  const manualRun = await loadManualRelativeStrengthRun(env, jobId);
  if (manualRun && hasScannerCacheStorage(env)) return cancelManualRelativeStrengthRun(env, manualRun);
  const vcpRun = await loadVcpRun(env, jobId);
  if (vcpRun && hasScannerCacheStorage(env)) return cancelVcpScanRun(env, vcpRun);
  const record = await loadScanRefreshJobRecord(env, jobId);
  if (!record) return null;
  return cancelLegacyRelativeStrengthRefreshJob(env, record);
}

export async function loadLatestActiveScanRefreshJob(
  env: Env,
  presetId: string,
): Promise<{ job: ScanRefreshJob; snapshot: ScanSnapshot | null } | null> {
  const preset = await loadScanPreset(env, presetId);
  if (!preset) return null;
  if (preset.scanType === "vcp") {
    const identity = buildVcpConfigIdentity(preset);
    const activeRun = await loadActiveVcpRun(env);
    if (activeRun) {
      return {
        job: mapVcpRunRecordToJob(activeRun),
        snapshot: await loadLatestUsableScansSnapshot(env, preset.id),
      };
    }
    const completed = await loadLatestCompletedVcpRunForPreset(env, preset.id, identity.configKey, identity.expectedTradingDate);
    if (!completed) return null;
    return {
      job: mapVcpRunRecordToJob(completed),
      snapshot: await loadLatestUsableScansSnapshot(env, preset.id),
    };
  }
  if (preset.scanType !== "relative-strength") return null;
  const identity = buildRelativeStrengthConfigIdentity(preset);
  const manualRun = await loadActiveManualRelativeStrengthRun(env);
  if (manualRun) {
    const appliesToPreset = manualRun.configKey === identity.configKey;
    return {
      job: mapManualRunRecordToJob(manualRun, { appliesToPreset }),
      snapshot: await loadLatestUsableScansSnapshot(env, preset.id),
    };
  }
  if (hasScannerCacheStorage(env)) {
    const completed = await loadLatestCompletedManualRelativeStrengthRunForConfig(env, identity.configKey);
    if (!completed) return null;
    return {
      job: mapManualRunRecordToJob(completed, { appliesToPreset: true }),
      snapshot: await loadLatestUsableScansSnapshot(env, preset.id),
    };
  }
  const record = await loadLatestScanRefreshJobRecordForPreset(env, presetId, { activeOnly: true });
  if (!record) return null;
  return {
    job: mapJobRecordToJob(record, preset),
    snapshot: await loadLatestUsableScansSnapshot(env, preset.id),
  };
}

export async function processQueuedRelativeStrengthRefreshJobs(
  env: Env,
  options?: { timeBudgetMs?: number; maxBatches?: number; batchSize?: number },
): Promise<ScanRefreshJob[]> {
  const startedAt = Date.now();
  const totalTimeBudgetMs = Math.max(1_000, options?.timeBudgetMs ?? RS_JOB_TIME_BUDGET_MS);
  let remainingBatches = options?.maxBatches == null
    ? Number.POSITIVE_INFINITY
    : Math.max(1, options.maxBatches);
  const processedByJobId = new Map<string, ScanRefreshJob>();
  const runBatchBurst = Math.max(1, Math.min(remainingBatches === Number.POSITIVE_INFINITY ? 3 : remainingBatches, 3));

  while (remainingBatches > 0 && Date.now() - startedAt < totalTimeBudgetMs) {
    const activeRuns = await listActiveRelativeStrengthMaterializationRuns(env);
    if (activeRuns.length === 0) break;
    const activeRunsById = new Map(activeRuns.map((run) => [run.id, run] as const));
    const queuedRows = await listQueuedRelativeStrengthMaterializationRuns(env);
    const queuedRunIds = new Set(queuedRows.map((row) => row.runId));
    for (const activeRun of activeRuns) {
      const staleThreshold = activeRun.status === "running" ? RS_JOB_RECOVERY_STALE_MS : RS_JOB_CONTINUATION_STALE_MS;
      if (!queuedRunIds.has(activeRun.id) && !isRelativeStrengthRunLeaseActive(activeRun) && runNeedsRelativeStrengthContinuation(activeRun, staleThreshold)) {
        await enqueueRelativeStrengthMaterializationRun(env, activeRun.id, "recovery");
      }
    }
    const refreshedQueue = await listQueuedRelativeStrengthMaterializationRuns(env);
    const runsToProcess = refreshedQueue
      .flatMap((row) => row.runId ? [activeRunsById.get(row.runId)] : [])
      .filter((run): run is RelativeStrengthMaterializationRunRecord => run != null && !isRelativeStrengthRunLeaseActive(run));
    if (runsToProcess.length === 0) break;

    let advancedAny = false;
    for (const activeRun of runsToProcess) {
      if (remainingBatches <= 0 || Date.now() - startedAt >= totalTimeBudgetMs) break;
      const remainingTimeBudgetMs = Math.max(1_000, totalTimeBudgetMs - (Date.now() - startedAt));
      await markRelativeStrengthMaterializationRunQueueAttempt(env, activeRun.id);
      const batchBurst = remainingBatches === Number.POSITIVE_INFINITY
        ? runBatchBurst
        : Math.max(1, Math.min(runBatchBurst, remainingBatches));
      const processedRun = await processRelativeStrengthMaterializationRun(env, activeRun.id, {
        maxBatches: batchBurst,
        timeBudgetMs: remainingTimeBudgetMs,
        batchSize: options?.batchSize,
      });
      if (!processedRun) continue;

      const advanced = processedRun.status === "completed"
        || processedRun.status === "failed"
        || processedRun.processedCandidates > activeRun.processedCandidates
        || processedRun.cursorOffset > activeRun.cursorOffset;
      if (advanced) {
        remainingBatches -= batchBurst;
        advancedAny = true;
      }
      const attachedJobs = await listScanRefreshJobRecordsForSharedRun(env, processedRun.id);
      for (const job of attachedJobs) {
        const preset = await loadScanPreset(env, job.presetId);
        if (!preset) continue;
        const refreshedJob = await loadScanRefreshJobRecord(env, job.id);
        if (!refreshedJob) continue;
        processedByJobId.set(job.id, mapJobRecordToJob(refreshedJob, preset));
      }
    }

    if (!advancedAny) break;
  }

  return Array.from(processedByJobId.values());
}

export async function refreshActiveRelativeStrengthPresets(
  env: Env,
  options?: { timeBudgetMs?: number; maxBatches?: number; batchSize?: number },
): Promise<ScanRefreshJob[]> {
  const presets = (await listScanPresets(env))
    .filter((preset) => preset.isActive && preset.scanType === "relative-strength");
  const presetIds = new Set(presets.map((preset) => preset.id));
  const completedJobsByPresetId = new Map<string, ScanRefreshJobRecord>();
  for (const preset of presets) {
    const identity = buildRelativeStrengthConfigIdentity(preset);
    const completed = await loadLatestCompletedScanRefreshJobRecordForPreset(env, preset.id, identity.expectedTradingDate);
    if (completed) {
      completedJobsByPresetId.set(preset.id, completed);
      continue;
    }
    const active = await loadLatestScanRefreshJobRecordForPreset(env, preset.id, { activeOnly: true });
    if (!active) {
      await requestScansRefresh(env, preset.id, "scheduled");
    }
  }
  const jobs = await processQueuedRelativeStrengthRefreshJobs(env, options);
  for (const preset of presets) {
    const identity = buildRelativeStrengthConfigIdentity(preset);
    const completed = completedJobsByPresetId.get(preset.id)
      ?? await loadLatestCompletedScanRefreshJobRecordForPreset(env, preset.id, identity.expectedTradingDate);
    if (completed) {
      completedJobsByPresetId.set(preset.id, completed);
    }
  }
  for (const preset of presets) {
    const completed = completedJobsByPresetId.get(preset.id);
    if (!completed) continue;
    await ensureRelativeStrengthSnapshotCurrent(env, preset, completed);
  }
  return jobs.filter((job) => presetIds.has(job.presetId));
}

type ScanSnapshotHeader = {
  id: string;
  presetId: string;
  providerLabel: string;
  generatedAt: string;
  rowCount: number;
  matchedRowCount: number;
  status: "ok" | "warning" | "error" | "empty";
  error: string | null;
};

async function loadLatestScanSnapshotHeader(
  env: Env,
  presetId: string,
  options?: { usableOnly?: boolean },
): Promise<ScanSnapshotHeader | null> {
  const clauses = ["preset_id = ?"];
  if (options?.usableOnly) clauses.push("status != 'error'");
  return env.DB.prepare(
    `SELECT
       id,
       preset_id as presetId,
       provider_label as providerLabel,
       generated_at as generatedAt,
       row_count as rowCount,
       COALESCE(matched_row_count, row_count) as matchedRowCount,
       status,
       error
     FROM scan_snapshots
     WHERE ${clauses.join(" AND ")}
     ORDER BY datetime(generated_at) DESC
     LIMIT 1`,
  )
    .bind(presetId)
    .first<ScanSnapshotHeader>();
}

async function loadScanSnapshotRows(env: Env, snapshotId: string): Promise<ScanSnapshotRow[]> {
  const rows = await env.DB.prepare(
    "SELECT ticker, name, sector, industry, change_1d as change1d, market_cap as marketCap, price, avg_volume as avgVolume, price_avg_volume as priceAvgVolume, raw_json as rawJson FROM scan_rows WHERE snapshot_id = ? ORDER BY change_1d DESC, ticker ASC",
  )
    .bind(snapshotId)
    .all<{
      ticker: string;
      name: string | null;
      sector: string | null;
      industry: string | null;
      change1d: number | null;
      marketCap: number | null;
      price: number | null;
      avgVolume: number | null;
      priceAvgVolume: number | null;
      rawJson: string | null;
    }>();
  return deserializeStoredScanRows(rows.results ?? []);
}

async function hydrateScanSnapshot(
  env: Env,
  preset: ScanPreset,
  snapshot: ScanSnapshotHeader,
): Promise<ScanSnapshot> {
  const rows = await loadScanSnapshotRows(env, snapshot.id);
  return {
    id: snapshot.id,
    presetId: preset.id,
    presetName: preset.name,
    providerLabel: snapshot.providerLabel,
    generatedAt: snapshot.generatedAt,
    rowCount: snapshot.rowCount,
    matchedRowCount: snapshot.matchedRowCount,
    status: snapshot.status,
    error: snapshot.error,
    rows: sortSnapshotRows(rows, preset.sortField, preset.sortDirection),
  };
}

export async function refreshScansSnapshot(env: Env, presetId?: string | null): Promise<ScanSnapshot> {
  const preset = presetId ? await loadScanPreset(env, presetId) : await loadDefaultScanPreset(env);
  if (!preset) throw new Error("No scan preset is configured.");

  if (preset.scanType === "relative-strength") {
    const response = await requestScansRefresh(env, preset.id, "sync-refresh");
    if (response.snapshot) return response.snapshot;
    if (response.job) {
      throw new Error(`Relative strength cache materialization is ${response.job.status} for ${response.job.expectedTradingDate ?? "the latest session"}.`);
    }
    throw new Error("Relative strength refresh could not load a snapshot.");
  }

  if (preset.scanType === "vcp") {
    const response = await requestScansRefresh(env, preset.id, "sync-refresh");
    if (response.snapshot) return response.snapshot;
    if (response.job) {
      throw new Error(`VCP scan is ${response.job.status} for ${response.job.expectedTradingDate ?? "the latest session"}.`);
    }
    throw new Error("VCP refresh could not load a snapshot.");
  }

  try {
    const result = await fetchTradingViewScanRows(preset, undefined, env);
    await upsertSymbolsFromRows(env, result.rows);
    await storeScanSnapshotResult(env, preset, result);
  } catch (error) {
    const message = normalizeScanStorageError(error);
    if (isCoreDatabaseCapacityError(error)) {
      return {
        id: crypto.randomUUID(),
        presetId: preset.id,
        presetName: preset.name,
        providerLabel: TV_PROVIDER_LABEL,
        generatedAt: new Date().toISOString(),
        rowCount: 0,
        matchedRowCount: 0,
        status: "error",
        error: message,
        rows: [],
      };
    }
    try {
      const errorWrite = await env.DB.prepare(
        "INSERT INTO scan_snapshots (id, preset_id, provider_label, generated_at, row_count, matched_row_count, status, error) VALUES (?, ?, ?, CURRENT_TIMESTAMP, 0, 0, 'error', ?)",
      )
        .bind(crypto.randomUUID(), preset.id, TV_PROVIDER_LABEL, message)
        .run();
      inspectCoreDatabaseSize(env, errorWrite.meta?.size_after, "scan-snapshot-error-write");
    } catch (writeError) {
      if (!isCoreDatabaseCapacityError(writeError)) throw writeError;
      return {
        id: crypto.randomUUID(),
        presetId: preset.id,
        presetName: preset.name,
        providerLabel: TV_PROVIDER_LABEL,
        generatedAt: new Date().toISOString(),
        rowCount: 0,
        matchedRowCount: 0,
        status: "error",
        error: normalizeScanStorageError(writeError),
        rows: [],
      };
    }
  }

  const snapshot = await loadLatestScansSnapshot(env, preset.id);
  if (!snapshot) throw new Error("Failed to load refreshed scan snapshot.");
  return snapshot;
}

export async function loadLatestScansSnapshot(env: Env, presetId?: string | null): Promise<ScanSnapshot | null> {
  const preset = presetId ? await loadScanPreset(env, presetId) : await loadDefaultScanPreset(env);
  if (!preset) return null;
  if (preset.scanType === "relative-strength" && env.SCANNER_CACHE_DB) {
    const publication = await loadRelativeStrengthPublicationSnapshot(env as Env & { SCANNER_CACHE_DB: D1Database }, preset);
    if (publication) return publication;
  }
  const snapshot = await loadLatestScanSnapshotHeader(env, preset.id);
  if (!snapshot) return null;
  return hydrateScanSnapshot(env, preset, snapshot);
}

export async function loadLatestUsableScansSnapshot(env: Env, presetId?: string | null): Promise<ScanSnapshot | null> {
  const preset = presetId ? await loadScanPreset(env, presetId) : await loadDefaultScanPreset(env);
  if (!preset) return null;
  if (preset.scanType === "relative-strength" && env.SCANNER_CACHE_DB) {
    const publication = await loadRelativeStrengthPublicationSnapshot(env as Env & { SCANNER_CACHE_DB: D1Database }, preset, true);
    if (publication) return publication;
  }
  const snapshot = await loadLatestScanSnapshotHeader(env, preset.id, { usableOnly: true });
  if (!snapshot) return null;
  return hydrateScanSnapshot(env, preset, snapshot);
}

function scannerPublicationTablesMissing(error: unknown): boolean {
  const message = String(error instanceof Error ? error.message : error).toLowerCase();
  return /no such (?:table|column):?[^\n]*(?:rs_publications|rs_publication_tickers|rs_preset_publications)/.test(message);
}

export function scaleRelativeStrengthPublicationValue(value: unknown, verticalOffset: number): number | null {
  if (value == null) return null;
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric * verticalOffset * 100 : null;
}

async function loadRelativeStrengthPublicationSnapshot(
  env: Env & { SCANNER_CACHE_DB: D1Database },
  preset: ScanPreset,
  usableOnly = false,
): Promise<ScanSnapshot | null> {
  try {
    const publication = await env.SCANNER_CACHE_DB.prepare(
      `SELECT p.id, p.published_at as generatedAt, p.row_count as rowCount,
         p.matched_row_count as matchedRowCount, p.status, p.warning as error, p.run_id as runId,
         r.benchmark_ticker as benchmarkTicker
       FROM rs_preset_publications pointer
       JOIN rs_publications p ON p.id = pointer.publication_id
       JOIN rs_scan_runs r ON r.id = p.run_id
       WHERE pointer.preset_id = ? ${usableOnly ? "AND p.status != 'error'" : ""}
       LIMIT 1`,
    ).bind(preset.id).first<ScanSnapshotHeader & { runId: string; benchmarkTicker: string }>();
    if (!publication) return null;
    const rows = await env.SCANNER_CACHE_DB.prepare(
      `SELECT t.ticker, t.name, t.sector, t.industry, t.change_1d as change1d, t.market_cap as marketCap,
         t.relative_volume as relativeVolume, t.price, t.avg_volume as avgVolume, t.price_avg_volume as priceAvgVolume,
         t.rs_ratio_close as rsClose, t.rs_ratio_ma as rsMa, t.rs_above_ma as rsAboveMa,
         t.rs_new_high as rsNewHigh, t.rs_new_high_before_price as rsNewHighBeforePrice,
         t.bull_cross as bullCross, t.approx_rs_rating as approxRsRating, t.exchange, t.asset_class as assetClass,
         t.latest_trading_date as tradingDate
       FROM rs_publication_tickers m
       JOIN rs_scan_run_tickers t ON t.run_id = ? AND t.ticker = m.ticker
       WHERE m.publication_id = ? ORDER BY m.rank ASC`,
    ).bind(publication.runId, publication.id).all<Record<string, unknown>>();
    return {
      id: publication.id,
      presetId: preset.id,
      presetName: preset.name,
      providerLabel: RS_PROVIDER_LABEL,
      generatedAt: publication.generatedAt,
      rowCount: Number(publication.rowCount),
      matchedRowCount: Number(publication.matchedRowCount),
      status: publication.status,
      error: publication.error,
      rows: (rows.results ?? []).map((row) => ({
        ticker: String(row.ticker), name: row.name == null ? null : String(row.name),
        sector: row.sector == null ? null : String(row.sector), industry: row.industry == null ? null : String(row.industry),
        change1d: row.change1d == null ? null : Number(row.change1d), marketCap: row.marketCap == null ? null : Number(row.marketCap),
        relativeVolume: row.relativeVolume == null ? null : Number(row.relativeVolume), price: row.price == null ? null : Number(row.price),
        avgVolume: row.avgVolume == null ? null : Number(row.avgVolume), priceAvgVolume: row.priceAvgVolume == null ? null : Number(row.priceAvgVolume),
        rsClose: scaleRelativeStrengthPublicationValue(row.rsClose, preset.verticalOffset),
        rsMa: scaleRelativeStrengthPublicationValue(row.rsMa, preset.verticalOffset),
        rsAboveMa: asBooleanFlag(row.rsAboveMa), rsNewHigh: asBooleanFlag(row.rsNewHigh),
        rsNewHighBeforePrice: asBooleanFlag(row.rsNewHighBeforePrice), bullCross: asBooleanFlag(row.bullCross),
        approxRsRating: row.approxRsRating == null ? null : Number(row.approxRsRating),
        rawJson: JSON.stringify({ benchmarkTicker: publication.benchmarkTicker, tradingDate: row.tradingDate,
          exchange: row.exchange, type: row.assetClass, relative_volume_10d_calc: row.relativeVolume }),
      })),
    };
  } catch (error) {
    if (scannerPublicationTablesMissing(error)) return null;
    throw error;
  }
}

export type RelativeStrengthBackendReadiness = {
  status: "ready" | "building" | "stale" | "failed" | "waiting" | "unavailable";
  expectedTradingDate: string;
  readyTradingDate: string | null;
  processedTickers: number;
  totalTickers: number;
  progressPct: number;
  runId: string | null;
  runStartedAt: string | null;
  runUpdatedAt: string | null;
  publishedAt: string | null;
  warning: string | null;
  error: string | null;
  capacity: ScannerCacheCapacity;
};

export async function loadRelativeStrengthBackendReadiness(
  env: Env,
  preset: ScanPreset,
): Promise<RelativeStrengthBackendReadiness | null> {
  if (preset.scanType !== "relative-strength") return null;
  const expectedTradingDate = await resolveRelativeStrengthExpectedTradingDate(env);
  const capacity = await loadScannerCacheCapacity(env);
  const base = { expectedTradingDate, readyTradingDate: null, processedTickers: 0, totalTickers: 0, progressPct: 0,
    runId: null, runStartedAt: null, runUpdatedAt: null, publishedAt: null, warning: null, error: null, capacity };
  if (!env.SCANNER_CACHE_DB) return { ...base, status: "unavailable", error: "Scanner cache database is not configured." };
  try {
    const identity = buildRelativeStrengthConfigIdentity(preset, expectedTradingDate);
    const [run, publication] = await Promise.all([
      env.SCANNER_CACHE_DB.prepare(
        `SELECT id, status, processed_tickers as processedTickers, total_tickers as totalTickers,
           started_at as startedAt, updated_at as updatedAt, warning, error
         FROM rs_scan_runs WHERE config_key = ? ORDER BY datetime(created_at) DESC LIMIT 1`,
      ).bind(identity.configKey).first<{ id: string; status: string; processedTickers: number; totalTickers: number;
        startedAt: string | null; updatedAt: string; warning: string | null; error: string | null }>(),
      env.SCANNER_CACHE_DB.prepare(
        `SELECT p.config_key as configKey, p.expected_trading_date as readyTradingDate, p.published_at as publishedAt, p.warning
         FROM rs_preset_publications pointer JOIN rs_publications p ON p.id = pointer.publication_id
         WHERE pointer.preset_id = ? LIMIT 1`,
      ).bind(preset.id).first<{ configKey: string; readyTradingDate: string; publishedAt: string; warning: string | null }>(),
    ]);
    const totalTickers = Math.max(0, Number(run?.totalTickers ?? 0));
    const processedTickers = Math.max(0, Number(run?.processedTickers ?? 0));
    const progressPct = totalTickers > 0 ? Math.min(100, Math.round(processedTickers / totalTickers * 100)) : 0;
    let status: RelativeStrengthBackendReadiness["status"] = "waiting";
    if (publication?.readyTradingDate === expectedTradingDate && publication.configKey === identity.configKey) status = "ready";
    else if (run?.status === "queued" || run?.status === "running") status = "building";
    else if (run?.status === "failed" || run?.status === "cancelled") status = "failed";
    else if (publication) status = "stale";
    else if (capacity.status === "halt") status = "unavailable";
    return { status, expectedTradingDate, readyTradingDate: publication?.readyTradingDate ?? null,
      processedTickers, totalTickers, progressPct, runId: run?.id ?? null, runStartedAt: run?.startedAt ?? null,
      runUpdatedAt: run?.updatedAt ?? null, publishedAt: publication?.publishedAt ?? null,
      warning: run?.warning ?? publication?.warning ?? (capacity.status === "warning" ? "Scanner cache is nearing capacity." : null),
      error: run?.error ?? (capacity.status === "halt" ? "Scanner cache capacity halt threshold reached." : null), capacity };
  } catch (error) {
    if (scannerPublicationTablesMissing(error)) return { ...base, status: "unavailable", error: "RS publication storage is not migrated yet." };
    throw error;
  }
}

export async function loadCompiledScansSnapshot(
  env: Env,
  presetIds: string[],
  options?: { compilePresetId?: string | null; compilePresetName?: string | null },
): Promise<CompiledScansSnapshot> {
  const uniquePresetIds = Array.from(new Set(
    presetIds
      .map((value) => value.trim())
      .filter(Boolean),
  ));
  const presets = (await Promise.all(uniquePresetIds.map((presetId) => loadScanPreset(env, presetId))))
    .filter((preset): preset is ScanPreset => Boolean(preset));
  const snapshots = await Promise.all(presets.map((preset) => loadLatestUsableScansSnapshot(env, preset.id)));
  const rowMap = new Map<string, CompiledScanUniqueTickerRow>();
  const rowTimestampMap = new Map<string, string>();
  let latestGeneratedAt = "";

  snapshots.forEach((snapshot, index) => {
    if (!snapshot) return;
    const preset = presets[index];
    if (!preset) return;
    if (snapshot.generatedAt > latestGeneratedAt) latestGeneratedAt = snapshot.generatedAt;
    for (const row of snapshot.rows) {
      const existing = rowMap.get(row.ticker);
      if (!existing) {
        rowMap.set(row.ticker, {
          ticker: row.ticker,
          name: row.name,
          sector: row.sector,
          industry: row.industry,
          occurrences: 1,
          presetIds: [preset.id],
          presetNames: [preset.name],
          latestPrice: row.price,
          latestChange1d: row.change1d,
          latestMarketCap: row.marketCap,
          latestRelativeVolume: row.relativeVolume,
        });
        rowTimestampMap.set(row.ticker, snapshot.generatedAt);
        continue;
      }
      existing.occurrences += 1;
      if (!existing.name && row.name) existing.name = row.name;
      if (!existing.sector && row.sector) existing.sector = row.sector;
      if (!existing.industry && row.industry) existing.industry = row.industry;
      if (!existing.presetIds.includes(preset.id)) existing.presetIds.push(preset.id);
      if (!existing.presetNames.includes(preset.name)) existing.presetNames.push(preset.name);
      const currentTimestamp = rowTimestampMap.get(row.ticker) ?? "";
      if (snapshot.generatedAt >= currentTimestamp) {
        existing.latestPrice = row.price;
        existing.latestChange1d = row.change1d;
        existing.latestMarketCap = row.marketCap;
        existing.latestRelativeVolume = row.relativeVolume;
        rowTimestampMap.set(row.ticker, snapshot.generatedAt);
      }
    }
  });

  return {
    compilePresetId: options?.compilePresetId ?? null,
    compilePresetName: options?.compilePresetName ?? null,
    presetIds: presets.map((preset) => preset.id),
    presetNames: presets.map((preset) => preset.name),
    generatedAt: latestGeneratedAt || new Date().toISOString(),
    rows: Array.from(rowMap.values()).sort((a, b) => {
      if (b.occurrences !== a.occurrences) return b.occurrences - a.occurrences;
      const left = a.latestChange1d ?? Number.NEGATIVE_INFINITY;
      const right = b.latestChange1d ?? Number.NEGATIVE_INFINITY;
      if (right !== left) return right - left;
      return a.ticker.localeCompare(b.ticker);
    }),
  };
}

export async function loadCompiledScansSnapshotForCompilePreset(env: Env, compilePresetId: string): Promise<CompiledScansSnapshot> {
  const compilePreset = await loadScanCompilePreset(env, compilePresetId);
  if (!compilePreset) throw new Error("Scan compile preset not found.");
  return loadCompiledScansSnapshot(env, compilePreset.presetIds, {
    compilePresetId: compilePreset.id,
    compilePresetName: compilePreset.name,
  });
}

export async function refreshScanCompilePreset(env: Env, compilePresetId: string): Promise<ScanCompilePresetRefreshResult> {
  const compilePreset = await loadScanCompilePreset(env, compilePresetId);
  if (!compilePreset) throw new Error("Scan compile preset not found.");

  const memberResults: ScanCompilePresetRefreshMemberResult[] = [];
  for (const member of compilePreset.members) {
    const refreshResult = await requestScansRefresh(env, member.scanPresetId, "compile-refresh");
    const refreshedSnapshot = refreshResult.snapshot;
    const usableSnapshot = refreshResult.job?.status === "failed" || refreshedSnapshot?.status === "error"
      ? await loadLatestUsableScansSnapshot(env, member.scanPresetId)
      : (refreshedSnapshot ?? await loadLatestUsableScansSnapshot(env, member.scanPresetId));
    const memberStatus = refreshResult.job?.status === "failed"
      ? "error"
      : (refreshResult.job?.status ?? refreshedSnapshot?.status ?? "empty");
    memberResults.push({
      presetId: member.scanPresetId,
      presetName: member.scanPresetName,
      status: memberStatus as ScanCompilePresetRefreshMemberResult["status"],
      rowCount: usableSnapshot?.rowCount ?? 0,
      error: refreshResult.job?.error ?? refreshedSnapshot?.error ?? null,
      snapshot: refreshedSnapshot,
      usableSnapshot,
      usedFallback: memberStatus === "error" && Boolean(usableSnapshot),
      includedInCompiled: Boolean(usableSnapshot),
    });
  }

  const snapshot = await loadCompiledScansSnapshot(env, compilePreset.presetIds, {
    compilePresetId: compilePreset.id,
    compilePresetName: compilePreset.name,
  });

  return {
    compilePresetId: compilePreset.id,
    compilePresetName: compilePreset.name,
    refreshedCount: memberResults.filter((result) => result.status !== "error").length,
    failedCount: memberResults.filter((result) => result.status === "error").length,
    snapshot,
    memberResults,
  };
}

export type ScannerCacheRetentionStats = {
  examinedRuns: number;
  childRowsDeleted: number;
  completedRunsDeleted: number;
  queueRowsDeleted: number;
  compactRowsDeleted: number;
  publicationRowsDeleted: number;
  rowsWritten: number;
  cursor: string | null;
  stopReason: "complete" | "write_budget" | "safety_limit" | "scanner_cache_unavailable";
  durationMs: number;
};

type DeletableScannerRun = {
  id: string;
  runType: "relative-strength" | "vcp";
};

function d1RowsWritten(result: D1Result<unknown>): number {
  const meta = result.meta as unknown as { rows_written?: number; changes?: number } | undefined;
  return Math.max(0, Math.trunc(Number(meta?.rows_written ?? meta?.changes ?? 0)));
}

async function loadOldestDeletableScannerRun(
  db: D1Database,
  window: string,
): Promise<DeletableScannerRun | null> {
  return db.prepare(
    `SELECT id, run_type as runType
     FROM (
       SELECT r.id, 'relative-strength' as run_type, r.updated_at
       FROM rs_scan_runs r
       WHERE r.status IN ('completed', 'failed', 'cancelled')
         AND datetime(r.updated_at) < datetime('now', ?)
         AND NOT EXISTS (
           SELECT 1 FROM rs_publications publication
           WHERE publication.run_id = r.id
         )
         AND r.id != COALESCE((
           SELECT latest.id
           FROM rs_scan_runs latest
           WHERE latest.preset_id = r.preset_id AND latest.status = 'completed'
           ORDER BY datetime(COALESCE(latest.completed_at, latest.updated_at)) DESC, latest.id DESC
           LIMIT 1
         ), '')
       UNION ALL
       SELECT r.id, 'vcp' as run_type, r.updated_at
       FROM vcp_scan_runs r
       WHERE r.status IN ('completed', 'failed', 'cancelled')
         AND datetime(r.updated_at) < datetime('now', ?)
         AND r.id != COALESCE((
           SELECT latest.id
           FROM vcp_scan_runs latest
           WHERE latest.preset_id = r.preset_id AND latest.status = 'completed'
           ORDER BY datetime(COALESCE(latest.completed_at, latest.updated_at)) DESC, latest.id DESC
           LIMIT 1
         ), '')
     )
     ORDER BY datetime(updated_at) ASC, id ASC
     LIMIT 1`,
  ).bind(window, window).first<DeletableScannerRun>();
}

async function pruneInactiveRsStateV2(
  env: Env & { SCANNER_CACHE_DB: D1Database },
  window: string,
  writeBudget: number,
): Promise<number> {
  if (!legacyRsCacheRetired(env) || writeBudget <= 0) return 0;
  const activeConfigKeys = Array.from(new Set(
    (await listScanPresets(env))
      .filter((preset) => preset.isActive && preset.scanType === "relative-strength")
      .map((preset) => buildRelativeStrengthConfigIdentity(preset).configKey),
  ));
  const activePredicate = activeConfigKeys.length > 0
    ? `config_key NOT IN (${activeConfigKeys.map(() => "?").join(",")})`
    : "1 = 1";
  const bindPrefix = activeConfigKeys.length > 0 ? activeConfigKeys : [];
  let rowsWritten = 0;
  for (const target of [
    { table: "rs_state_latest", timestamp: "updated_at" },
    { table: "rs_features_latest", timestamp: "computed_at" },
  ] as const) {
    while (rowsWritten < writeBudget) {
      const limit = Math.min(1_000, writeBudget - rowsWritten);
      const result = await env.SCANNER_CACHE_DB.prepare(
        `DELETE FROM ${target.table}
         WHERE rowid IN (
           SELECT rowid
           FROM ${target.table}
           WHERE datetime(${target.timestamp}) < datetime('now', ?)
             AND ${activePredicate}
             AND NOT EXISTS (
               SELECT 1 FROM rs_scan_runs active
               WHERE active.status IN ('queued', 'running')
                 AND active.config_key = ${target.table}.config_key
             )
           ORDER BY datetime(${target.timestamp}) ASC
           LIMIT ?
         )`,
      ).bind(window, ...bindPrefix, limit).run();
      const changed = d1RowsWritten(result);
      rowsWritten += changed;
      if (changed === 0 || changed < limit) break;
    }
    if (rowsWritten >= writeBudget) break;
  }
  return rowsWritten;
}

export async function cleanupScannerCacheRunData(
  env: Env,
  retentionDays = RETENTION_DAYS,
  writeBudget = 5_000,
): Promise<ScannerCacheRetentionStats> {
  const startedAt = Date.now();
  const stats: ScannerCacheRetentionStats = {
    examinedRuns: 0,
    childRowsDeleted: 0,
    completedRunsDeleted: 0,
    queueRowsDeleted: 0,
    compactRowsDeleted: 0,
    publicationRowsDeleted: 0,
    rowsWritten: 0,
    cursor: null,
    stopReason: env.SCANNER_CACHE_DB ? "complete" : "scanner_cache_unavailable",
    durationMs: 0,
  };
  if (!env.SCANNER_CACHE_DB) return { ...stats, durationMs: Date.now() - startedAt };
  const scannerEnv = env as Env & { SCANNER_CACHE_DB: D1Database };
  const window = `-${Math.max(1, retentionDays)} day`;
  const examined = new Set<string>();
  let iterations = 0;

  try {
    const orphanMemberships = await scannerEnv.SCANNER_CACHE_DB.prepare(
      `DELETE FROM rs_publication_tickers WHERE publication_id IN (
         SELECT p.id FROM rs_publications p
         LEFT JOIN rs_preset_publications pointer ON pointer.publication_id = p.id
         WHERE pointer.publication_id IS NULL AND datetime(p.published_at) < datetime('now', ?) LIMIT ?
       )`,
    ).bind(window, Math.min(1_000, writeBudget)).run();
    const membershipWrites = d1RowsWritten(orphanMemberships);
    stats.publicationRowsDeleted += membershipWrites;
    stats.rowsWritten += membershipWrites;
    if (stats.rowsWritten < writeBudget) {
      const orphanPublications = await scannerEnv.SCANNER_CACHE_DB.prepare(
        `DELETE FROM rs_publications WHERE id IN (
           SELECT p.id FROM rs_publications p
           LEFT JOIN rs_preset_publications pointer ON pointer.publication_id = p.id
           WHERE pointer.publication_id IS NULL AND datetime(p.published_at) < datetime('now', ?) LIMIT ?
         )`,
      ).bind(window, Math.min(1_000, writeBudget - stats.rowsWritten)).run();
      const publicationWrites = d1RowsWritten(orphanPublications);
      stats.publicationRowsDeleted += publicationWrites;
      stats.rowsWritten += publicationWrites;
    }
  } catch (error) {
    if (!scannerPublicationTablesMissing(error)) throw error;
  }

  while (stats.rowsWritten < writeBudget && iterations < 100) {
    iterations += 1;
    const run = await loadOldestDeletableScannerRun(scannerEnv.SCANNER_CACHE_DB, window);
    if (!run) break;
    stats.cursor = run.id;
    examined.add(`${run.runType}:${run.id}`);
    const remaining = writeBudget - stats.rowsWritten;
    const deleteLimit = Math.min(1_000, remaining);
    const childTable = run.runType === "relative-strength" ? "rs_scan_run_tickers" : "vcp_scan_run_tickers";
    const runTable = run.runType === "relative-strength" ? "rs_scan_runs" : "vcp_scan_runs";
    const childResult = await scannerEnv.SCANNER_CACHE_DB.prepare(
      `DELETE FROM ${childTable}
       WHERE rowid IN (
         SELECT rowid FROM ${childTable} WHERE run_id = ? ORDER BY rowid ASC LIMIT ?
       )`,
    ).bind(run.id, deleteLimit).run();
    const childWrites = d1RowsWritten(childResult);
    stats.childRowsDeleted += childWrites;
    stats.rowsWritten += childWrites;
    if (childWrites > 0) continue;

    const queueResult = await scannerEnv.SCANNER_CACHE_DB.prepare(
      "DELETE FROM scanner_cache_scan_run_queue WHERE run_id = ?",
    ).bind(run.id).run();
    const queueWrites = d1RowsWritten(queueResult);
    stats.queueRowsDeleted += queueWrites;
    stats.rowsWritten += queueWrites;
    if (stats.rowsWritten >= writeBudget) break;

    const runResult = await scannerEnv.SCANNER_CACHE_DB.prepare(
      `DELETE FROM ${runTable}
       WHERE id = ? AND status IN ('completed', 'failed', 'cancelled')`,
    ).bind(run.id).run();
    const runWrites = d1RowsWritten(runResult);
    stats.completedRunsDeleted += runWrites;
    stats.rowsWritten += runWrites;
    if (runWrites === 0) break;
    stats.cursor = null;
  }

  stats.examinedRuns = examined.size;
  if (stats.rowsWritten < writeBudget && iterations < 100) {
    const compactWrites = await pruneInactiveRsStateV2(scannerEnv, window, writeBudget - stats.rowsWritten);
    stats.compactRowsDeleted = compactWrites;
    stats.rowsWritten += compactWrites;
  }
  stats.stopReason = stats.rowsWritten >= writeBudget
    ? "write_budget"
    : (iterations >= 100 ? "safety_limit" : "complete");
  stats.durationMs = Date.now() - startedAt;
  console.log("scanner cache retention completed", stats);
  return stats;
}

export async function cleanupOldScansPageData(env: Env, retentionDays = RETENTION_DAYS): Promise<ScannerCacheRetentionStats> {
  const window = `-${Math.max(1, retentionDays)} day`;
  const cleanupResults = await env.DB.batch([
    env.DB.prepare(
      "DELETE FROM relative_strength_materialization_queue WHERE run_id IN (SELECT id FROM relative_strength_materialization_runs WHERE datetime(updated_at) < datetime('now', ?))",
    ).bind(window),
    env.DB.prepare(
      "DELETE FROM relative_strength_materialization_run_candidates WHERE run_id IN (SELECT id FROM relative_strength_materialization_runs WHERE datetime(updated_at) < datetime('now', ?))",
    ).bind(window),
    env.DB.prepare("DELETE FROM relative_strength_materialization_runs WHERE datetime(updated_at) < datetime('now', ?)").bind(window),
    env.DB.prepare(
      "DELETE FROM relative_strength_refresh_queue WHERE job_id IN (SELECT id FROM scan_refresh_jobs WHERE datetime(updated_at) < datetime('now', ?))",
    ).bind(window),
    env.DB.prepare(
      "DELETE FROM scan_refresh_job_top_rows WHERE job_id IN (SELECT id FROM scan_refresh_jobs WHERE datetime(updated_at) < datetime('now', ?))",
    ).bind(window),
    env.DB.prepare(
      "DELETE FROM scan_refresh_job_candidates WHERE job_id IN (SELECT id FROM scan_refresh_jobs WHERE datetime(updated_at) < datetime('now', ?))",
    ).bind(window),
    env.DB.prepare("DELETE FROM scan_refresh_jobs WHERE datetime(updated_at) < datetime('now', ?)").bind(window),
    env.DB.prepare(
      "DELETE FROM scan_rows WHERE snapshot_id IN (SELECT id FROM scan_snapshots WHERE datetime(generated_at) < datetime('now', ?))",
    ).bind(window),
    env.DB.prepare("DELETE FROM scan_snapshots WHERE datetime(generated_at) < datetime('now', ?)").bind(window),
  ]);
  inspectCoreDatabaseResults(env, cleanupResults, "scans-page-housekeeping");
  return cleanupScannerCacheRunData(env, retentionDays);
}

