type PatternUniverseSymbol = {
  ticker: string;
  name: string | null;
  exchange: string | null;
  assetClass: string | null;
  sector: string | null;
  industry: string | null;
};

type PatternUniverseStats = {
  ticker: string;
  price: number;
  latestBarDate: string;
  avgDollarVolume20d: number;
  barCount: number;
};

async function loadActivePatternSymbols(env: Env): Promise<Map<string, PatternUniverseSymbol>> {
  const rows = await env.DB.prepare(
    `SELECT
       UPPER(ticker) as ticker,
       name,
       exchange,
       asset_class as assetClass,
       sector,
       industry
     FROM symbols
     WHERE COALESCE(is_active, 1) = 1
       AND COALESCE(catalog_managed, 0) = 1
       AND lower(COALESCE(asset_class, '')) IN ('equity', 'stock')
     ORDER BY ticker ASC`,
  ).all<PatternUniverseSymbol>();
  return new Map((rows.results ?? []).map((row) => [row.ticker.toUpperCase(), row]));
}

export async function loadCanonicalPatternUniverseStats(
  env: Env,
  profile: PatternProfile,
  tradingDate: string,
  tickers: string[],
  offset: number | null,
  limit: number | null,
): Promise<PatternUniverseStats[] | { count: number | string | null }> {
  if (env.EOD_READ_ENABLED === "true") {
    const eligible: PatternUniverseStats[] = [];
    for (const row of (await loadEodCatalogRows(env, tickers, tradingDate, { unavailableRows: "omit" })).values()) {
      if (row.price != null && row.lastDate != null && row.avgDollarVolume20d != null
        && row.price >= profile.prefilterConfig.minPrice
        && row.avgDollarVolume20d >= profile.prefilterConfig.minDollarVolume20d
        && row.barCount >= profile.prefilterConfig.minBars) {
        eligible.push({ ticker: row.ticker, latestBarDate: row.lastDate, price: row.price,
          avgDollarVolume20d: row.avgDollarVolume20d, barCount: row.barCount });
      }
    }
    eligible.sort((left, right) => left.ticker.localeCompare(right.ticker));
    if (offset == null || limit == null) return { count: eligible.length };
    return eligible.slice(offset, offset + limit);
  }
  const db = getMarketDataDb(env);
  const feed = marketDataFeed(env);
  const eligibleSql = `
    WITH ranked AS (
      SELECT
        ticker,
        date,
        c,
        volume,
        ROW_NUMBER() OVER (PARTITION BY ticker ORDER BY date DESC) as row_number
      FROM alpaca_daily_bars
      WHERE feed = ?
        AND date <= ?
        AND ticker IN (SELECT UPPER(CAST(value AS TEXT)) FROM json_each(?))
    ),
    stats AS (
      SELECT
        ticker,
        MAX(CASE WHEN row_number = 1 THEN date END) as latestBarDate,
        MAX(CASE WHEN row_number = 1 THEN c END) as price,
        AVG(CASE WHEN row_number <= 20 THEN c * COALESCE(volume, 0) END) as avgDollarVolume20d,
        COUNT(*) as barCount
      FROM ranked
      GROUP BY ticker
    )
    SELECT ticker, latestBarDate, price, avgDollarVolume20d, barCount
    FROM stats
    WHERE price >= ?
      AND avgDollarVolume20d >= ?
      AND barCount >= ?`;
  const bindings: unknown[] = [
    feed,
    tradingDate,
    JSON.stringify(tickers),
    profile.prefilterConfig.minPrice,
    profile.prefilterConfig.minDollarVolume20d,
    profile.prefilterConfig.minBars,
  ];
  if (offset == null || limit == null) {
    return (await db.prepare(`SELECT COUNT(*) as count FROM (${eligibleSql})`)
      .bind(...bindings)
      .first<{ count: number | string | null }>()) ?? { count: 0 };
  }
  return (await db.prepare(`${eligibleSql} ORDER BY ticker ASC LIMIT ? OFFSET ?`)
    .bind(...bindings, limit, offset)
    .all<PatternUniverseStats>()).results ?? [];
}

async function countEligibleUniverse(env: Env, profile: PatternProfile, tradingDate: string): Promise<number> {
  const symbols = await loadActivePatternSymbols(env);
  if (symbols.size === 0) return 0;
  const row = await loadCanonicalPatternUniverseStats(env, profile, tradingDate, Array.from(symbols.keys()), null, null) as {
    count: number | string | null;
  };
  return Math.max(0, Number(row.count ?? 0) || 0);
}

async function loadEligibleUniverseBatch(
  env: Env,
  profile: PatternProfile,
  tradingDate: string,
  offset: number,
  limit: number,
): Promise<UniverseCandidate[]> {
  const symbols = await loadActivePatternSymbols(env);
  if (symbols.size === 0) return [];
  const rows = await loadCanonicalPatternUniverseStats(
    env,
    profile,
    tradingDate,
    Array.from(symbols.keys()),
    Math.max(0, Math.trunc(offset)),
    Math.max(1, Math.trunc(limit)),
  ) as PatternUniverseStats[];
  return rows.map((row) => {
    const symbol = symbols.get(row.ticker.toUpperCase());
    return {
    ticker: row.ticker.toUpperCase(),
    name: symbol?.name ?? null,
    exchange: symbol?.exchange ?? null,
    assetClass: symbol?.assetClass ?? null,
    sector: symbol?.sector ?? null,
    industry: symbol?.industry ?? null,
    price: asNumber(row.price),
    avgDollarVolume20d: asNumber(row.avgDollarVolume20d),
    barCount: Number(row.barCount ?? 0),
    latestBarDate: row.latestBarDate,
  };
  });
}

export async function createPatternRun(env: Env, input: PatternRunCreateInput = {}): Promise<PatternRun> {
  const db = requirePatternDb(env);
  const profile = await ensurePatternProfile(env, input.profileId ?? DEFAULT_PATTERN_PROFILE_ID);
  const tradingDate = input.tradingDate ?? latestUsSessionAsOfDate(new Date());
  const existing = await loadPatternRunByProfileDate(env, profile.id, tradingDate);
  if (existing && !input.force && !TERMINAL_PATTERN_RUN_STATUSES.has(existing.status)) {
    if (input.autoContinue && !existing.autoContinue) {
      await updatePatternRun(env, existing.id, { autoContinue: true });
      return await loadPatternRun(env, existing.id) ?? existing;
    }
    return existing;
  }
  if (existing && !input.force && existing.status === "completed") return existing;
  const totalCount = await countEligibleUniverse(env, profile, tradingDate);
  const runId = crypto.randomUUID();
  await db.prepare(
    `INSERT INTO pattern_runs
      (id, profile_id, trading_date, status, phase, total_count, processed_count, matched_count, cursor_offset, auto_continue, last_advanced_at, lease_owner, lease_expires_at, started_at, updated_at, completed_at, error, warning)
     VALUES (?, ?, ?, 'queued', 'queued', ?, 0, 0, 0, ?, NULL, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, NULL, NULL, NULL)`,
  )
    .bind(runId, profile.id, tradingDate, totalCount, input.autoContinue === false ? 0 : 1)
    .run();
  const run = await loadPatternRun(env, runId);
  if (!run) throw new Error("Failed to create pattern scan run.");
  return run;
}

