export async function listPatternCandidatesForReview(
  env: Env,
  options: {
    profileId?: string;
    scope?: PatternCandidateListScope;
    reviewed?: PatternCandidateReviewedMode;
    limit?: number;
    runId?: string | null;
  } = {},
): Promise<PatternCandidateListResult> {
  const profile = await ensurePatternProfile(env, options.profileId ?? DEFAULT_PATTERN_PROFILE_ID);
  const run = options.runId
    ? await loadPatternRun(env, options.runId)
    : await loadLatestCompletedPatternRun(env, profile.id);
  const scope = options.scope ?? "matched";
  const reviewed = options.reviewed ?? "exclude";
  const matchScoreThreshold = sanitizeMatchScoreThreshold(profile.settings.matchScoreThreshold);
  if (!run) {
    return {
      profileId: profile.id,
      run: null,
      scope,
      reviewed,
      matchScoreThreshold,
      totalCandidateCount: 0,
      reviewedHiddenCount: 0,
      rows: [],
    };
  }
  if (run.profileId !== profile.id) throw new Error("Pattern run does not belong to the selected profile.");
  const db = requirePatternDb(env);
  const scopeSql = scope === "matched" ? " AND score >= ?" : "";
  const scopeArgs = scope === "matched" ? [matchScoreThreshold] : [];
  const reviewExistsSql = `EXISTS (
    SELECT 1
    FROM pattern_review_events e
    WHERE e.run_id = pattern_run_candidates.run_id
      AND e.candidate_id = pattern_run_candidates.id
      AND e.event_type IN ('label_approved', 'label_rejected', 'skip')
  )`;
  const totalRow = await db.prepare(
    `SELECT COUNT(*) as count
     FROM pattern_run_candidates
     WHERE run_id = ?${scopeSql}`,
  )
    .bind(run.id, ...scopeArgs)
    .first<{ count: number | string | null }>();
  const hiddenRow = await db.prepare(
    `SELECT COUNT(*) as count
     FROM pattern_run_candidates
     WHERE run_id = ?${scopeSql}
       AND ${reviewExistsSql}`,
  )
    .bind(run.id, ...scopeArgs)
    .first<{ count: number | string | null }>();
  const reviewedSql = reviewed === "exclude" ? ` AND NOT ${reviewExistsSql}` : "";
  const limit = Math.max(1, Math.min(500, Math.trunc(options.limit ?? profile.settings.candidateLimit)));
  const rows = await db.prepare(
    `SELECT
       id,
       run_id as runId,
       profile_id as profileId,
       ticker,
       rank,
       score,
       reasons_json as reasonsJson,
       nearest_approved_json as nearestApprovedJson,
       nearest_rejected_json as nearestRejectedJson,
       feature_json as featureJson,
       shape_json as shapeJson,
       source_metadata_json as sourceMetadataJson,
       created_at as createdAt,
       ? as tradingDate
     FROM pattern_run_candidates
     WHERE run_id = ?${scopeSql}${reviewedSql}
     ORDER BY score DESC, ticker ASC
     LIMIT ?`,
  )
    .bind(run.tradingDate, run.id, ...scopeArgs, limit)
    .all<PatternCandidateRow>();
  return {
    profileId: profile.id,
    run,
    scope,
    reviewed,
    matchScoreThreshold,
    totalCandidateCount: Math.max(0, Number(totalRow?.count ?? 0) || 0),
    reviewedHiddenCount: Math.max(0, Number(hiddenRow?.count ?? 0) || 0),
    rows: (rows.results ?? []).map(mapCandidateRow),
  };
}

async function updatePatternRun(env: Env, runId: string, patch: Partial<{
  status: PatternRun["status"];
  phase: string;
  processedCount: number;
  matchedCount: number;
  cursorOffset: number;
  autoContinue: boolean;
  lastAdvancedAt: string | null;
  leaseOwner: string | null;
  leaseExpiresAt: string | null;
  completedAt: string | null;
  error: string | null;
  warning: string | null;
}>): Promise<void> {
  const db = requirePatternDb(env);
  const assignments = ["updated_at = CURRENT_TIMESTAMP"];
  const values: unknown[] = [];
  if (patch.status) {
    assignments.push("status = ?");
    values.push(patch.status);
  }
  if (patch.phase !== undefined) {
    assignments.push("phase = ?");
    values.push(patch.phase);
  }
  if (typeof patch.processedCount === "number") {
    assignments.push("processed_count = ?");
    values.push(patch.processedCount);
  }
  if (typeof patch.matchedCount === "number") {
    assignments.push("matched_count = ?");
    values.push(patch.matchedCount);
  }
  if (typeof patch.cursorOffset === "number") {
    assignments.push("cursor_offset = ?");
    values.push(patch.cursorOffset);
  }
  if (typeof patch.autoContinue === "boolean") {
    assignments.push("auto_continue = ?");
    values.push(patch.autoContinue ? 1 : 0);
  }
  if (patch.lastAdvancedAt !== undefined) {
    assignments.push("last_advanced_at = ?");
    values.push(patch.lastAdvancedAt);
  }
  if (patch.leaseOwner !== undefined) {
    assignments.push("lease_owner = ?");
    values.push(patch.leaseOwner);
  }
  if (patch.leaseExpiresAt !== undefined) {
    assignments.push("lease_expires_at = ?");
    values.push(patch.leaseExpiresAt);
  }
  if (patch.completedAt !== undefined) {
    assignments.push("completed_at = ?");
    values.push(patch.completedAt);
  }
  if (patch.error !== undefined) {
    assignments.push("error = ?");
    values.push(patch.error);
  }
  if (patch.warning !== undefined) {
    assignments.push("warning = ?");
    values.push(patch.warning);
  }
  await db.prepare(`UPDATE pattern_runs SET ${assignments.join(", ")} WHERE id = ?`).bind(...values, runId).run();
}

async function acquirePatternRunLease(env: Env, runId: string, owner: string, leaseMs = PATTERN_RUN_LEASE_MS): Promise<boolean> {
  const db = requirePatternDb(env);
  const nowIso = new Date().toISOString();
  const leaseExpiresAt = new Date(Date.now() + leaseMs).toISOString();
  const result = await db.prepare(
    `UPDATE pattern_runs
     SET
       status = CASE WHEN status = 'queued' THEN 'running' ELSE status END,
       phase = 'scanning',
       lease_owner = ?,
       lease_expires_at = ?,
       error = NULL,
       updated_at = CURRENT_TIMESTAMP
     WHERE id = ?
       AND status IN ('queued', 'running')
       AND (
         lease_owner IS NULL
         OR lease_owner = ?
         OR lease_expires_at IS NULL
         OR datetime(lease_expires_at) <= datetime(?)
       )`,
  )
    .bind(owner, leaseExpiresAt, runId, owner, nowIso)
    .run();
  return Number(result.meta?.changes ?? 0) > 0;
}

async function releasePatternRunLease(env: Env, runId: string, owner: string): Promise<void> {
  const db = requirePatternDb(env);
  await db.prepare(
    `UPDATE pattern_runs
     SET lease_owner = NULL,
         lease_expires_at = NULL,
         updated_at = CURRENT_TIMESTAMP
     WHERE id = ?
       AND lease_owner = ?`,
  )
    .bind(runId, owner)
    .run();
}

async function clearLatestPatternScoresForRun(env: Env, runId: string): Promise<void> {
  const db = requirePatternDb(env);
  await db.prepare("DELETE FROM pattern_scores_latest WHERE run_id = ?").bind(runId).run();
}

async function publishCompletedPatternRun(
  env: Env,
  run: PatternRun,
  progress: { processedCount: number; matchedCount: number; cursorOffset: number; warning: string | null },
): Promise<void> {
  const db = requirePatternDb(env);
  const completedAt = new Date().toISOString();
  await db.batch([
    db.prepare("DELETE FROM pattern_scores_latest WHERE profile_id = ?").bind(run.profileId),
    db.prepare(
      `INSERT INTO pattern_scores_latest
        (profile_id, ticker, run_id, candidate_id, trading_date, rank, score, reasons_json,
         nearest_approved_json, nearest_rejected_json, feature_json, shape_json,
         source_metadata_json, updated_at)
       SELECT
         c.profile_id, c.ticker, c.run_id, c.id, r.trading_date, c.rank, c.score,
         c.reasons_json, c.nearest_approved_json, c.nearest_rejected_json,
         c.feature_json, c.shape_json, c.source_metadata_json, ?
       FROM pattern_run_candidates c
       JOIN pattern_runs r ON r.id = c.run_id
       WHERE c.run_id = ?`,
    ).bind(completedAt, run.id),
    db.prepare(
      `INSERT INTO pattern_completed_run_pointer (profile_id, run_id, updated_at)
       VALUES (?, ?, ?)
       ON CONFLICT(profile_id) DO UPDATE SET
         run_id = excluded.run_id,
         updated_at = excluded.updated_at`,
    ).bind(run.profileId, run.id, completedAt),
    db.prepare(
      `UPDATE pattern_runs
       SET status = 'completed',
           phase = 'completed',
           processed_count = ?,
           matched_count = ?,
           cursor_offset = ?,
           auto_continue = 0,
           last_advanced_at = ?,
           lease_owner = NULL,
           lease_expires_at = NULL,
           completed_at = ?,
           warning = ?,
           updated_at = ?
       WHERE id = ?`,
    ).bind(
      progress.processedCount,
      progress.matchedCount,
      progress.cursorOffset,
      completedAt,
      completedAt,
      progress.warning,
      completedAt,
      run.id,
    ),
  ]);
}

export async function processPatternScanRun(
  env: Env,
  runId: string,
  options?: { batchSize?: number; maxBatches?: number; leaseOwner?: string },
): Promise<PatternRun | null> {
  const db = requirePatternDb(env);
  let run = await loadPatternRun(env, runId);
  if (!run) return null;
  if (!PROCESSABLE_PATTERN_RUN_STATUSES.has(run.status)) return run;
  const leaseOwner = options?.leaseOwner ?? crypto.randomUUID();
  const acquired = await acquirePatternRunLease(env, run.id, leaseOwner);
  if (!acquired) return run;
  run = await loadPatternRun(env, runId);
  if (!run || !PROCESSABLE_PATTERN_RUN_STATUSES.has(run.status)) {
    await releasePatternRunLease(env, runId, leaseOwner);
    return run;
  }
  const profile = await ensurePatternProfile(env, run.profileId);
  let model = await loadPatternModel(env, profile.id);
  if (!model) model = await rebuildPatternModel(env, profile.id);
  const labels = await listActiveTrainingLabels(env, profile.id);
  const batchSize = Math.max(1, Math.trunc(options?.batchSize ?? 40));
  const maxBatches = Math.max(1, Math.trunc(options?.maxBatches ?? 4));
  const matchScoreThreshold = sanitizeMatchScoreThreshold(profile.settings.matchScoreThreshold);
  let cursorOffset = run.cursorOffset;
  let processedCount = run.processedCount;
  let matchedCount = run.matchedCount;
  let batchCount = 0;
  let warning: string | null = run.warning;
  try {
    while (cursorOffset < run.totalCount && batchCount < maxBatches) {
      const control = await loadPatternRun(env, run.id);
      if (!control) return null;
      if (control.status === "paused" || control.status === "cancelled") {
        await updatePatternRun(env, run.id, {
          phase: control.status,
          processedCount,
          matchedCount,
          cursorOffset,
          lastAdvancedAt: batchCount > 0 ? new Date().toISOString() : control.lastAdvancedAt,
          autoContinue: false,
        });
        if (control.status === "cancelled") await clearLatestPatternScoresForRun(env, run.id);
        run = await loadPatternRun(env, runId);
        return run;
      }
      const universe = await loadEligibleUniverseBatch(env, profile, run.tradingDate, cursorOffset, batchSize);
      if (universe.length === 0) {
        warning = "Eligible universe ended before the stored total count.";
        cursorOffset = run.totalCount;
        break;
      }
      const benchmarkTicker = profile.benchmarkTickers[0] ?? DEFAULT_BENCHMARK_TICKER;
      const tickers = universe.map((candidate) => candidate.ticker);
      const barsByTicker = await loadBarsByCount(env, [...tickers, benchmarkTicker], run.tradingDate, profile.settings.contextWindowBars);
      const benchmarkBars = barsByTicker.get(benchmarkTicker) ?? [];
      const candidatePatternLengths = sanitizeCandidatePatternLengths(profile.settings.candidatePatternLengths);
      const statements: D1PreparedStatement[] = [];
      for (let index = 0; index < universe.length; index += 1) {
        const row = universe[index];
        const tickerBars = barsByTicker.get(row.ticker) ?? [];
        let bestSnapshot: PatternFeatureSnapshot | null = null;
        let bestReasons: PatternScoreReasons | null = null;
        for (const length of candidatePatternLengths) {
          const snapshot = buildPatternFeatureSnapshot({
            ticker: row.ticker,
            setupDate: run.tradingDate,
            benchmarkTicker,
            tickerBars,
            benchmarkBars,
            contextWindowBars: profile.settings.contextWindowBars,
            patternWindowBars: length,
            selectionMode: "fixed_window",
            selectedResamplePoints: profile.settings.selectedResamplePoints,
          });
          if (!snapshot) continue;
          const reasons = scorePatternSnapshot(snapshot, labels, model);
          if (!bestReasons || reasons.score > bestReasons.score) {
            bestSnapshot = snapshot;
            bestReasons = reasons;
          }
        }
        if (!bestSnapshot || !bestReasons) {
          processedCount += 1;
          continue;
        }
        const snapshot = bestSnapshot;
        const reasons = bestReasons;
        const nearestApproved = model?.model ? nearestExamples(snapshot.featureJson, snapshot.shapeJson, labels, model.model, "approved") : [];
        const nearestRejected = model?.model ? nearestExamples(snapshot.featureJson, snapshot.shapeJson, labels, model.model, "rejected") : [];
        const candidateId = crypto.randomUUID();
        const rank = cursorOffset + index + 1;
        const sourceMetadata = {
          ...snapshot.sourceMetadata,
          matchedPatternStartDate: snapshot.patternStartDate,
          matchedPatternEndDate: snapshot.patternEndDate,
          matchedPatternBars: snapshot.selectedBarCount,
          name: row.name,
          exchange: row.exchange,
          assetClass: row.assetClass,
          sector: row.sector,
          industry: row.industry,
          universePrice: row.price,
          universeAvgDollarVolume20d: row.avgDollarVolume20d,
          universeBarCount: row.barCount,
        };
        if (reasons.score >= matchScoreThreshold) matchedCount += 1;
        processedCount += 1;
        statements.push(
          db.prepare(
            `INSERT INTO pattern_run_candidates
              (id, run_id, profile_id, ticker, rank, score, reasons_json, nearest_approved_json, nearest_rejected_json, feature_json, shape_json, source_metadata_json, created_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
             ON CONFLICT(run_id, ticker) DO UPDATE SET
               rank = excluded.rank,
               score = excluded.score,
               reasons_json = excluded.reasons_json,
               nearest_approved_json = excluded.nearest_approved_json,
               nearest_rejected_json = excluded.nearest_rejected_json,
               feature_json = excluded.feature_json,
               shape_json = excluded.shape_json,
               source_metadata_json = excluded.source_metadata_json`,
          )
            .bind(
              candidateId,
              run.id,
              profile.id,
              row.ticker,
              rank,
              reasons.score,
              JSON.stringify(reasons),
              JSON.stringify(nearestApproved),
              JSON.stringify(nearestRejected),
              JSON.stringify(snapshot.featureJson),
              JSON.stringify(snapshot.shapeJson),
              JSON.stringify(sourceMetadata),
            ),
        );
      }
      if (statements.length > 0) await db.batch(statements);
      cursorOffset += universe.length;
      batchCount += 1;
      const progressedAt = new Date().toISOString();
      const controlAfterBatch = await loadPatternRun(env, run.id);
      if (controlAfterBatch?.status === "paused" || controlAfterBatch?.status === "cancelled") {
        await updatePatternRun(env, run.id, {
          phase: controlAfterBatch.status,
          processedCount,
          matchedCount,
          cursorOffset,
          lastAdvancedAt: progressedAt,
          autoContinue: false,
        });
        if (controlAfterBatch.status === "cancelled") await clearLatestPatternScoresForRun(env, run.id);
        run = await loadPatternRun(env, runId);
        return run;
      }
      await updatePatternRun(env, run.id, {
        status: "running",
        phase: "scanning",
        processedCount,
        matchedCount,
        cursorOffset,
        lastAdvancedAt: progressedAt,
      });
    }
    if (cursorOffset >= run.totalCount) {
      await rerankRunCandidates(env, run.id);
      await publishCompletedPatternRun(env, run, {
        processedCount,
        matchedCount,
        cursorOffset,
        warning,
      });
    } else {
      await updatePatternRun(env, run.id, {
        status: "running",
        phase: "waiting_for_next_batch",
        processedCount,
        matchedCount,
        cursorOffset,
        warning,
      });
    }
  } catch (error) {
    await updatePatternRun(env, runId, {
      status: "failed",
      phase: "failed",
      autoContinue: false,
      leaseOwner: null,
      leaseExpiresAt: null,
      completedAt: new Date().toISOString(),
      error: error instanceof Error ? error.message : "Pattern scan failed.",
    });
  } finally {
    await releasePatternRunLease(env, runId, leaseOwner);
  }
  run = await loadPatternRun(env, runId);
  return run;
}

async function rerankRunCandidates(env: Env, runId: string): Promise<void> {
  const db = requirePatternDb(env);
  const rows = await db.prepare(
    "SELECT id, profile_id as profileId, ticker FROM pattern_run_candidates WHERE run_id = ? ORDER BY score DESC, ticker ASC",
  )
    .bind(runId)
    .all<{ id: string; profileId: string; ticker: string }>();
  const statements = (rows.results ?? []).map((row, index) =>
    db.prepare("UPDATE pattern_run_candidates SET rank = ? WHERE id = ?").bind(index + 1, row.id),
  );
  for (let index = 0; index < statements.length; index += 100) {
    const chunk = statements.slice(index, index + 100);
    if (chunk.length > 0) await db.batch(chunk);
  }
}

export async function continuePatternRun(env: Env, runId: string): Promise<PatternRun | null> {
  const run = await loadPatternRun(env, runId);
  if (!run) return null;
  if (TERMINAL_PATTERN_RUN_STATUSES.has(run.status)) return run;
  await updatePatternRun(env, run.id, {
    status: "running",
    phase: "waiting_for_next_batch",
    autoContinue: true,
    completedAt: null,
    error: null,
  });
  return await loadPatternRun(env, run.id);
}

export async function pausePatternRun(env: Env, runId: string): Promise<PatternRun | null> {
  const run = await loadPatternRun(env, runId);
  if (!run) return null;
  if (TERMINAL_PATTERN_RUN_STATUSES.has(run.status)) return run;
  await updatePatternRun(env, run.id, {
    status: "paused",
    phase: "paused",
    autoContinue: false,
    warning: "Paused by user.",
  });
  return await loadPatternRun(env, run.id);
}

export async function resumePatternRun(env: Env, runId: string): Promise<PatternRun | null> {
  const run = await loadPatternRun(env, runId);
  if (!run) return null;
  if (TERMINAL_PATTERN_RUN_STATUSES.has(run.status)) return run;
  await updatePatternRun(env, run.id, {
    status: "running",
    phase: "waiting_for_next_batch",
    autoContinue: true,
    completedAt: null,
    error: null,
    warning: null,
  });
  return await loadPatternRun(env, run.id);
}

export async function cancelPatternRun(env: Env, runId: string): Promise<PatternRun | null> {
  const run = await loadPatternRun(env, runId);
  if (!run) return null;
  if (TERMINAL_PATTERN_RUN_STATUSES.has(run.status)) return run;
  await updatePatternRun(env, run.id, {
    status: "cancelled",
    phase: "cancelled",
    autoContinue: false,
    leaseOwner: null,
    leaseExpiresAt: null,
    completedAt: new Date().toISOString(),
    warning: "Cancelled by user.",
  });
  await clearLatestPatternScoresForRun(env, run.id);
  return await loadPatternRun(env, run.id);
}

export async function listAutoContinuablePatternRuns(env: Env, limit = 3): Promise<PatternRun[]> {
  const db = requirePatternDb(env);
  const nowIso = new Date().toISOString();
  const rows = await db.prepare(
    `SELECT
       id,
       profile_id as profileId,
       trading_date as tradingDate,
       status,
       phase,
       total_count as totalCount,
       processed_count as processedCount,
       matched_count as matchedCount,
       cursor_offset as cursorOffset,
       COALESCE(auto_continue, 0) as autoContinue,
       last_advanced_at as lastAdvancedAt,
       lease_owner as leaseOwner,
       lease_expires_at as leaseExpiresAt,
       started_at as startedAt,
       updated_at as updatedAt,
       completed_at as completedAt,
       error,
       warning
     FROM pattern_runs
     WHERE auto_continue = 1
       AND status IN ('queued', 'running')
       AND (
         lease_owner IS NULL
         OR lease_expires_at IS NULL
         OR datetime(lease_expires_at) <= datetime(?)
       )
     ORDER BY datetime(started_at) ASC
     LIMIT ?`,
  )
    .bind(nowIso, Math.max(1, Math.min(10, limit)))
    .all<PatternRunRow>();
  return (rows.results ?? []).map(mapRunRow);
}

export async function maybeRunScheduledPatternScan(
  env: Env,
  now: Date,
  settings: WorkerScheduleSettings,
): Promise<PatternRun | null> {
  if (!env.PATTERN_DB) return null;
  const continuable = await listAutoContinuablePatternRuns(env, 1);
  if (continuable[0]) {
    return await processPatternScanRun(env, continuable[0].id, {
      batchSize: settings.patternScanBatchSize,
      maxBatches: settings.patternScanMaxBatchesPerTick,
    });
  }
  if (!settings.patternScanEnabled) return null;
  const tradingDate = latestUsSessionAsOfDate(now);
  if (!isPatternScanWindowOpen(now, tradingDate, settings.patternScanOffsetMinutes)) return null;
  const run = await createPatternRun(env, { profileId: DEFAULT_PATTERN_PROFILE_ID, tradingDate, force: false, autoContinue: true });
  if (run.status === "completed") return run;
  return await processPatternScanRun(env, run.id, {
    batchSize: settings.patternScanBatchSize,
    maxBatches: settings.patternScanMaxBatchesPerTick,
  });
}

export function isPatternScanWindowOpen(now: Date, expectedTradingDate: string, offsetMinutes: number): boolean {
  const ny = zonedParts(now, "America/New_York");
  const closeMinutesWithOffset = 16 * 60 + Math.max(0, offsetMinutes);
  if (ny.localDate > expectedTradingDate) return true;
  return ny.localDate === expectedTradingDate && ny.minutesOfDay >= closeMinutesWithOffset;
}

export async function listLatestPatternCandidates(env: Env, profileId = DEFAULT_PATTERN_PROFILE_ID, limit = 100): Promise<PatternCandidate[]> {
  const db = requirePatternDb(env);
  const rows = await db.prepare(
    `SELECT
       candidate_id as id,
       run_id as runId,
       profile_id as profileId,
       ticker,
       rank,
       score,
       reasons_json as reasonsJson,
       nearest_approved_json as nearestApprovedJson,
       nearest_rejected_json as nearestRejectedJson,
       feature_json as featureJson,
       shape_json as shapeJson,
       source_metadata_json as sourceMetadataJson,
       trading_date as tradingDate,
       updated_at as updatedAt,
       (
         SELECT event_type
         FROM pattern_review_events e
         WHERE e.profile_id = pattern_scores_latest.profile_id
           AND e.run_id = pattern_scores_latest.run_id
           AND e.candidate_id = pattern_scores_latest.candidate_id
           AND e.event_type IN ('label_approved', 'label_rejected', 'skip')
         ORDER BY datetime(e.created_at) DESC
         LIMIT 1
       ) as reviewEventType,
       (
         SELECT created_at
         FROM pattern_review_events e
         WHERE e.profile_id = pattern_scores_latest.profile_id
           AND e.run_id = pattern_scores_latest.run_id
           AND e.candidate_id = pattern_scores_latest.candidate_id
           AND e.event_type IN ('label_approved', 'label_rejected', 'skip')
         ORDER BY datetime(e.created_at) DESC
         LIMIT 1
       ) as reviewedAt
     FROM pattern_scores_latest
     WHERE profile_id = ?
       AND run_id = (
         SELECT run_id
         FROM pattern_completed_run_pointer
         WHERE profile_id = ?
       )
     ORDER BY score DESC, ticker ASC
     LIMIT ?`,
  )
    .bind(profileId, profileId, Math.max(1, Math.min(500, limit)))
    .all<PatternCandidateRow>();
  return (rows.results ?? []).map(mapCandidateRow);
}

export async function loadPatternRunDetail(env: Env, runId: string): Promise<{ run: PatternRun; candidates: PatternCandidate[] } | null> {
  const run = await loadPatternRun(env, runId);
  if (!run) return null;
  const db = requirePatternDb(env);
  const rows = await db.prepare(
    `SELECT
       id,
       run_id as runId,
       profile_id as profileId,
       ticker,
       rank,
       score,
       reasons_json as reasonsJson,
       nearest_approved_json as nearestApprovedJson,
       nearest_rejected_json as nearestRejectedJson,
       feature_json as featureJson,
       shape_json as shapeJson,
       source_metadata_json as sourceMetadataJson,
       created_at as createdAt,
       (
         SELECT event_type
         FROM pattern_review_events e
         WHERE e.profile_id = pattern_run_candidates.profile_id
           AND e.run_id = pattern_run_candidates.run_id
           AND e.candidate_id = pattern_run_candidates.id
           AND e.event_type IN ('label_approved', 'label_rejected', 'skip')
         ORDER BY datetime(e.created_at) DESC
         LIMIT 1
       ) as reviewEventType,
       (
         SELECT created_at
         FROM pattern_review_events e
         WHERE e.profile_id = pattern_run_candidates.profile_id
           AND e.run_id = pattern_run_candidates.run_id
           AND e.candidate_id = pattern_run_candidates.id
           AND e.event_type IN ('label_approved', 'label_rejected', 'skip')
         ORDER BY datetime(e.created_at) DESC
         LIMIT 1
       ) as reviewedAt
     FROM pattern_run_candidates
     WHERE run_id = ?
     ORDER BY score DESC, ticker ASC
     LIMIT 250`,
  )
    .bind(runId)
    .all<PatternCandidateRow>();
  return { run, candidates: (rows.results ?? []).map(mapCandidateRow) };
}

export async function loadPatternAnalysis(env: Env, profileId = DEFAULT_PATTERN_PROFILE_ID): Promise<{
  profile: PatternProfile;
  activeModel: PatternModelVersion | null;
  featureRegistry: PatternFeatureRegistryRow[];
  approvalCount: number;
  rejectionCount: number;
  featureSummary: PatternFeatureSummary;
  validationMetrics: PatternValidationMetrics;
  modelHistory: PatternModelVersion[];
  mlReadiness: {
    balancedLabels: number;
    logisticReady: boolean;
    neuralReady: boolean;
    guidance: string[];
  };
}> {
  const profile = await ensurePatternProfile(env, profileId);
  const [labels, registry, activeModel, modelHistory] = await Promise.all([
    listActiveTrainingLabels(env, profile.id),
    listPatternFeatureRegistry(env),
    loadPatternModel(env, profile.id),
    loadPatternModelHistory(env, profile.id, 10),
  ]);
  const approvalCount = labels.filter((label) => label.label === "approved").length;
  const rejectionCount = labels.filter((label) => label.label === "rejected").length;
  const balancedLabels = Math.min(approvalCount, rejectionCount) * 2;
  return {
    profile,
    activeModel,
    featureRegistry: registry,
    approvalCount,
    rejectionCount,
    featureSummary: activeModel?.featureSummary ?? emptyFeatureSummary(),
    validationMetrics: activeModel?.metrics ?? {
      ...emptyMetrics(),
      approvedCount: approvalCount,
      rejectedCount: rejectionCount,
      totalActiveLabels: labels.length,
    },
    modelHistory,
    mlReadiness: {
      balancedLabels,
      logisticReady: balancedLabels >= 300,
      neuralReady: balancedLabels >= 1500,
      guidance: [
        "Test logistic and boosted models around 300 balanced labels.",
        "Consider neural or image models around 1,500 labels.",
        "Promote only if chronological validation improves Precision@25/50 by at least 15%.",
      ],
    },
  };
}

export async function patternExportText(env: Env, profileId = DEFAULT_PATTERN_PROFILE_ID): Promise<string> {
  const candidates = await listLatestPatternCandidates(env, profileId, 500);
  return candidates.map((candidate) => candidate.ticker).join("\n");
}

