async function loadTickersMissingRecentBars(env: Env, tickers: string[], expectedAsOfDate = latestUsMarketSessionAsOfDate(new Date())): Promise<string[]> {
  const unique = uniqueTickers(tickers);
  if (unique.length === 0) return [];
  if (env.MARKET_HISTORY_DB) {
    const dates = await loadMarketHistoryLatestDates(env, unique, marketDataFeed(env));
    return unique.filter((ticker) => (dates.get(ticker) ?? "") < expectedAsOfDate);
  }
  const lastDateByTicker = new Map<string, string | null>();
  const chunkSize = 80;
  for (let i = 0; i < unique.length; i += chunkSize) {
    const chunk = unique.slice(i, i + chunkSize);
    const sql = `SELECT ticker, MAX(date) as lastDate FROM alpaca_daily_bars WHERE feed = ? AND ticker IN (${chunk.map(() => "?").join(",")}) GROUP BY ticker`;
    const rows = await getMarketDataDb(env).prepare(sql).bind(marketDataFeed(env), ...chunk).all<{ ticker: string; lastDate: string | null }>();
    for (const row of rows.results ?? []) {
      lastDateByTicker.set(row.ticker.toUpperCase(), row.lastDate ?? null);
    }
  }
  return unique.filter((ticker) => {
    const lastDate = lastDateByTicker.get(ticker) ?? null;
    return !lastDate || lastDate < expectedAsOfDate;
  });
}

async function loadTickersMissingBarHistory(env: Env, tickers: string[], minBars = OVERVIEW_SPARKLINE_MIN_POINTS): Promise<string[]> {
  const unique = uniqueTickers(tickers);
  if (unique.length === 0) return [];
  if (env.EOD_READ_ENABLED === "true") {
    const session = await expectedEodSession(env);
    if (!session) throw new EodCatalogUnavailableError("the expected completed exchange session cannot be verified");
    const catalog = await loadEodCatalogRows(env, unique, session, { unavailableRows: "omit" });
    return unique.filter((ticker) => !catalog.has(ticker) || catalog.get(ticker)!.barCount < minBars);
  }
  if (env.MARKET_HISTORY_DB) {
    const coverage=await loadMarketHistoryCoverage(env,{tickers:unique});
    return unique.filter((ticker) => (coverage.get(ticker)?.barCount ?? 0)<minBars);
  }
  const barCountByTicker = new Map<string, number>();
  const chunkSize = 80;
  for (let i = 0; i < unique.length; i += chunkSize) {
    const chunk = unique.slice(i, i + chunkSize);
    const sql = `SELECT ticker, COUNT(*) as barCount FROM alpaca_daily_bars WHERE feed = ? AND ticker IN (${chunk.map(() => "?").join(",")}) GROUP BY ticker`;
    const rows = await getMarketDataDb(env).prepare(sql).bind(marketDataFeed(env), ...chunk).all<{ ticker: string; barCount: number }>();
    for (const row of rows.results ?? []) {
      barCountByTicker.set(row.ticker.toUpperCase(), Number(row.barCount ?? 0));
    }
  }
  return unique.filter((ticker) => (barCountByTicker.get(ticker) ?? 0) < minBars);
}

