type RefreshPage =
  | "overview"
  | "breadth"
  | "sectors"
  | "thirteenf"
  | "admin"
  | "ticker"
  | "alerts"
  | "scans"
  | "pattern-scanner"
  | "watchlist-compiler"
  | "gappers"
  | "earnings"
  | "market-commentary";

const MAX_MARKET_LANE_REFRESH_TICKERS = 4 * 80;

async function refreshPageScopedData(
  env: Env,
  page: RefreshPage,
  tickerInput?: string | null,
): Promise<{
  page: RefreshPage;
  refreshedTickers: number;
  notes?: string;
  generationId?: string;
  publishedAt?: string;
  currentCoveragePct?: number;
  historyExactCoveragePct?: number;
  historyUsableCoveragePct?: number;
  canonicalSession?: string;
  historyRefreshStatus?: string;
  historyErrorCode?: string | null;
  historyNextAttemptAt?: string | null;
  publicationStatus?: "published" | "recovering" | "blocked";
  publicationNextAttemptAt?: string | null;
  publicationErrorCode?: string | null;
  publicationError?: string | null;
  reportId?: string;
  sessionDate?: string;
}> {
  if (["overview", "breadth", "sectors", "thirteenf", "admin", "ticker"].includes(page)) {
    assertMarketPipelineActive(env);
  }
  if (page === "overview") {
    return await refreshOverviewPageData(env, {
      loadOverviewTickers,
      refreshAndStoreOverviewSnapshot: (targetEnv, options) => refreshAndStoreOverviewSnapshot(targetEnv, undefined, "default", options),
    });
  }
  if (page === "market-commentary") {
    const response = await refreshMarketCommentary(env, { force: true, trigger: "manual" });
    if (response.status !== "ready" || !response.report) {
      throw new Error("Market commentary generation did not publish a ready report.");
    }
    return {
      page,
      refreshedTickers: 0,
      notes: `Published market commentary for ${response.report.sessionDate}.`,
      reportId: response.report.id,
      sessionDate: response.report.sessionDate,
      publishedAt: response.report.generatedAt,
    };
  }
  if (page === "breadth") {
    const catchUp = await refreshMissingBreadthBarsForCoverage(env, undefined, {
      maxTickers: MAX_MARKET_LANE_REFRESH_TICKERS,
      maxPasses: 1,
    });
    const recompute = await recomputeBreadthFromStoredBars(env);
    const sp500CountRow = await getMarketDataDb(env).prepare("SELECT COUNT(*) as count FROM universe_symbols WHERE universe_id = ?")
      .bind("sp500-core")
      .first<{ count: number }>();
    const lowCoverage = catchUp.diagnostics
      .filter((diagnostic) => !diagnostic.ok)
      .map((diagnostic) => `${diagnostic.universeId} ${diagnostic.coveragePct.toFixed(1)}%/${diagnostic.minCoveragePct}%`);
    return {
      page,
      refreshedTickers: sp500CountRow?.count ?? 0,
      notes: `Breadth catch-up wrote ${catchUp.writtenRows} rows from ${catchUp.attemptedTickers} attempted tickers. Stored ${recompute.universeCount}/${recompute.attemptedUniverseCount} universes.${lowCoverage.length ? ` Low coverage: ${lowCoverage.join(", ")}.` : ""}`,
    };
  }
  if (page === "sectors") {
    const tickers = await loadSectorPageTickers(env);
    await refreshRecentBarsForTickers(env, tickers, MAX_MARKET_LANE_REFRESH_TICKERS, 21, false, {
      target: "market",
      throwOnError: true,
    });
    return {
      page,
      refreshedTickers: Math.min(tickers.length, MAX_MARKET_LANE_REFRESH_TICKERS),
      notes: tickers.length > MAX_MARKET_LANE_REFRESH_TICKERS
        ? `Refreshed the first ${MAX_MARKET_LANE_REFRESH_TICKERS} tickers; remaining canonical catch-up continues in scheduled slices.`
        : undefined,
    };
  }
  if (page === "thirteenf") {
    const tickers = await load13fTickers(env);
    await refreshRecentBarsForTickers(env, tickers, MAX_MARKET_LANE_REFRESH_TICKERS, 21, false, {
      target: "market",
      throwOnError: true,
    });
    return {
      page,
      refreshedTickers: Math.min(tickers.length, MAX_MARKET_LANE_REFRESH_TICKERS),
      notes: tickers.length > MAX_MARKET_LANE_REFRESH_TICKERS
        ? `Refreshed the first ${MAX_MARKET_LANE_REFRESH_TICKERS} tickers; remaining canonical catch-up continues in scheduled slices.`
        : undefined,
    };
  }
  if (page === "admin") {
    const tickers = await loadAdminTickers(env);
    try {
      await refreshRecentBarsForTickers(env, tickers, MAX_MARKET_LANE_REFRESH_TICKERS, 21, false, {
        target: "market",
        throwOnError: true,
      });
      await recomputeDashboardFromStoredBars(env);
      await recomputeBreadthFromStoredBars(env);
      return {
        page,
        refreshedTickers: Math.min(tickers.length, MAX_MARKET_LANE_REFRESH_TICKERS),
        notes: tickers.length > MAX_MARKET_LANE_REFRESH_TICKERS
          ? `Refreshed the first ${MAX_MARKET_LANE_REFRESH_TICKERS} tickers; remaining canonical catch-up continues in scheduled slices.`
          : undefined,
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : "Live admin refresh failed.";
      await recomputeDashboardFromStoredBars(env);
      await recomputeBreadthFromStoredBars(env);
      return {
        page,
        refreshedTickers: Math.min(tickers.length, MAX_MARKET_LANE_REFRESH_TICKERS),
        notes: `Live admin refresh failed (${message}). Rebuilt dashboard and breadth from stored bars instead.`,
      };
    }
  }
  if (page === "ticker") {
    const ticker = tickerInput?.trim().toUpperCase() ?? "";
    if (!/^[A-Z.\-^]{1,20}$/.test(ticker)) {
      throw new Error("Valid ticker is required for ticker page refresh.");
    }
    await refreshRecentBarsForTickers(env, [ticker], 1, TICKER_SERIES_2Y_LOOKBACK_DAYS, true, {
      target: "market",
      throwOnError: true,
    });
    return { page, refreshedTickers: 1 };
  }
  if (page === "alerts") {
    const reconcile = await reconcileAlertsFromMailboxAdapters(env, 25);
    await cleanupOldAlertsData(env, 30);
    return {
      page,
      refreshedTickers: reconcile.alertsIngested,
      notes: `Alerts ingest: ${reconcile.alertsIngested} new, ${reconcile.duplicates} duplicate, ${reconcile.parseFailures} parse failures.`,
    };
  }
  if (page === "scans") {
    const snapshot = await refreshScansSnapshot(env);
    return {
      page,
      refreshedTickers: snapshot.rowCount,
      notes: `Refreshed ${snapshot.presetName} scan snapshot with ${snapshot.rowCount} ranked rows.`,
    };
  }
  if (page === "pattern-scanner") {
    const run = await createPatternRun(env, { profileId: "default", force: false, autoContinue: true });
    const processed = await processPatternScanRun(env, run.id, { batchSize: 40, maxBatches: 1 });
    return {
      page,
      refreshedTickers: processed?.processedCount ?? run.processedCount,
      notes: `Pattern scanner run ${processed?.status ?? run.status} for ${run.tradingDate}.`,
    };
  }
  if (page === "watchlist-compiler") {
    const refreshed = await compileActiveWatchlistSets(env);
    return {
      page,
      refreshedTickers: refreshed.compiledRows,
      notes: `Compiled ${refreshed.compiledSets} watchlist set${refreshed.compiledSets === 1 ? "" : "s"} and stored ${refreshed.compiledRows} compiled rows.`,
    };
  }
  if (page === "gappers") {
    const snapshot = await refreshGappersSnapshot(env, 25);
    return {
      page,
      refreshedTickers: snapshot.rowCount,
      notes: `Refreshed gappers snapshot with ${snapshot.rowCount} ranked rows.`,
    };
  }
  if (page === "earnings") {
    const result = await syncEarningsSurprises(env, { mode: "incremental" });
    return {
      page,
      refreshedTickers: result.rowsUpserted,
      notes: `Synced earnings surprises from ${result.provider ?? "configured providers"}: ${result.rowsUpserted} row${result.rowsUpserted === 1 ? "" : "s"} upserted.`,
    };
  }
  return { page, refreshedTickers: 0, notes: "No market tickers are tracked on this page." };
}

async function processNextRefreshJob(env: Env): Promise<void> {
  const job = await claimNextRefreshJob(env);
  if (!job) return;
  await processClaimedRefreshJob(env, job);
}

async function processRefreshJobById(env: Env, jobId: string): Promise<void> {
  const job = await claimRefreshJobById(env, jobId);
  if (!job) return;
  await processClaimedRefreshJob(env, job);
}

async function processClaimedRefreshJob(
  env: Env,
  job: RefreshJob,
): Promise<void> {
  try {
    if (eodEnabled(env) && ["overview", "breadth"].includes(job.page)) {
      const session = await expectedEodSession(env);
      if (!session) throw new Error("Exchange calendar unavailable; refresh could not resolve a completed session.");
      const run = await enqueueEodRun(env, session);
      const status = await eodStatus(env);
      const pageReady = job.page === "overview"
        ? status.publications.some((row) => row.scope === "overview:default" && row.session_date === session)
        : !status.missingScopes?.some((scope) => scope.startsWith("breadth:"));
      if (pageReady) {
        await completeRefreshJob(env, job, { page: job.page, refreshedTickers: 0, sessionDate: run.session_date, notes: "EOD publication completed." });
      } else {
        await dispatchEodRun(env, run);
        await deferRefreshJob(env, job, 15 * 60_000);
      }
      return;
    }
    const result = await refreshPageScopedData(env, job.page as RefreshPage, job.ticker);
    await completeRefreshJob(env, job, result);
  } catch (error) {
    if (error instanceof MarketPipelinePausedError) {
      await deferRefreshJob(env, job, 15 * 60_000);
      return;
    }
    if (error instanceof OverviewCurrentRefreshPendingError) {
      await deferRefreshJob(env, job, error.retryAfterMs);
      return;
    }
    await failRefreshJob(env, job, error);
  }
}

