        enabled: marketCommentary.scheduleEnabled,
        timezone: marketCommentary.scheduleTimezone,
        localTime: marketCommentary.scheduleLocalTime,
        days: marketCommentary.scheduleDays,
      },
      fields: [cronEnabledField, cronTimezoneField, cronLocalTimeField, cronDaysField],
    }, fixedCronExpression),
    buildCronJob({
      key: "social-alerts-scrape",
      label: "Social Alerts Scrape",
      category: "Content/Social",
      description: "Runs Scweet scrapes for all active handles on the configured repeating local slots.",
      kind: "local-time",
      cadence: `Every ${socialAlerts.scrapeIntervalHours} hour${socialAlerts.scrapeIntervalHours === 1 ? "" : "s"} from ${socialAlerts.dailyScrapeTimeLocal} ${socialAlerts.dailyScrapeTimezone}`,
      values: {
        enabled: socialAlerts.dailyScrapeEnabled,
        timezone: socialAlerts.dailyScrapeTimezone,
        localTime: socialAlerts.dailyScrapeTimeLocal,
        intervalHours: socialAlerts.scrapeIntervalHours,
        lookbackDays: socialAlerts.dailyScrapeLookbackDays,
      },
      fields: [
        cronEnabledField,
        cronTimezoneField,
        cronLocalTimeField,
        cronSelectField("intervalHours", "Repeat interval", [1, 2, 3, 4, 6, 8, 12, 24].map((hours) => ({ label: `Every ${hours} hour${hours === 1 ? "" : "s"}`, value: String(hours) }))),
        cronNumberField("lookbackDays", "Lookback days", 1, 10),
      ],
    }, fixedCronExpression),
    ...CENTRAL_CRON_JOB_DEFINITIONS
      .filter((definition) => definition.key !== "overview-eod")
      .map((definition) => {
        const values = centralSettings.get(definition.key) ?? mergeCentralCronValues(definition.key, definition.defaults);
        return centralCronJobToAdminJob(definition, values, fixedCronExpression);
      }),
  ];

  return { fixedCronExpression, timezoneOptions: CRON_TIMEZONE_OPTIONS, jobs };
}

async function updateAdminCronJob(env: Env, key: string, values: CronJobValues): Promise<void> {
  if (key === "overview-eod") {
    const config = await loadDefaultConfigRow(env);
    const id = config?.id ?? "default";
    const timezone = stringValue(values, "timezone", config?.timezone ?? env.APP_TIMEZONE ?? "Australia/Melbourne");
    const localTime = stringValue(values, "localTime", config?.eodRunLocalTime ?? "08:15");
    await updateCentralCronJobSettings(env, key, { enabled: booleanValue(values, "enabled", true) });
    await env.DB.prepare(
      "UPDATE dashboard_configs SET timezone = ?, eod_run_local_time = ?, eod_run_time_label = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
    ).bind(timezone, localTime, formatAutoRefreshLabel(localTime, timezone), id).run();
    await upsertAudit(env, id, "CRON_JOB_PATCH", { key, values: { enabled: values.enabled, timezone, localTime } });
    return;
  }

  if (key === "post-close-bars" || key === "relative-strength-background" || key === "pattern-scanner") {
    const current = await loadWorkerScheduleSettings(env);
    const next = {
      id: current.id,
      rsBackgroundEnabled: key === "relative-strength-background" ? booleanValue(values, "enabled", current.rsBackgroundEnabled) : current.rsBackgroundEnabled,
      rsBackgroundBatchSize: key === "relative-strength-background" ? numberValue(values, "batchSize", current.rsBackgroundBatchSize, 1, 500) : current.rsBackgroundBatchSize,
      rsBackgroundMaxBatchesPerTick: key === "relative-strength-background" ? numberValue(values, "maxBatchesPerTick", current.rsBackgroundMaxBatchesPerTick, 1, 100) : current.rsBackgroundMaxBatchesPerTick,
      rsBackgroundTimeBudgetMs: key === "relative-strength-background" ? numberValue(values, "timeBudgetMs", current.rsBackgroundTimeBudgetMs, 1_000, 30_000) : current.rsBackgroundTimeBudgetMs,
      rsManualCacheReuseEnabled: key === "relative-strength-background" ? booleanValue(values, "manualCacheReuseEnabled", current.rsManualCacheReuseEnabled) : current.rsManualCacheReuseEnabled,
      rsSharedConfigSnapshotFanoutEnabled: key === "relative-strength-background" ? booleanValue(values, "sharedConfigSnapshotFanoutEnabled", current.rsSharedConfigSnapshotFanoutEnabled) : current.rsSharedConfigSnapshotFanoutEnabled,
      postCloseBarsEnabled: key === "post-close-bars" ? booleanValue(values, "enabled", current.postCloseBarsEnabled) : current.postCloseBarsEnabled,
      postCloseBarsOffsetMinutes: key === "post-close-bars" ? numberValue(values, "offsetMinutes", current.postCloseBarsOffsetMinutes, 0, 240) : current.postCloseBarsOffsetMinutes,
      postCloseBarsBatchSize: key === "post-close-bars" ? numberValue(values, "batchSize", current.postCloseBarsBatchSize, 20, 2_000) : current.postCloseBarsBatchSize,
      postCloseBarsMaxBatchesPerTick: key === "post-close-bars" ? numberValue(values, "maxBatchesPerTick", current.postCloseBarsMaxBatchesPerTick, 1, 20) : current.postCloseBarsMaxBatchesPerTick,
      patternScanEnabled: key === "pattern-scanner" ? booleanValue(values, "enabled", current.patternScanEnabled) : current.patternScanEnabled,
      patternScanOffsetMinutes: key === "pattern-scanner" ? numberValue(values, "offsetMinutes", current.patternScanOffsetMinutes, 0, 360) : current.patternScanOffsetMinutes,
      patternScanBatchSize: key === "pattern-scanner" ? numberValue(values, "batchSize", current.patternScanBatchSize, 1, 500) : current.patternScanBatchSize,
      patternScanMaxBatchesPerTick: key === "pattern-scanner" ? numberValue(values, "maxBatchesPerTick", current.patternScanMaxBatchesPerTick, 1, 20) : current.patternScanMaxBatchesPerTick,
    };
    await updateWorkerScheduleSettings(env, next);
    await upsertAudit(env, "default", "CRON_JOB_PATCH", { key, values });
    return;
  }

  if (key === "market-commentary") {
    const current = await loadMarketCommentarySettings(env);
    await updateMarketCommentarySettings(env, {
      ...current,
      scheduleEnabled: booleanValue(values, "enabled", current.scheduleEnabled),
      scheduleTimezone: stringValue(values, "timezone", current.scheduleTimezone),
      scheduleLocalTime: stringValue(values, "localTime", current.scheduleLocalTime),
      scheduleDays: daysValue(values, "days", current.scheduleDays),
    });
    await upsertAudit(env, "default", "CRON_JOB_PATCH", { key, values });
    return;
  }

  if (key === "social-alerts-scrape") {
    const current = await getSocialAlertSettings(env);
    await updateSocialAlertSettings(env, {
      dailyScrapeEnabled: booleanValue(values, "enabled", current.dailyScrapeEnabled),
      dailyScrapeTimeLocal: stringValue(values, "localTime", current.dailyScrapeTimeLocal),
      dailyScrapeTimezone: stringValue(values, "timezone", current.dailyScrapeTimezone),
      dailyScrapeLookbackDays: numberValue(values, "lookbackDays", current.dailyScrapeLookbackDays, 1, 10),
      scrapeIntervalHours: numberValue(values, "intervalHours", current.scrapeIntervalHours, 1, 24),
    });
    await upsertAudit(env, "default", "CRON_JOB_PATCH", { key, values });
    return;
  }

  if (key === "watchlist-compiler") {
    const setId = stringValue(values, "setId", "");
    if (!setId) throw new Error("Choose a watchlist set.");
    await updateWatchlistSet(env, setId, {
      compileDaily: booleanValue(values, "enabled", false),
      dailyCompileTimeLocal: stringValue(values, "localTime", "08:15"),
      dailyCompileTimezone: stringValue(values, "timezone", "Australia/Sydney"),
    });
    await upsertAudit(env, "default", "CRON_JOB_PATCH", { key, setId, values });
    return;
  }

  if (key === "symbol-catalog") {
    await setSymbolCatalogSyncEnabled(env, booleanValue(values, "enabled", false));
    await upsertAudit(env, "default", "CRON_JOB_PATCH", { key, values });
    return;
  }

  if (CENTRAL_CRON_JOB_DEFINITIONS.some((definition) => definition.key === key)) {
    const next = await updateCentralCronJobSettings(env, key, values);
    await upsertAudit(env, "default", "CRON_JOB_PATCH", { key, values: next });
    return;
  }

  throw new Error(`Unknown cron job: ${key}`);
}

type BreadthSentiment = {
  fearGreed?: number | null;
  putCall?: number | null;
  metrics?: Record<string, unknown>;
  dataSource?: string | null;
  provenance?: Record<string, unknown> | null;
};

const hasUsableBreadthRow = isUsableBreadthRow;

let lastSp500BreadthFreshnessAttemptAt = 0;
const SP500_BREADTH_FRESHNESS_ATTEMPT_INTERVAL_MS = 15 * 60 * 1000;

async function recomputeSp500BreadthFromStoredBarsSafe(env: Env, asOfDate: string): Promise<void> {
  const memberCount = await env.DB.prepare(
    "SELECT COUNT(*) as count FROM universe_symbols WHERE universe_id = 'sp500-core'",
  ).first<{ count: number | null }>();
  if ((memberCount?.count ?? 0) > 0) {
    await computeAndStoreBreadth(env, asOfDate, "sp500-core", "Stored Daily Bars", new Date().toISOString());
    return;
  }
  await ensureBreadthRowsSafe(env);
}

async function ensureFreshSp500BreadthSafe(env: Env): Promise<void> {
  const expectedAsOf = latestUsMarketSessionAsOfDate(new Date());
  let latestSnapshotAsOf: string | null = null;
  try {
    const latestSnapshot = await env.DB.prepare(
      "SELECT as_of_date as asOfDate FROM snapshots_meta ORDER BY generated_at DESC LIMIT 1",
    ).first<{ asOfDate: string | null }>();
    latestSnapshotAsOf = latestSnapshot?.asOfDate ?? null;
  } catch {
    latestSnapshotAsOf = null;
  }

  const latestSp500Row = await env.DB.prepare(
    "SELECT as_of_date as asOfDate, advancers, decliners, unchanged, sentiment_json as sentimentJson FROM breadth_snapshots WHERE universe_id = 'sp500-core' ORDER BY as_of_date DESC LIMIT 1",
  ).first<{ asOfDate: string | null; advancers: number; decliners: number; unchanged: number; sentimentJson: string | null }>();

  if (!latestSp500Row) {
    const now = Date.now();
    if (now - lastSp500BreadthFreshnessAttemptAt < SP500_BREADTH_FRESHNESS_ATTEMPT_INTERVAL_MS) return;
    lastSp500BreadthFreshnessAttemptAt = now;
    try {
      await recomputeSp500BreadthFromStoredBarsSafe(env, expectedAsOf);
    } catch (error) {
      console.error("sp500 core stored-bar on-demand recompute failed; falling back to breadth recompute", error);
      await ensureBreadthRowsSafe(env);
    }
    return;
  }
  const sentiment = parseBreadthSentiment(latestSp500Row.sentimentJson);
  const usable = hasUsableBreadthRow({
    advancers: latestSp500Row.advancers,
    decliners: latestSp500Row.decliners,
    unchanged: latestSp500Row.unchanged,
    metrics: sentiment.metrics ?? null,
  });
  const isStaleVsSnapshot =
    Boolean(latestSnapshotAsOf) &&
    Boolean(latestSp500Row.asOfDate) &&
    String(latestSp500Row.asOfDate) < String(latestSnapshotAsOf);
  const isStaleVsExpected =
    Boolean(latestSp500Row.asOfDate) &&
    String(latestSp500Row.asOfDate) < expectedAsOf;
  if (!usable || isStaleVsSnapshot || isStaleVsExpected) {
    const now = Date.now();
    if (now - lastSp500BreadthFreshnessAttemptAt < SP500_BREADTH_FRESHNESS_ATTEMPT_INTERVAL_MS) return;
    lastSp500BreadthFreshnessAttemptAt = now;
    try {
      await recomputeSp500BreadthFromStoredBarsSafe(env, expectedAsOf);
    } catch (error) {
      console.error("sp500 core stored-bar on-demand recompute failed; falling back to breadth recompute", error);
      await ensureBreadthRowsSafe(env);
    }
  }
}

type BreadthStatusDiagnostic = {
  universeId: string;
  expectedAsOfDate: string;
  latestAsOfDate: string | null;
  latestGeneratedAt: string | null;
  memberCount: number;
  currentDateTickers: number;
  coveragePct: number;
  minCoveragePct: number;
  status: "fresh" | "stale" | "missing" | "low_coverage";
  reason: string;
};

function breadthMinCoveragePct(universeId: string): number {
  return minBreadthCoveragePct(universeId);
}

async function loadBreadthStatusDiagnostics(env: Env, expectedAsOfDate: string): Promise<{
  status: "fresh" | "partial" | "stale";
  warning: string | null;
  diagnostics: BreadthStatusDiagnostic[];
}> {
  const diagnostics: BreadthStatusDiagnostic[] = [];
  const unavailableWarning = "Breadth freshness could not be verified quickly; latest stored breadth data may be stale.";
  const membershipByUniverse = new Map<string, Set<string>>();
  const latestSnapshotByUniverse = new Map<
    string,
    { asOfDate: string | null; generatedAt: string | null } | null
  >();
  const snapshotQueryFailures = new Set<string>();
  for (const universeId of CORE_BREADTH_UNIVERSE_IDS) {
    membershipByUniverse.set(universeId, new Set<string>());
  }

  await Promise.all(CORE_BREADTH_UNIVERSE_IDS.map(async (universeId) => {
    try {
      const latestRow = await env.DB.prepare(
        "SELECT as_of_date as asOfDate, generated_at as generatedAt FROM breadth_snapshots WHERE universe_id = ? ORDER BY as_of_date DESC, generated_at DESC LIMIT 1",
      ).bind(universeId).first<{ asOfDate: string | null; generatedAt: string | null }>();
      latestSnapshotByUniverse.set(universeId, latestRow);
    } catch (error) {
      console.error("breadth status diagnostic query failed", { universeId, error });
      snapshotQueryFailures.add(universeId);
      latestSnapshotByUniverse.set(universeId, null);
    }
  }));

  const unavailableDiagnostics = (): BreadthStatusDiagnostic[] => CORE_BREADTH_UNIVERSE_IDS.map((universeId) => {
    const latestRow = latestSnapshotByUniverse.get(universeId) ?? null;
    return {
      universeId,
      expectedAsOfDate,
      latestAsOfDate: latestRow?.asOfDate ?? null,
      latestGeneratedAt: latestRow?.generatedAt ?? null,
      memberCount: membershipByUniverse.get(universeId)?.size ?? 0,
      currentDateTickers: 0,
      coveragePct: 0,
      minCoveragePct: breadthMinCoveragePct(universeId),
      status: "stale",
      reason: unavailableWarning,
    };
  });

  const allTickers = new Set<string>();
  try {
    const membershipRows = await env.DB.prepare(
      `SELECT universe_id as universeId, ticker
       FROM universe_symbols
       WHERE universe_id IN (SELECT CAST(value AS TEXT) FROM json_each(?))
       ORDER BY universe_id, ticker`,
    )
      .bind(JSON.stringify(CORE_BREADTH_UNIVERSE_IDS))
      .all<{ universeId: string; ticker: string }>();
    for (const row of membershipRows.results ?? []) {
      const ticker = row.ticker.trim().toUpperCase();
      const universeTickers = membershipByUniverse.get(row.universeId);
      if (!universeTickers || !ticker) continue;
      universeTickers.add(ticker);
      allTickers.add(ticker);
    }
  } catch (error) {
    console.error("breadth status membership query failed", { error });
    return {
      status: "stale",
      warning: unavailableWarning,
      diagnostics: unavailableDiagnostics(),
    };
  }

  let currentDateTickerSet: Set<string>;
  try {
    currentDateTickerSet = await loadMarketDataTickersWithBarOnDate(env, Array.from(allTickers), expectedAsOfDate);
  } catch (error) {
    console.error("breadth status coverage query failed", { error });
    return {
      status: "stale",
      warning: unavailableWarning,
      diagnostics: unavailableDiagnostics(),
    };
  }

  for (const universeId of CORE_BREADTH_UNIVERSE_IDS) {
    const members = membershipByUniverse.get(universeId) ?? new Set<string>();
    const memberCount = members.size;
    let currentDateTickers = 0;
    for (const ticker of members) {
      if (currentDateTickerSet.has(ticker)) currentDateTickers += 1;
    }
    const coveragePct = memberCount > 0 ? (currentDateTickers / memberCount) * 100 : 0;
    const latestRow = latestSnapshotByUniverse.get(universeId) ?? null;
    if (snapshotQueryFailures.has(universeId)) {
      diagnostics.push({
        universeId,
        expectedAsOfDate,
        latestAsOfDate: null,
        latestGeneratedAt: null,
        memberCount,
        currentDateTickers,
        coveragePct,
        minCoveragePct: breadthMinCoveragePct(universeId),
        status: "stale",
        reason: unavailableWarning,
      });
      continue;
    }

    const minCoveragePct = breadthMinCoveragePct(universeId);
    const latestAsOfDate = latestRow?.asOfDate ?? null;
    let status: BreadthStatusDiagnostic["status"] = "fresh";
    let reason = `Breadth snapshot is current for ${expectedAsOfDate}.`;
    if (memberCount === 0) {
      status = "missing";
      reason = "No universe members are stored for this breadth universe.";
    } else if (!isBreadthUniverseMemberCountValid(universeId, memberCount)) {
      status = "low_coverage";
      reason = `Stored universe membership is invalid (${memberCount} members); breadth health is fail-closed until a validated universe version is active.`;
    } else if (!latestAsOfDate) {
      status = "missing";
      reason = `No stored breadth snapshot exists; coverage for ${expectedAsOfDate} is ${coveragePct.toFixed(1)}%.`;
    } else if (latestAsOfDate < expectedAsOfDate) {
      status = coveragePct >= minCoveragePct ? "stale" : "low_coverage";
      reason = `Latest stored breadth snapshot is ${latestAsOfDate}; expected ${expectedAsOfDate}. Current-date bar coverage is ${coveragePct.toFixed(1)}% (${currentDateTickers}/${memberCount}), minimum ${minCoveragePct}%.`;
    } else if (coveragePct < minCoveragePct) {
      status = "low_coverage";
      reason = `Current-date bar coverage is ${coveragePct.toFixed(1)}% (${currentDateTickers}/${memberCount}), below the ${minCoveragePct}% minimum.`;
    }
    diagnostics.push({
      universeId,
      expectedAsOfDate,
      latestAsOfDate,
      latestGeneratedAt: latestRow?.generatedAt ?? null,
      memberCount,
      currentDateTickers,
      coveragePct,
      minCoveragePct,
      status,
      reason,
    });
  }

  const problemDiagnostics = diagnostics.filter((diagnostic) => diagnostic.status !== "fresh");
  return {
    status: problemDiagnostics.length === 0 ? "fresh" : problemDiagnostics.length === diagnostics.length ? "stale" : "partial",
    warning: problemDiagnostics.length
      ? `Breadth history is not current for ${expectedAsOfDate}: ${problemDiagnostics.slice(0, 3).map((diagnostic) => `${diagnostic.universeId} ${diagnostic.latestAsOfDate ?? "missing"}`).join(", ")}.`
      : null,
    diagnostics,
  };
}

function parseBreadthSentiment(raw: unknown): BreadthSentiment {
  if (typeof raw !== "string" || raw.trim().length === 0) return {};
  try {
    return JSON.parse(raw) as BreadthSentiment;
  } catch {
    return {};
  }
}

function deriveStoredQuoteFreshness(input: {
  ticker: string;
  barDate: string | null | undefined;
  expectedAsOfDate: string;
  source: string | null | undefined;
}): { quoteFreshnessStatus: QuoteFreshnessStatus; quoteFreshnessReason: string; quoteSource: string | null } {
  const ticker = input.ticker.trim().toUpperCase();
  const barDate = input.barDate ?? null;
  const source = input.source ?? "daily-bars";
  if (!barDate) {
    return {
      quoteFreshnessStatus: "unavailable",
      quoteFreshnessReason: `No stored daily bar is available for ${ticker} from the current sources.`,
      quoteSource: source,
    };
  }
  if (barDate === input.expectedAsOfDate) {
    return {
      quoteFreshnessStatus: "fresh",
      quoteFreshnessReason: `Stored daily bar is current for ${input.expectedAsOfDate}.`,
      quoteSource: source,
    };
  }
  return {
    quoteFreshnessStatus: "stale",
    quoteFreshnessReason: `Last stored daily bar is ${barDate}; expected ${input.expectedAsOfDate}.`,
    quoteSource: source,
  };
}

export async function getStored1dStatsMap(env: Env, tickers: string[]): Promise<Map<string, { change1d: number | null; lastPrice: number | null; barDate: string | null; source: string }>> {
  const unique = Array.from(new Set(tickers.map((t) => t.toUpperCase()).filter(Boolean)));
  const map = new Map<string, { change1d: number | null; lastPrice: number | null; barDate: string | null; source: string }>();
  if (env.MARKET_HISTORY_DB && env.EOD_READ_ENABLED === "true") {
    for (const [ticker, stats] of await getStoredHoldingStats(env, unique)) {
      map.set(ticker, { ...stats, source: stats.source ?? "daily-bars" });
    }
    return map;
  }
  for (let index = 0; index < unique.length; index += 80) {
    const batch = unique.slice(index, index + 80);
    if (batch.length === 0) continue;
    const rows = env.MARKET_HISTORY_DB ? { results: (await loadMarketHistory(env, { tickers: batch, limitPerTicker: 2 }))
      .sort((left, right) => left.ticker.localeCompare(right.ticker) || right.date.localeCompare(left.date)) } : await getMarketDataDb(env).prepare(
      `SELECT ticker, date, c, rowNumber FROM (
         SELECT ticker, date, c, ROW_NUMBER() OVER (PARTITION BY ticker ORDER BY date DESC) as rowNumber
         FROM alpaca_daily_bars
         WHERE feed = ? AND ticker IN (${batch.map(() => "?").join(",")})
       )
       WHERE rowNumber <= 2
       ORDER BY ticker ASC, rowNumber ASC`,
    )
      .bind(marketDataFeed(env), ...batch)
      .all<{ ticker: string; date: string; c: number; rowNumber: number }>();
    const barsByTicker = new Map<string, Array<{ date: string; c: number }>>();
    for (const row of rows.results ?? []) {
      const ticker = row.ticker.toUpperCase();
      const bars = barsByTicker.get(ticker) ?? [];
      bars.push({ date: row.date, c: row.c });
      barsByTicker.set(ticker, bars);
    }
    for (const [ticker, bars] of barsByTicker.entries()) {
      const latest = bars[0] ?? null;
      const previous = bars[1] ?? null;
      const lastPrice = latest?.c ?? null;
      const prev = previous?.c ?? null;
      map.set(ticker, {
        change1d: lastPrice && prev ? ((lastPrice - prev) / prev) * 100 : null,
        lastPrice,
        barDate: latest?.date ?? null,
        source: "daily-bars",
      });
    }
  }
  return map;
}

async function loadYahooPreferredDailyBarTickers(env: Env, tickers: string[]): Promise<string[]> {
  const preferred = new Set<string>();
  for (let i = 0; i < tickers.length; i += 80) {
    const batch = tickers.slice(i, i + 80).map((ticker) => ticker.toUpperCase()).filter(Boolean);
    if (batch.length === 0) continue;
    const placeholders = batch.map(() => "?").join(",");
    try {
      const rows = await env.DB.prepare(
        `SELECT ticker FROM symbols WHERE ticker IN (${placeholders}) AND lower(COALESCE(asset_class, '')) = 'etf'
         UNION
         SELECT ticker FROM etf_watchlists WHERE ticker IN (${placeholders})`,
      )
        .bind(...batch, ...batch)
        .all<{ ticker: string }>();
      for (const row of rows.results ?? []) {
        const ticker = row.ticker?.trim().toUpperCase();
        if (ticker) preferred.add(ticker);
      }
    } catch (error) {
      console.error("load yahoo preferred daily-bar tickers failed", { batchSize: batch.length, error });
    }
  }
  return Array.from(preferred);
}

type RefreshRecentBarsOptions = {
  fallbackScope?: "preferred" | "all";
  target?: DailyBarStorageTarget;
  throwOnError?: boolean;
};

async function refreshRecentBarsForTickers(
  env: Env,
  tickers: string[],
  maxTickers = 1600,
  lookbackDays = 21,
  replaceExisting = false,
  options: RefreshRecentBarsOptions = {},
): Promise<void> {
  const unique = Array.from(new Set(tickers.map((t) => t.toUpperCase()).filter(Boolean))).slice(0, Math.max(1, maxTickers));
  if (unique.length === 0) return;
  let provider: ReturnType<typeof getProvider> | null = null;
  try {
    if (options.target === "market") {
      provider = getProvider(env, { fallbackEnabled: false });
    } else {
      const yahooPreferredTickers = await loadYahooPreferredDailyBarTickers(env, unique);
      provider = getProvider(env, {
        yahooPreferredTickers,
        fallbackScope: options.fallbackScope ?? "preferred",
      });
    }
  } catch (error) {
    console.error("market data provider unavailable for recent bar refresh", error);
    if (options.throwOnError) throw error;
    return;
  }
  try {
    const end = latestUsMarketSessionAsOfDate(new Date());
    const start = new Date(Date.now() - Math.max(1, lookbackDays) * 86400_000).toISOString().slice(0, 10);
    await refreshDailyBarsIncremental(env, {
      provider,
      tickers: unique,
      startDate: start,
      endDate: end,
      replaceExisting,
      target: options.target,
    });
  } catch (error) {
    console.error("refresh recent bars for tickers failed", error);
    if (options.throwOnError) throw error;
  }
}

app.get("/api/health", async (c) => {
  const mode = marketPipelineMode(c.env);
  const capacity = await loadDatabaseCapacity(c.env);
  const [core, market, ops, history] = capacity;
  const unhealthyLevels = new Set(["critical", "halt", "unavailable"]);
  const ok = core.ok && market.ok && ops.ok
    && !capacity.some((database) => unhealthyLevels.has(database.level));
  c.header("Cache-Control", "no-store");
  return c.json({ ok, pipelineMode: mode, databases: { core, market, ops, ...(history ? { history } : {}) } }, ok ? 200 : 503);
});

app.get("/api/status", async (c) => {
  const page = (c.req.query("page") ?? "overview").trim();
  if (c.env.EOD_READ_ENABLED === "true") {
    c.header("Cache-Control", "no-store");
    return c.json(await loadEodApiStatus(c.env,page));
  }
  let config:
    | {
        id: string;
        name: string;
        timezone: string;
        eodRunLocalTime: string;
        eodRunTimeLabel: string;
      }
    | null = null;
  try {
    config = await c.env.DB.prepare(
      "SELECT id, name, timezone, eod_run_local_time as eodRunLocalTime, eod_run_time_label as eodRunTimeLabel FROM dashboard_configs WHERE is_default = 1 LIMIT 1",
    ).first<{ id: string; name: string; timezone: string; eodRunLocalTime: string; eodRunTimeLabel: string }>();
  } catch {
    const legacy = await c.env.DB.prepare(
      "SELECT id, name, timezone, eod_run_time_label as eodRunTimeLabel FROM dashboard_configs WHERE is_default = 1 LIMIT 1",
    ).first<{ id: string; name: string; timezone: string; eodRunTimeLabel: string }>();
    config = legacy
      ? {
          ...legacy,
          eodRunLocalTime: "08:15",
          eodRunTimeLabel: legacy.eodRunTimeLabel || formatAutoRefreshLabel("08:15", legacy.timezone),
        }
      : null;
  }

  const latestAllowedAsOfDate = latestUsMarketSessionAsOfDate(new Date());
  const overviewRecoveryEnabled = isOverviewPublicationRecoveryEnabled(c.env);
  type OverviewLatestRow = {
        asOfDate?: string;
        generatedAt?: string;
        providerLabel?: string;
        expectedAsOfDate?: string | null;
        freshnessStatus?: "fresh" | "partial" | "stale" | string | null;
        freshnessCoveragePct?: number | null;
        freshnessCurrentCount?: number | null;
        freshnessEligibleCount?: number | null;
        freshnessCriticalMissingJson?: string | null;
        freshnessMinBarDate?: string | null;
        freshnessMaxBarDate?: string | null;
        freshnessWarning?: string | null;
        quoteOverlayRequestedCount?: number | null;
        quoteOverlayReturnedCount?: number | null;
        quoteOverlayError?: string | null;
        quoteOverlayMissingSampleJson?: string | null;
        as_of_date?: string;
        generated_at?: string;
        provider_label?: string;
      };
  let overviewLatest: OverviewLatestRow | null = null;
  if (overviewRecoveryEnabled) {
    const published = (await loadPublishedOverviewGeneration(c.env, config?.id ?? "default")).generation;
    overviewLatest = published ? {
      asOfDate: published.asOfDate,
      generatedAt: published.generatedAt,
      providerLabel: published.providerLabel,
      expectedAsOfDate: published.expectedAsOfDate,
      freshnessStatus: published.freshnessStatus,
      freshnessCoveragePct: published.freshnessCoveragePct,
      freshnessCurrentCount: published.freshnessCurrentCount,
      freshnessEligibleCount: published.freshnessEligibleCount,
      freshnessCriticalMissingJson: published.freshnessCriticalMissingJson,
      freshnessMinBarDate: published.freshnessMinBarDate,
      freshnessMaxBarDate: published.freshnessMaxBarDate,
      freshnessWarning: published.freshnessWarning,
      quoteOverlayRequestedCount: published.quoteOverlayRequestedCount,
      quoteOverlayReturnedCount: published.quoteOverlayReturnedCount,
      quoteOverlayError: published.quoteOverlayError,
      quoteOverlayMissingSampleJson: published.quoteOverlayMissingSampleJson,
    } : null;
  } else try {
    overviewLatest = await c.env.DB.prepare(
      "SELECT as_of_date as asOfDate, generated_at as generatedAt, provider_label as providerLabel, expected_as_of_date as expectedAsOfDate, freshness_status as freshnessStatus, freshness_coverage_pct as freshnessCoveragePct, freshness_current_count as freshnessCurrentCount, freshness_eligible_count as freshnessEligibleCount, freshness_critical_missing_json as freshnessCriticalMissingJson, freshness_min_bar_date as freshnessMinBarDate, freshness_max_bar_date as freshnessMaxBarDate, freshness_warning as freshnessWarning, quote_overlay_requested_count as quoteOverlayRequestedCount, quote_overlay_returned_count as quoteOverlayReturnedCount, quote_overlay_error as quoteOverlayError, quote_overlay_missing_sample_json as quoteOverlayMissingSampleJson FROM snapshots_meta WHERE config_id = ? AND as_of_date <= ? ORDER BY as_of_date DESC, generated_at DESC LIMIT 1",
    )
      .bind(config?.id ?? "default", latestAllowedAsOfDate)
      .first<OverviewLatestRow>();
  } catch {
    overviewLatest = await c.env.DB.prepare(
      "SELECT as_of_date as asOfDate, generated_at as generatedAt, provider_label as providerLabel FROM snapshots_meta WHERE config_id = ? AND as_of_date <= ? ORDER BY as_of_date DESC, generated_at DESC LIMIT 1",
    )
      .bind(config?.id ?? "default", latestAllowedAsOfDate)
      .first<OverviewLatestRow>();
  }
  const breadthDashboard = await loadBreadthDashboard(c.env, 1).catch((error) => {
    console.error("status breadth diagnostics load failed", error);
    return {
      generatedAt: null,
      providerLabel: "Alpaca SIP split-adjusted completed daily bars; Alpaca IEX exact-session fallback.",
      overallHealth: "stale" as const,
      warning: "Breadth freshness could not be verified because the market-data database is unavailable.",
      universes: CORE_BREADTH_UNIVERSE_IDS.map((universeId) => ({
        universeId,
        displayedAsOfSession: null,
        displayedSnapshot: null,
        staleTradingSessions: 0,
        memberCount: 0,
        exactSessionCount: 0,
        coveragePct: 0,
        requiredCoveragePct: minBreadthCoveragePct(universeId),
        freshness: "missing" as const,
        error: {
          code: "market-data-db-unavailable",
          message: "Breadth freshness could not be verified because the market-data database is unavailable.",
        },
      })),
    };
  });

  const normalizedOverview = {
    lastUpdated: overviewLatest?.generatedAt ?? overviewLatest?.generated_at ?? null,
    asOfDate: overviewLatest?.asOfDate ?? overviewLatest?.as_of_date ?? null,
    providerLabel: overviewLatest?.providerLabel ?? overviewLatest?.provider_label ?? null,
  };
  const overviewStoredExpectedAsOfDate = overviewLatest?.expectedAsOfDate ?? normalizedOverview.asOfDate ?? latestAllowedAsOfDate;
  const overviewStoredFreshnessMatchesExpected =
    normalizedOverview.asOfDate === latestAllowedAsOfDate && overviewStoredExpectedAsOfDate === latestAllowedAsOfDate;
  const overviewStoredFreshnessHasDiagnostics = Number(overviewLatest?.freshnessEligibleCount ?? 0) > 0
    && (overviewRecoveryEnabled || overviewStoredFreshnessMatchesExpected);
  const overviewStoredFreshnessUnknownWarning =
    "Snapshot freshness diagnostics are unavailable for the displayed data; refresh this page to rebuild row-level bar dates.";
  let overviewFreshness = {
    expectedAsOfDate: overviewStoredFreshnessMatchesExpected ? overviewStoredExpectedAsOfDate : latestAllowedAsOfDate,
    freshnessStatus: overviewStoredFreshnessHasDiagnostics && (overviewLatest?.freshnessStatus === "fresh" || overviewLatest?.freshnessStatus === "partial" || overviewLatest?.freshnessStatus === "stale")
      ? overviewStoredFreshnessMatchesExpected ? overviewLatest.freshnessStatus : "stale"
      : overviewStoredFreshnessMatchesExpected
        ? "stale"
        : overviewRecoveryEnabled ? "stale" : null,
    freshnessCoveragePct: overviewStoredFreshnessHasDiagnostics ? overviewLatest?.freshnessCoveragePct ?? null : null,
    freshnessCurrentCount: overviewStoredFreshnessHasDiagnostics ? overviewLatest?.freshnessCurrentCount ?? null : null,
    freshnessEligibleCount: overviewStoredFreshnessHasDiagnostics ? overviewLatest?.freshnessEligibleCount ?? null : null,
    freshnessCriticalMissingTickers: overviewStoredFreshnessHasDiagnostics ? (() => {
      try {
        const parsed = JSON.parse(overviewLatest?.freshnessCriticalMissingJson ?? "[]");
        return Array.isArray(parsed) ? parsed.map((ticker) => String(ticker)).filter(Boolean) : [];
      } catch {
        return [];
      }
    })() : [],
    freshnessMinBarDate: overviewStoredFreshnessHasDiagnostics ? overviewLatest?.freshnessMinBarDate ?? null : null,
    freshnessMaxBarDate: overviewStoredFreshnessHasDiagnostics ? overviewLatest?.freshnessMaxBarDate ?? null : null,
    freshnessWarning: overviewStoredFreshnessHasDiagnostics
      ? overviewLatest?.freshnessWarning ?? null
      : overviewStoredFreshnessMatchesExpected
        ? overviewStoredFreshnessUnknownWarning
        : overviewRecoveryEnabled
          ? normalizedOverview.asOfDate
            ? `Published Overview is ${normalizedOverview.asOfDate}; expected ${latestAllowedAsOfDate}.`
            : "No published Overview generation is available."
          : null,
    quoteOverlayRequestedCount: overviewStoredFreshnessHasDiagnostics ? overviewLatest?.quoteOverlayRequestedCount ?? null : null,
    quoteOverlayReturnedCount: overviewStoredFreshnessHasDiagnostics ? overviewLatest?.quoteOverlayReturnedCount ?? null : null,
    quoteOverlayError: overviewStoredFreshnessHasDiagnostics ? overviewLatest?.quoteOverlayError ?? null : null,
    quoteOverlayMissingSample: overviewStoredFreshnessHasDiagnostics ? (() => {
      try {
        const parsed = JSON.parse(overviewLatest?.quoteOverlayMissingSampleJson ?? "[]");
        return Array.isArray(parsed) ? parsed.map((ticker) => String(ticker)).filter(Boolean) : [];
      } catch {
        return [];
      }
    })() : [],
  };
  if (!overviewFreshness.freshnessStatus && !overviewRecoveryEnabled) {
    try {
      const computed = await computeOverviewFreshnessDiagnostics(c.env, latestAllowedAsOfDate, config?.id ?? "default");
      overviewFreshness = {
        expectedAsOfDate: computed.expectedAsOfDate,
        freshnessStatus: computed.status,
        freshnessCoveragePct: computed.coveragePct,
        freshnessCurrentCount: computed.currentCount,
        freshnessEligibleCount: computed.eligibleCount,
        freshnessCriticalMissingTickers: computed.criticalMissingTickers,
        freshnessMinBarDate: computed.minBarDate,
        freshnessMaxBarDate: computed.maxBarDate,
        freshnessWarning: computed.warning,
        quoteOverlayRequestedCount: null,
        quoteOverlayReturnedCount: null,
        quoteOverlayError: null,
        quoteOverlayMissingSample: [],
      };
    } catch (error) {
      console.error("status overview freshness computation failed", error);
      overviewFreshness = {
        ...overviewFreshness,
        freshnessStatus: "stale",
        freshnessWarning: "Overview freshness could not be verified.",
      };
    }
  }
  const normalizedBreadth = {
    lastUpdated: breadthDashboard.generatedAt,
    asOfDate: breadthDashboard.universes[0]?.displayedAsOfSession ?? null,
  };
  const useBreadthStatus = page === "breadth";
  const normalizedLastUpdated = useBreadthStatus
    ? normalizedBreadth.lastUpdated
    : overviewRecoveryEnabled
      ? normalizedOverview.lastUpdated
      : normalizedOverview.lastUpdated ?? normalizedBreadth.lastUpdated;
  const normalizedAsOf = useBreadthStatus
    ? normalizedBreadth.asOfDate
    : overviewRecoveryEnabled
      ? normalizedOverview.asOfDate
      : normalizedOverview.asOfDate ?? normalizedBreadth.asOfDate;
  const normalizedProvider = useBreadthStatus
    ? breadthDashboard.providerLabel
    : normalizedOverview.providerLabel
      ?? "Alpaca SIP split-adjusted completed daily bars; Alpaca IEX exact-session fallback";
  const overviewRecovery = overviewRecoveryEnabled
    ? await loadOverviewRecovery(c.env, new Date(), config?.id ?? "default")
    : null;
  const servingState = overviewRecovery?.servingState
    ?? (!normalizedOverview.asOfDate
      ? "unavailable"
      : normalizedOverview.asOfDate < latestAllowedAsOfDate
        ? "stale_fallback"
        : "ready");
  const staleTradingSessions = useBreadthStatus
    ? Math.max(0, ...breadthDashboard.universes.map((universe) => universe.staleTradingSessions))
    : overviewRecovery?.staleTradingSessions ?? 0;

  return c.json({
    configId: config?.id ?? "default",
    timezone: config?.timezone ?? c.env.APP_TIMEZONE ?? "Australia/Melbourne",
    autoRefreshLabel: formatAutoRefreshLabel(config?.eodRunLocalTime, config?.timezone),
    autoRefreshLocalTime: config?.eodRunLocalTime ?? "08:15",
    lastUpdated: normalizedLastUpdated ?? (normalizedAsOf ? `${normalizedAsOf}T00:00:00Z` : null),
    asOfDate: normalizedAsOf,
    providerLabel: normalizedProvider,
    servingState,
    staleTradingSessions,
    overviewRecovery,
    dataProvider: c.env.DATA_PROVIDER ?? "alpaca",
    ...overviewFreshness,
    breadthExpectedAsOfDate: latestAllowedAsOfDate,
    breadthStatus: breadthDashboard.overallHealth,
    breadthLatestAsOfDate: normalizedBreadth.asOfDate,
    breadthLastUpdated: normalizedBreadth.lastUpdated,
    breadthWarning: breadthDashboard.warning,
    breadthDiagnostics: breadthDashboard.universes.map((universe) => ({
      universeId: universe.universeId,
      expectedAsOfDate: latestAllowedAsOfDate,
      latestAsOfDate: universe.displayedAsOfSession,
      latestGeneratedAt: universe.displayedSnapshot?.generatedAt ?? null,
      memberCount: universe.memberCount,
      currentDateTickers: universe.exactSessionCount,
      coveragePct: universe.coveragePct,
      minCoveragePct: universe.requiredCoveragePct,
      status: universe.freshness,
      reason: universe.error?.message ?? `Breadth snapshot is current for ${latestAllowedAsOfDate}.`,
    })),
  });
});

