app.post("/api/admin/peer-groups/bootstrap", async (c) => {
  if (!isAuthed(c.req.raw, c.env)) return c.json({ error: "Unauthorized" }, 401);
  const payload = peerBootstrapSchema.parse(await c.req.json().catch(() => ({})));
  const requestedTickers = uniqueTickers(payload.tickers ?? []);
  const candidates = requestedTickers.length > 0
    ? requestedTickers.map((ticker) => ({ ticker, name: null, exchange: null }))
    : await listPeerBootstrapCandidates(c.env, payload);
  const rows: Array<{
    ticker: string;
    ok: boolean;
    groupId?: string;
    insertedTickers?: string[];
    sourceBreakdown?: Record<string, number>;
    error?: string;
  }> = [];
  for (const candidate of candidates) {
    try {
      const result = await seedPeerGroupForTicker(c.env, candidate.ticker, {
        providerMode: payload.providerMode,
        enrichPeers: payload.enrichPeers,
      });
      rows.push({
        ticker: candidate.ticker,
        ok: true,
        groupId: result.groupId,
        insertedTickers: result.insertedTickers,
        sourceBreakdown: result.sourceBreakdown,
      });
      await upsertAudit(c.env, "default", "PEER_GROUP_BOOTSTRAP_SEED", result);
    } catch (error) {
      rows.push({
        ticker: candidate.ticker,
        ok: false,
        error: error instanceof Error ? error.message : "Peer bootstrap seed failed.",
      });
    }
  }
  return c.json({
    ok: true,
    requested: requestedTickers.length > 0 ? requestedTickers.length : payload.limit,
    attempted: candidates.length,
    rows,
  });
});

