app.get("/api/admin/overview-current/audit", async (c) => {
  if (!isOverviewRolloutRequestAuthorized(c.req.raw, c.env)) return c.json({ error: "Unauthorized" }, 401);
  const date = c.req.query("date") ?? latestUsMarketSessionAsOfDate(new Date());
  const configId = c.req.query("configId") ?? "default";
  try {
    const currentRows = await loadOverviewCurrentData(c.env, configId, date);
    const currentTickers = Array.from(currentRows.keys());
    const tickersWithCurrentBars = await loadMarketDataTickersWithBarOnDate(c.env, currentTickers, date);
    const storedRows = await c.env.DB.prepare(
      `SELECT sr.ticker, sr.price, sr.change_1d as change1d, sr.change_1w as change1w,
              sr.change_3m as change3m, sr.change_6m as change6m, sr.ytd
       FROM snapshot_rows sr
       JOIN snapshots_meta sm ON sm.id = sr.snapshot_id
       WHERE sm.config_id = ? AND sm.as_of_date = ?
       ORDER BY sr.ticker`,
    ).bind(configId, date).all<{
      ticker: string;
      price: number | null;
      change1d: number | null;
      change1w: number | null;
      change3m: number | null;
      change6m: number | null;
      ytd: number | null;
    }>();
    const storedByTicker = new Map((storedRows.results ?? []).map((row) => [row.ticker.toUpperCase(), row]));
    const rows = Array.from(currentRows.values()).map((row) => {
      const missingFields = OVERVIEW_REQUIRED_CURRENT_FIELDS.filter((field) => !row.fieldSources[field]);
      const alpacaAssetStatus = row.providerStatuses.alpacaAsset?.status;
      const historyTerminal = alpacaAssetStatus === "unsupported" || alpacaAssetStatus === "auth-blocked";
      const historyReady = tickersWithCurrentBars.has(row.ticker.toUpperCase());
      const historyNeedsRepair = !historyReady && !historyTerminal;
      const currentNeedsRepair = doesOverviewCurrentRowNeedRepair(row);
      return {
        ticker: row.ticker,
        sessionDate: row.sessionDate,
        status: row.status,
        complete: isOverviewCurrentRowComplete(row),
        needsRepair: currentNeedsRepair || historyNeedsRepair,
        currentNeedsRepair,
        historyReady,
        historyNeedsRepair,
        missingFields,
        reason: row.reason,
        fieldSources: row.fieldSources,
        providerStatuses: row.providerStatuses,
        current: {
          price: row.price,
          change1d: row.change1d,
          change1w: row.change1w,
          change3m: row.change3m,
          change6m: row.change6m,
          ytd: row.ytd,
        },
        storedSnapshot: storedByTicker.get(row.ticker) ?? null,
      };
    });
    return c.json({
      configId,
      sessionDate: date,
      total: rows.length,
      fresh: rows.filter((row) => row.status === "fresh").length,
      complete: rows.filter((row) => row.complete).length,
      historyReady: rows.filter((row) => row.historyReady).length,
      historyNeedsRepair: rows.filter((row) => row.historyNeedsRepair).length,
      incomplete: rows.filter((row) => !row.complete).length,
      needsRepair: rows.filter((row) => row.needsRepair).length,
      retrying: rows.filter((row) => row.status === "retrying").length,
      unavailable: rows.filter((row) => row.status === "unavailable").length,
      rows,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Overview current-data audit failed.";
    console.error("admin overview current-data audit failed", { date, configId, error });
    return c.json({ error: message }, 500);
  }
});

app.post("/api/admin/etf-sync-backfill", async (c) => {
  if (!isAuthed(c.req.raw, c.env)) return c.json({ error: "Unauthorized" }, 401);
  const body = (await c.req.json().catch(() => ({}))) as { limit?: number };
  // Keep this low to avoid Cloudflare subrequest caps in one request.
  const limit = Math.max(1, Math.min(5, Number(body.limit ?? 3)));
  const rows = await (async () => {
    try {
      return await c.env.DB.prepare(
        "SELECT w.ticker as ticker, s.last_synced_at as lastSyncedAt, s.status as status, s.records_count as recordsCount, s.coverage as coverage, s.source_tier as sourceTier, COALESCE(cs.actualRecordsCount, 0) as actualRecordsCount FROM (SELECT DISTINCT ticker FROM etf_watchlists) w LEFT JOIN etf_constituent_sync_status s ON s.etf_ticker = w.ticker LEFT JOIN (SELECT etf_ticker as etfTicker, COUNT(*) as actualRecordsCount FROM etf_constituents GROUP BY etf_ticker) cs ON cs.etfTicker = w.ticker ORDER BY CASE WHEN s.last_synced_at IS NULL THEN 0 WHEN COALESCE(s.status, '') = 'error' THEN 1 WHEN COALESCE(s.coverage, '') = 'partial' OR COALESCE(s.source_tier, '') = 'partial' OR COALESCE(s.status, '') = 'partial' THEN 2 WHEN COALESCE(cs.actualRecordsCount, s.records_count, 0) = 0 THEN 3 ELSE 4 END, datetime(COALESCE(s.last_synced_at, '1970-01-01 00:00:00')) ASC, w.ticker ASC",
      ).all<{ ticker: string; lastSyncedAt: string | null; status: string | null; recordsCount: number | null; coverage?: string | null; sourceTier?: string | null; actualRecordsCount: number | null }>();
    } catch {
      return await c.env.DB.prepare(
        "SELECT w.ticker as ticker, s.last_synced_at as lastSyncedAt, s.status as status, s.records_count as recordsCount, COALESCE(cs.actualRecordsCount, 0) as actualRecordsCount FROM (SELECT DISTINCT ticker FROM etf_watchlists) w LEFT JOIN etf_constituent_sync_status s ON s.etf_ticker = w.ticker LEFT JOIN (SELECT etf_ticker as etfTicker, COUNT(*) as actualRecordsCount FROM etf_constituents GROUP BY etf_ticker) cs ON cs.etfTicker = w.ticker ORDER BY CASE WHEN s.last_synced_at IS NULL THEN 0 WHEN COALESCE(s.status, '') = 'error' THEN 1 WHEN COALESCE(cs.actualRecordsCount, s.records_count, 0) = 0 THEN 2 ELSE 3 END, datetime(COALESCE(s.last_synced_at, '1970-01-01 00:00:00')) ASC, w.ticker ASC",
      ).all<{ ticker: string; lastSyncedAt: string | null; status: string | null; recordsCount: number | null; coverage?: string | null; sourceTier?: string | null; actualRecordsCount: number | null }>();
    }
  })();
  const candidates = (rows.results ?? [])
    .filter((r) => (r.actualRecordsCount ?? r.recordsCount ?? 0) === 0 || r.status === "error" || r.status === "partial" || r.coverage === "partial" || r.sourceTier === "partial" || isStaleDate(r.lastSyncedAt, 45))
    .slice(0, limit);

  let ok = 0;
  const failed: Array<{ ticker: string; error: string }> = [];
  for (const row of candidates) {
    try {
      await syncEtfConstituents(c.env, row.ticker);
      ok += 1;
    } catch (error) {
      failed.push({ ticker: row.ticker, error: error instanceof Error ? error.message : "sync failed" });
    }
  }

  return c.json({
    ok: true,
    attempted: candidates.length,
    synced: ok,
    failed,
  });
});

