    ? body.symbols.map((value) => String(value).trim().toUpperCase()).filter((value) => /^[A-Z.\-]{1,20}$/.test(value)).slice(0, 20)
    : [];
  if (symbols.length === 0) return c.json({ error: "Provide 1-20 symbols." }, 400);
  try {
    const provider = getProvider({ ...c.env, ALPACA_FEED: typeof body.feed === "string" ? body.feed : c.env.ALPACA_FEED });
    const snapshots = provider.getQuoteSnapshot ? await provider.getQuoteSnapshot(symbols) : {};
    return c.json({
      ok: true,
      providerLabel: provider.label,
      feed: typeof body.feed === "string" ? body.feed : c.env.ALPACA_FEED ?? "iex",
      requestedSymbols: symbols,
      returnedSymbols: Object.keys(snapshots).sort(),
      returnedSnapshots: Object.keys(snapshots).length,
      sampleFields: Object.fromEntries(Object.entries(snapshots).slice(0, 5).map(([ticker, snapshot]) => [ticker, Object.keys(snapshot).sort()])),
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Alpaca snapshot diagnostic failed.";
    return c.json({ error: message.slice(0, 500), requestedSymbols: symbols }, 502);
  }
});

app.post("/api/admin/refresh-page", async (c) => {
  if (!isAuthed(c.req.raw, c.env)) return c.json({ error: "Unauthorized" }, 401);
  const body = (await c.req.json().catch(() => ({}))) as { page?: string; ticker?: string | null };
  const rawPage = String(body.page ?? "").trim().toLowerCase();
  const page = (rawPage || "overview") as RefreshPage;
  if (!["overview", "breadth", "sectors", "thirteenf", "admin", "ticker", "alerts", "scans", "pattern-scanner", "watchlist-compiler", "gappers", "earnings", "market-commentary"].includes(page)) {
    return c.json({ error: "Unsupported page key." }, 400);
  }
  if (eodEnabled(c.env) && ["overview","breadth"].includes(page)) {
    const session=await expectedEodSession(c.env);
    if (!session) return c.json({error:"exchange-calendar-unavailable"},503);
    const run=await requestEodRefresh(c.env,session);
    return c.json({ok:true,page,jobId:run.id,status:"queued",refreshedTickers:0,pollAfterMs:5000,notes:"EOD refresh queued; completion is tracked by the daily runner."},202);
  }
  const pipelineMode = marketPipelineMode(c.env);
  if (pipelineMode !== "active" && ["overview", "breadth", "sectors", "thirteenf", "admin", "ticker"].includes(page)) {
    try {
      const job = await requestRefreshJob(c.env, { page, ticker: body.ticker ?? null, requestedBy: "admin" });
      return c.json({
        ok: true,
        page,
        refreshedTickers: 0,
        notes: `Market-data pipeline is ${pipelineMode}; run ${job.id} is queued and the last validated data remains available.`,
        jobId: job.id,
        status: "paused",
        pollAfterMs: 0,
      }, 202);
    } catch (error) {
      const code = error instanceof Error && "code" in error ? String(error.code) : "ops-db-unavailable";
      return c.json({ ok: false, page, error: code, message: "The paused pipeline request could not be recorded in OPS_DB." }, 503);
    }
  }
  try {
    const job = await requestRefreshJob(c.env, {
      page,
      ticker: body.ticker ?? null,
      requestedBy: "admin",
    });
    if ((page === "overview" || page === "market-commentary") && (job.status === "queued" || job.status === "running")) {
      c.executionCtx.waitUntil(processRefreshJobById(c.env, job.id));
    }
    return c.json({
      ok: true,
      page,
      refreshedTickers: job.result?.refreshedTickers ?? 0,
      notes: job.status === "completed"
        ? job.result?.notes ?? "Refresh completed."
        : "Refresh queued; work will continue in the market-data lane.",
      jobId: job.id,
      status: job.status,
      pollAfterMs: page === "market-commentary" ? 5000 : 1500,
      generationId: job.result?.generationId,
      publishedAt: job.result?.publishedAt,
      currentCoveragePct: job.result?.currentCoveragePct,
      historyExactCoveragePct: job.result?.historyExactCoveragePct,
      historyUsableCoveragePct: job.result?.historyUsableCoveragePct,
      canonicalSession: job.result?.canonicalSession,
      historyRefreshStatus: job.result?.historyRefreshStatus,
      historyErrorCode: job.result?.historyErrorCode,
      historyNextAttemptAt: job.result?.historyNextAttemptAt,
      publicationStatus: job.result?.publicationStatus,
      publicationNextAttemptAt: job.result?.publicationNextAttemptAt,
      publicationErrorCode: job.result?.publicationErrorCode,
      publicationError: job.result?.publicationError,
      reportId: job.result?.reportId,
      sessionDate: job.result?.sessionDate,
    }, 202);
  } catch (error) {
    const message = error instanceof Error ? error.message : "Refresh queue is temporarily unavailable.";
    console.error("admin refresh queue request failed", { page, error });
    return c.json({
      ok: false,
      page,
      refreshedTickers: 0,
      notes: `Refresh could not be queued (${message}). Existing ${page} data remains available.`,
      jobId: null,
      status: "failed",
      pollAfterMs: 0,
    }, 200);
  }
});

app.get("/api/admin/refresh-jobs/:jobId", async (c) => {
  if (!isAuthed(c.req.raw, c.env)) return c.json({ error: "Unauthorized" }, 401);
