         (feed, ticker, date, o, h, l, c, volume, source_provider, adjustment, observed_at, fetched_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'manual-upload', 'split', NULL, CURRENT_TIMESTAMP)
       ON CONFLICT(feed, ticker, date) DO UPDATE SET
         o = excluded.o,
         h = excluded.h,
         l = excluded.l,
         c = excluded.c,
         volume = excluded.volume,
         source_provider = excluded.source_provider,
         adjustment = excluded.adjustment,
         observed_at = NULL,
         fetched_at = CURRENT_TIMESTAMP
       WHERE alpaca_daily_bars.o IS NOT excluded.o
          OR alpaca_daily_bars.h IS NOT excluded.h
          OR alpaca_daily_bars.l IS NOT excluded.l
          OR alpaca_daily_bars.c IS NOT excluded.c
          OR alpaca_daily_bars.volume IS NOT excluded.volume
          OR alpaca_daily_bars.source_provider IS NOT excluded.source_provider`,
    ).bind(feed, r.ticker.toUpperCase(), r.date, r.o, r.h, r.l, r.c, r.volume ?? 0),
  );
  await db.batch(statements);
  await refreshSnapshotSafe(c.env);
  return c.json({ ok: true, upserted: rows.length });
});

app.post("/api/admin/reorder", async (c) => {
  if (!isAuthed(c.req.raw, c.env)) return c.json({ error: "Unauthorized" }, 401);
  const body = (await c.req.json()) as { type: "group" | "item"; orderedIds: string[] };
  if (body.type === "item" && body.orderedIds.length > 0) {
    const placeholders = body.orderedIds.map(() => "?").join(", ");
    const themedRows = await c.env.DB.prepare(
      `SELECT DISTINCT g.title as groupTitle
       FROM dashboard_items i
       JOIN dashboard_groups g ON g.id = i.group_id
       WHERE i.id IN (${placeholders})`,
    )
      .bind(...body.orderedIds)
      .all<{ groupTitle: string | null }>();
    if ((themedRows.results ?? []).some((row) => row.groupTitle === "Industry/Thematic ETFs" || row.groupTitle === "Thematic ETFs")) {
      return c.json({ error: "Industry/Thematic ETFs is managed from ETF Universe." }, 409);
    }
  }
  const table = body.type === "group" ? "dashboard_groups" : "dashboard_items";
  const stmts = body.orderedIds.map((id, i) =>
    c.env.DB.prepare(`UPDATE ${table} SET sort_order = ? WHERE id = ?`).bind(i + 1, id),
  );
  if (stmts.length > 0) await c.env.DB.batch(stmts);
  await upsertAudit(c.env, "default", "REORDER", body);
  await refreshSnapshotSafe(c.env);
  return c.json({ ok: true });
});

app.get("/api/admin/audit", async (c) => {
  if (!isAuthed(c.req.raw, c.env)) return c.json({ error: "Unauthorized" }, 401);
  const rows = await c.env.DB.prepare(
    "SELECT id, action, actor, payload_json as payloadJson, created_at as createdAt FROM config_audit ORDER BY created_at DESC LIMIT 50",
  ).all();
  return c.json({ rows: rows.results ?? [] });
});

async function syncMonthlyEtfSlice(env: Env, settings?: CronJobValues): Promise<void> {
  if (settings && !isCentralCronEnabled(settings)) return;
  const selected = await loadDueEtfRefreshTickers(env.DB, {
    staleDays: cronNumber(settings ?? {}, "staleDays", ETF_HOLDINGS_REFRESH_DAYS),
    batchLimit: cronNumber(settings ?? {}, "batchLimit", 5),
  });
  for (const ticker of selected) {
    try {
      await syncEtfConstituents(env, ticker);
    } catch (error) {
      console.error("scheduled etf constituent sync failed", ticker, error);
    }
  }
}

function isOverviewGenerationSlot(now: Date): boolean {
  const ny = zonedParts(now, "America/New_York");
  return ny.minutesOfDay >= 4 * 60
    && ny.minutesOfDay <= 16 * 60 + 45
    && ny.minutesOfDay % 15 === 0;
}

function isPremarketGappersSlot(now: Date): boolean {
  const ny = zonedParts(now, "America/New_York");
  return ny.minutesOfDay >= 4 * 60
    && ny.minutesOfDay <= 9 * 60 + 30
    && ny.minutesOfDay % 10 === 0;
}

function isPeerMetricSlot(now: Date): boolean {
  return zonedParts(now, "America/New_York").minutesOfDay % 30 === 0;
}

async function refreshScheduledPeerMetricSlice(env: Env): Promise<void> {
  const rows = await env.DB.prepare(
    `SELECT DISTINCT s.ticker, s.exchange
       FROM ticker_peer_groups tpg
       JOIN peer_groups pg ON pg.id = tpg.peer_group_id AND pg.is_active = 1
       JOIN symbols s ON s.ticker = tpg.ticker
       LEFT JOIN peer_metric_cache pmc ON pmc.ticker = s.ticker
      ORDER BY CASE WHEN pmc.as_of IS NULL THEN 0 ELSE 1 END,
               datetime(COALESCE(pmc.as_of, '1970-01-01')) ASC,
               s.ticker ASC
      LIMIT 80`,
  ).all<{ ticker: string; exchange: string | null }>();
  if ((rows.results ?? []).length > 0) await refreshPeerMetrics(env, rows.results ?? []);
}

async function publishScheduledBreadthIfReady(env: Env, asOfDate: string): Promise<void> {
  await publishReadyBreadthUniverses(env, asOfDate);
}

export default {
  queue: async (batch: MessageBatch<unknown>, env: Env): Promise<void> => {
    if (env.EOD_RUNTIME_CANDIDATE_ONLY === "true") throw new Error("Runtime candidate cannot consume production queues.");
    return consumeScannerCacheWakeUps(batch, env);
  },
  fetch: async (request: Request, env?: Env, ctx?: ExecutionContext): Promise<Response> => {
    if (!env) return app.fetch(request, env, ctx);
    const path = new URL(request.url).pathname;
    const probe = isEodRuntimeHttpProbe(request, env);
    if (!probe && (env.EOD_RUNTIME_CANDIDATE_ONLY === "true" || path === EOD_RUNTIME_COORDINATOR_PATH)) {
      return Response.json({ error: "Not found." }, { status: 404 });
    }
    if (!probe) return app.fetch(request, env, ctx);
    try {
      return await runEodRuntimeProbe(env, path === EOD_RUNTIME_COORDINATOR_PATH ? "coordinator" : "http", path,
        async (observed) => {
          if (path === EOD_RUNTIME_COORDINATOR_PATH) {
            await coordinateEod(observed);
            return Response.json({ ok: true });
          }
          return app.fetch(request, observed, ctx);
        });
    } catch {
      return Response.json({ error: "Runtime probe failed; inspect bounded probe evidence." }, { status: 503 });
    }
  },
  email: async (message: any, env: Env): Promise<void> => {
    if (env.EOD_RUNTIME_CANDIDATE_ONLY === "true") return;
    await handleInboundTradingViewEmail(message, env);
  },
  scheduled: async (event: ScheduledEvent, env: Env, _ctx?: ExecutionContext): Promise<void> => {
    if (env.EOD_RUNTIME_CANDIDATE_ONLY === "true") return;
    await refreshEodAccountUsageHeartbeat(env, new Date(event.scheduledTime || Date.now())).catch(() => {
      console.error("eod-account-heartbeat-unavailable");
    });
    const cronSettings = await loadCentralCronJobSettingsMap(env).catch((error) => {
      console.error("scheduled cron settings load failed; using defaults", error);
      return new Map<string, CronJobValues>();
    });
    const cron = (key: string) => cronSettings.get(key);
    const now = new Date(event.scheduledTime || Date.now());
    const triggerLane = classifyScheduledCron(event.cron);
    const lanesToRun = scheduledLanesForCron(event.cron);
    type ScheduledJobMetadata = Record<string, unknown>;
    type ScheduledLaneRunner = {
      budget: ScheduledBudget;
      runBudgeted: (jobKey: string, units: number, task: () => Promise<void>, metadata?: ScheduledJobMetadata) => Promise<void>;
      auditSkipped: (jobKey: string, reason: string, metadata?: ScheduledJobMetadata) => Promise<void>;
    };
    const laneRunners = new Map<ScheduledLane, ScheduledLaneRunner>();
    const runnerForLane = (jobLane: ScheduledLane): ScheduledLaneRunner => {
      const existing = laneRunners.get(jobLane);
      if (existing) return existing;
      const laneBudget = createScheduledBudget(env, jobLane);
      const auditSkipped = async (jobKey: string, reason: string, metadata: ScheduledJobMetadata = {}): Promise<void> => {
        const skippedAuditId = await startScheduledJobRun(env, {
          lane: jobLane,
          cron: event.cron,
          jobKey,
          scheduledTime: now.toISOString(),
          metadata: { ...metadata, budget: laneBudget.snapshot() },
        });
        await finishScheduledJobRun(env, skippedAuditId, "skipped", reason, { ...metadata, budget: laneBudget.snapshot() });
      };
      const runBudgeted = async (jobKey: string, units: number, task: () => Promise<void>, metadata: ScheduledJobMetadata = {}): Promise<void> => {
        if (!laneBudget.claim(jobKey, units)) {
          await auditSkipped(jobKey, "Skipped by scheduled budget.", { ...metadata, estimatedUnits: units });
          return;
        }
        const auditId = await startScheduledJobRun(env, {
          lane: jobLane,
          cron: event.cron,
          jobKey,
          scheduledTime: now.toISOString(),
          metadata: { ...metadata, estimatedUnits: units, budget: laneBudget.snapshot() },
        });
        try {
          await task();
          await finishScheduledJobRun(env, auditId, "completed", null, { ...metadata, budget: laneBudget.snapshot() });
        } catch (error) {
          const message = error instanceof Error ? error.message : `Scheduled ${jobKey} failed.`;
          await finishScheduledJobRun(env, auditId, "failed", message, { ...metadata, budget: laneBudget.snapshot() });
          console.error(`scheduled ${jobKey} failed`, { lane: jobLane, error });
        }
      };
      const runner = { budget: laneBudget, runBudgeted, auditSkipped };
      laneRunners.set(jobLane, runner);
      return runner;
    };
    const budgetSnapshots = () => Object.fromEntries(
      [...laneRunners.entries()].map(([jobLane, runner]) => [jobLane, runner.budget.snapshot()]),
    );

    const runScheduledSocialAlertScrapeJob = async (): Promise<void> => {
      const runner = runnerForLane("scans");
      const decision = await planScheduledSocialAlertScrape(env, now);
      const metadata = {
        localDate: decision.localDate ?? null,
        scheduledLocalSlot: decision.scheduledLocalSlot ?? null,
        existingRunId: decision.existingRunId ?? null,
        existingRunStatus: decision.existingRunStatus ?? null,
        existingRunStartedAt: decision.existingRunStartedAt ?? null,
      };
      if (decision.skipped) {
        const reason = decision.reason === "already_ran"
          ? "Social alert scrape already ran for scheduled slot."
          : "Social alert scrape not due.";
        await runner.auditSkipped("social-alert-scrape", reason, { ...metadata, decisionReason: decision.reason ?? "not_due" });
        return;
      }
      await runner.runBudgeted("social-alert-scrape", 8, async () => {
        await runPlannedScheduledSocialAlertScrape(env, decision);
      }, metadata);
    };

    const runMaintenanceLane = async (): Promise<void> => {
      const { runBudgeted } = runnerForLane("maintenance");
      if (now.getUTCHours() === 0 && now.getUTCMinutes() < 15) {
        await runBudgeted("database-capacity-sample", 2, () => sampleDatabaseCapacity(env, now).then(() => undefined));
        await runBudgeted("freshness-housekeeping", 2, async () => {
          await cleanupProviderUsage(env, now);
          await cleanupRefreshJobs(env, now);
        });
      }
      await runBudgeted("alerts-housekeeping", 4, () => maybeRunAlertsHousekeeping(env, cron("alerts-housekeeping")));
      await runBudgeted("social-alerts-housekeeping", 4, () => maybeRunSocialAlertsHousekeeping(env, cron("social-alerts-housekeeping")));
      await runBudgeted("scans-page-housekeeping", 4, () => maybeRunScansPageHousekeeping(env, cron("scans-page-housekeeping")));
      await runBudgeted("scanning-housekeeping", 4, () => maybeRunScanningHousekeeping(env, cron("scanning-housekeeping")));
      await runBudgeted("gappers-housekeeping", 4, () => maybeRunGappersHousekeeping(env, cron("gappers-housekeeping")));
      await runBudgeted("options-housekeeping", 4, () => maybeRunOptionsHousekeeping(env, cron("options-housekeeping")).then(() => undefined));
    };

    const runCoreLane = async (): Promise<void> => {
      const { runBudgeted } = runnerForLane("core");
      await runBudgeted("research-queue", 8, async () => {
        const settings = cron("research-queue");
        if (!settings || isCentralCronEnabled(settings)) {
          await advanceResearchQueue(env, cronNumber(settings ?? {}, "batchLimit", 2));
        }
      });
      await runBudgeted("watchlist-compiles", 8, () => runDueWatchlistCompiles(env, now).then(() => undefined));
      await runBudgeted("earnings-calendar", 8, () => maybeRunScheduledEarningsCalendarSync(env, now, cron("earnings-calendar")).then(() => undefined));
      await runBudgeted("earnings-surprises", 8, () => maybeRunScheduledEarningsSurpriseSync(env, now, cron("earnings-surprises")).then(() => undefined));
      await runBudgeted("earnings-gaps", 8, () => maybeRunScheduledEarningsGapSync(env, now, cron("earnings-gaps")).then(() => undefined));
      await runBudgeted("earnings-fundamentals-refresh", 8, async () => {
        const settings = cron("earnings-fundamentals-refresh");
        if (!settings || isCentralCronEnabled(settings)) {
          await processDueEarningsFundamentalRefreshes(env, { limit: cronNumber(settings ?? {}, "batchLimit", 5), now });
        }
      });
      await runBudgeted("fundamentals-seed-queue", 8, async () => {
        const settings = cron("fundamentals-seed-queue");
        if (!settings || isCentralCronEnabled(settings)) {
          await maybeProcessFundamentalSeedQueue(env, { limit: cronNumber(settings ?? {}, "batchLimit", 10), now });
        }
      });
    };

    const runMarketDataLane = async (): Promise<void> => {
      const runner = runnerForLane("market-data");
      const { runBudgeted, auditSkipped, budget } = runner;
      if (eodEnabled(env) || env.EOD_STORAGE_MIGRATION_ID) {
        await runBudgeted("eod-coordinate", 4, () => coordinateEod(env,now));
        await runBudgeted("eod-commentary",6,() => maybeRunPublishedEodCommentary(env,now).then(() => undefined));
      }
      if (env.EOD_RUNNER_MODE === "active") {
        if (await hasClaimableRefreshJob(env,now)) await runBudgeted("refresh-job",8,() => processNextRefreshJob(env));
        if (isPeerMetricSlot(now)) await runBudgeted("peer-metric-slice",6,() => refreshScheduledPeerMetricSlice(env).then(() => undefined));
        if (isPremarketGappersSlot(now)) await runBudgeted("gappers-snapshot",8,() => refreshGappersSnapshot(env,50).then(() => undefined));
        await runBudgeted("symbol-catalog-sync",6,() => maybeRunScheduledSymbolCatalogSync(env,now).then(() => undefined));
        await runBudgeted("etf-constituent-slice",10,() => syncMonthlyEtfSlice(env,cron("etf-constituent-slice")));
        return;
      }
      const pipelineMode = marketPipelineMode(env);
      if (pipelineMode !== "active") {
        await auditSkipped(
          "market-data-pipeline",
          `Market-data pipeline is ${pipelineMode}; scheduled provider and publication work is disabled.`,
          { pipelineMode },
        );
        return;
      }
      const workerSchedule = await loadWorkerScheduleSettings(env);
      const postClosePlan = await planPostCloseBudgetProtection(env, now, workerSchedule);
      const overviewCurrentBudgetUnits = 12;
      const postCloseDailyBarsBudgetUnits = 24;
      const canFitPostCloseDailyBars = budget.canClaim(postCloseDailyBarsBudgetUnits);
      const canFitBothCriticalJobs = budget.canClaim(overviewCurrentBudgetUnits + postCloseDailyBarsBudgetUnits);
      const postCloseMetadata: ScheduledJobMetadata = {
        expectedTradingDate: postClosePlan.expectedTradingDate,
        postCloseReason: postClosePlan.reason,
      };

      // Membership sources publish daily. Use one dedicated UTC window rather
      // than rechecking them on every five-minute market-data tick.
      if (now.getUTCHours() === 23 && now.getUTCMinutes() < 5) {
        await runBudgeted(
          "universe-membership-refresh",
          4,
          () => refreshBreadthUniverseMemberships(env).then(() => undefined),
        );
      }

      if (await hasClaimableRefreshJob(env, now)) {
        await runBudgeted("refresh-job", 8, () => processNextRefreshJob(env).then(() => undefined));
      } else {
        await auditSkipped("refresh-job", "No refresh job is due.");
      }

      const recoveryEnabled = isOverviewPublicationRecoveryEnabled(env);
      const overviewSessionDate = latestUsMarketSessionAsOfDate(now);
      const currentJob = recoveryEnabled
        ? await loadOverviewCurrentRefreshJob(env, "default", overviewSessionDate).catch(() => null)
        : null;
      const recoveryCurrentActionable = recoveryEnabled
        && currentRefreshContinuationAllowed(currentJob, overviewSessionDate, now);
      const recoveryPublicationEligible = recoveryEnabled
        && Boolean(currentJob?.cycleId)
        && await isOverviewCurrentRefreshPublicationReady(env, "default", overviewSessionDate);
      let overviewCurrentRan = false;
      let reconciliationAttempted = false;
      let recoveryResult: Awaited<ReturnType<typeof reconcileOverviewPublication>> | null = null;
      const runOverviewCurrent = async (): Promise<void> => {
        overviewCurrentRan = true;
        await runBudgeted(
          "overview-current-data",
          overviewCurrentBudgetUnits,
          () => maybeRunScheduledOverviewCurrentRefresh(env, now).then(() => undefined),
        );
      };
      const runOverviewReconciliation = async (): Promise<void> => {
        reconciliationAttempted = true;
        await runBudgeted("overview-snapshot", 10, async () => {
          recoveryResult = await reconcileOverviewPublication(env, now, "default");
        });
      };

      if (recoveryEnabled && (recoveryCurrentActionable || recoveryPublicationEligible)) {
        if (recoveryCurrentActionable) await runOverviewCurrent();
        await runOverviewReconciliation();
      }

      if (postClosePlan.protect) {
        await runBudgeted(
          "post-close-daily-bars",
          postCloseDailyBarsBudgetUnits,
          async () => {
            const result = await maybeRunScheduledPostCloseDailyBarRefresh(env, now, workerSchedule);
            if (result) {
              Object.assign(postCloseMetadata, {
                jobId: result.id,
                sessionDate: result.tradingDate,
                feed: result.sourceFeed,
                requestEnd: result.requestEnd,
                exactProcessedTickers: result.currentDateTickers,
                exactRemainingTickers: result.missingCurrentDateTickers,
                exactCoveragePct: result.currentDateCoveragePct,
                rowsFetched: result.fetchedRows,
                rowsWritten: result.writtenRows,
                errorCode: result.errorCode,
                nextAttemptAt: result.nextAttemptAt,
                stopReason: result.status,
              });
            }
            if (result?.status === "failed") {
              throw new Error(
                `Post-close daily bars failed for ${result.tradingDate}: ${result.errorCode ?? "unknown-error"}.`,
              );
            }
          },
          postCloseMetadata,
        );
      } else {
        await auditSkipped(
          "post-close-daily-bars",
          "Skipped because post-close daily bars are not actionable.",
          postCloseMetadata,
        );
      }
      if (!overviewCurrentRan && postClosePlan.protect && canFitPostCloseDailyBars && !canFitBothCriticalJobs) {
        await auditSkipped(
          "overview-current-data",
          "Skipped to preserve market-data budget for actionable post-close daily bars.",
          postCloseMetadata,
        );
      } else if (!overviewCurrentRan) {
        await runOverviewCurrent();
      }
      if (recoveryEnabled && !reconciliationAttempted) {
        await runOverviewReconciliation();
      }
      await runBudgeted(
        "breadth-publication",
        6,
        () => publishScheduledBreadthIfReady(env, latestUsMarketSessionAsOfDate(now)).then(() => undefined),
      );
      if (!recoveryEnabled && isOverviewGenerationSlot(now)) {
        if (!await isOverviewCurrentRefreshPublicationReady(env, "default", overviewSessionDate)) {
          await auditSkipped(
            "overview-snapshot",
            "Skipped until the bounded current-data refresh cycle completes.",
            { sessionDate: overviewSessionDate },
          );
        } else {
          await runBudgeted("overview-snapshot", 10, async () => {
            try {
              await computeAndStoreSnapshot(env, overviewSessionDate, "default", {
                includeBreadth: false,
              });
            } catch (error) {
              if (!(error instanceof OverviewFreshnessError)) throw error;
              console.warn("scheduled overview candidate retained last-ready generation", error.diagnostics);
            }
          });
        }
      }
      if (recoveryEnabled) {
        const state = recoveryResult ?? await loadOverviewRecovery(env, now, "default");
        await auditOverviewFreshnessState(env, now, state, "default");
      }
      if (isPeerMetricSlot(now)) {
        await runBudgeted("peer-metric-slice", 6, () => refreshScheduledPeerMetricSlice(env).then(() => undefined));
      }
      if (isPremarketGappersSlot(now)) {
        await runBudgeted("gappers-snapshot", 8, () => refreshGappersSnapshot(env, 50).then(() => undefined));
      }
      await runBudgeted("symbol-catalog-sync", 6, () => maybeRunScheduledSymbolCatalogSync(env, now).then(() => undefined));
      await runBudgeted("etf-constituent-slice", 10, () => syncMonthlyEtfSlice(env, cron("etf-constituent-slice")));
    };

    const runScansLane = async (): Promise<void> => {
      const { runBudgeted } = runnerForLane("scans");
      const workerSchedule = await loadWorkerScheduleSettings(env);
      await runBudgeted("scanner-cache-scan-continuation", 12, () => reconcileScannerCacheRuns(env, {
        maxBatches: workerSchedule.rsBackgroundMaxBatchesPerTick,
        batchSize: workerSchedule.rsBackgroundBatchSize,
        timeBudgetMs: workerSchedule.rsBackgroundTimeBudgetMs,
      }));
      if (workerSchedule.rsBackgroundEnabled) {
        await runBudgeted("relative-strength-post-close-precompute", 6, () =>
          planScheduledRelativeStrengthPrecompute(env, now, workerSchedule).then(() => undefined));
      }
      await runScheduledSocialAlertScrapeJob();
      await runBudgeted("pattern-scan", 12, () => maybeRunScheduledPatternScan(env, now, workerSchedule).then(() => undefined));
    };

    const runReportsLane = async (): Promise<void> => {
      const { runBudgeted } = runnerForLane("reports");
      if (await shouldRunScheduledFomcRefresh(env, now)) {
        await runBudgeted("fomc-commentary", 4, async () => {
          const result = await refreshLatestFomcCommentary(env, { now });
          if (result.warning) console.warn("scheduled FOMC commentary refresh warning", result.warning);
        });
      }

      await runBudgeted("fedwatch-snapshot", 4, () => getFedWatchSnapshot(env).then(() => undefined));
      await runBudgeted("market-commentary", 6, () => maybeRunScheduledMarketCommentary(env, now).then(() => undefined));

      await runBudgeted("weekly-market-review", 5, () => maybeRunScheduledWeeklyMarketReview(env, now).then(() => undefined));
    };

    const runLane = async (jobLane: ScheduledLane): Promise<void> => {
      if (jobLane === "maintenance") {
        await runMaintenanceLane();
      } else if (jobLane === "market-data") {
        await runMarketDataLane();
      } else if (jobLane === "scans") {
        await runScansLane();
      } else if (jobLane === "reports") {
        await runReportsLane();
      } else {
        await runCoreLane();
      }
    };

    console.log("scheduled worker lane started", { cron: event.cron, triggerLane, lanesToRun });
    for (const jobLane of lanesToRun) {
      await runLane(jobLane);
    }
    console.log("scheduled worker lane completed", { cron: event.cron, triggerLane, lanesToRun, budgets: budgetSnapshots() });
  },
};

